window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["ACT"]={"book":"ACT","editions":{"fin-biblia1776":[[1,1,"Ennen olen minä tosin, oi Teophilus, puhunut kaikista niistä, mitä Jesus rupesi sekä tekemään että opettamaan,","Ennen olen minä tosin, oi Teophilus, puhunut kaikista niistä, mitä Jesus rupesi sekä tekemään että opettamaan,"],[1,2,"Hamaan siihen päivään asti, jona hän otettiin ylös, sitte kuin hän apostoleille, jotka hän valinnut oli, Pyhän Hengen kautta oli käskyn antanut;","Hamaan siihen päivään asti, jona hän otettiin ylös, sitte kuin hän apostoleille, jotka hän valinnut oli, Pyhän Hengen kautta oli käskyn antanut;"],[1,3,"Joille hän myös kärsimisensä jälkeen oli itsensä eläväksi osoittanut moninaisilla merkeillä, ja näkyi heille neljäkymmentä päivää, ja puhui heille Jumalan valtakunnasta.","Joille hän myös kärsimisensä jälkeen oli itsensä eläväksi osoittanut moninaisilla merkeillä, ja näkyi heille neljäkymmentä päivää, ja puhui heille Jumalan valtakunnasta."],[1,4,"Ja kuin hän heidät oli koonnut, kielsi hän heitä lähtemästä Jerusalemista, vaan että he Isän lupausta odottaisivat, josta te olette (sanoi hän) kuulleet minulta.","Ja kuin hän heidät oli koonnut, kielsi hän heitä lähtemästä Jerusalemista, vaan että he Isän lupausta odottaisivat, josta te olette (sanoi hän) kuulleet minulta."],[1,5,"Sillä Johannes tosin kasti vedellä, mutta te kastetaan Pyhällä Hengellä, ei monen päivän perästä.","Sillä Johannes tosin kasti vedellä, mutta te kastetaan Pyhällä Hengellä, ei monen päivän perästä."],[1,6,"Kuin he siis kokoontuneet olivat, kysyivät he häneltä, sanoen: Herra, tällä ajallakos Israelille valtakunnan jälleen rakennat?","Kuin he siis kokoontuneet olivat, kysyivät he häneltä, sanoen: Herra, tällä ajallakos Israelille valtakunnan jälleen rakennat?"],[1,7,"Mutta hän sanoi heille: ei teidän tule tietää aikaa eikä hetkeä, jotka Isä on omaan voimaansa pannut.","Mutta hän sanoi heille: ei teidän tule tietää aikaa eikä hetkeä, jotka Isä on omaan voimaansa pannut."],[1,8,"Vaan teidän pitää saaman Pyhän Hengen voiman, joka on tuleva teidän päällenne, ja teidän pitää minun todistajani oleman, sekä Jerusalemissa, että koko Juudeassa ja Samariassa, ja sitte maailman ääreen.","Vaan teidän pitää saaman Pyhän Hengen voiman, joka on tuleva teidän päällenne, ja teidän pitää minun todistajani oleman, sekä Jerusalemissa, että koko Juudeassa ja Samariassa, ja sitte maailman ääreen."],[1,9,"Ja kuin hän nämät sanonut oli, otettiin hän ylös heidän nähtensä, ja pilvi vei hänen ylös heidän silmäinsä edestä.","Ja kuin hän nämät sanonut oli, otettiin hän ylös heidän nähtensä, ja pilvi vei hänen ylös heidän silmäinsä edestä."],[1,10,"Ja kuin he katselivat taivaaseen, hänen mennessänsä, katso, heidän tykönänsä seisoi kaksi miestä valkeissa vaatteissa,","Ja kuin he katselivat taivaaseen, hänen mennessänsä, katso, heidän tykönänsä seisoi kaksi miestä valkeissa vaatteissa,"],[1,11,"Jotka myös sanoivat: Galilean miehet, mitä te seisotte ja katsotte taivaasen? Tämä Jesus, joka teiltä otettiin ylös taivaasen, on niin tuleva kuin te hänen taivaasen menevän näitte.","Jotka myös sanoivat: Galilean miehet, mitä te seisotte ja katsotte taivaasen? Tämä Jesus, joka teiltä otettiin ylös taivaasen, on niin tuleva kuin te hänen taivaasen menevän näitte."],[1,12,"Silloin he palasivat Jerusalemiin vuorelta, joka Öljymäeksi kutsutaan ja on läsnä Jerusalemia sabbatin matkan.","Silloin he palasivat Jerusalemiin vuorelta, joka Öljymäeksi kutsutaan ja on läsnä Jerusalemia sabbatin matkan."],[1,13,"Ja kuin he tulivat sisälle, niin he astuivat ylös saliin, kussa he oleskelivat: Pietari ja Jakob, ja Johannes ja Andreas, Philippus ja Toomas, Bartolomeus ja Matteus, Jakob Alphein poika ja Simon Zelotes, ja Juudas Jakobin.","Ja kuin he tulivat sisälle, niin he astuivat ylös saliin, kussa he oleskelivat: Pietari ja Jakob, ja Johannes ja Andreas, Philippus ja Toomas, Bartolomeus ja Matteus, Jakob Alphein poika ja Simon Zelotes, ja Juudas Jakobin."],[1,14,"Nämät kaikki olivat yksimielisesti pysyväiset rukouksessa ja anomisessa, vaimoin kanssa ja Marian Jesuksen äidin ja hänen veljeinsä kanssa.","Nämät kaikki olivat yksimielisesti pysyväiset rukouksessa ja anomisessa, vaimoin kanssa ja Marian Jesuksen äidin ja hänen veljeinsä kanssa."],[1,15,"Ja niinä päivinä nousi Pietari opetuslasten keskellä ja sanoi: (ja joukko oli nimiltä yhteen lähes kaksikymmentä toista sataa:)","Ja niinä päivinä nousi Pietari opetuslasten keskellä ja sanoi: (ja joukko oli nimiltä yhteen lähes kaksikymmentä toista sataa:)"],[1,16,"Te miehet ja veljet! se kirjoitus piti täytettämän, jonka Pyhä Henki oli Davidin suun kautta Juudaasta ennen sanonut, joka niiden johdattajaksi tuli, jotka Jesuksen ottivat kiinni.","Te miehet ja veljet! se kirjoitus piti täytettämän, jonka Pyhä Henki oli Davidin suun kautta Juudaasta ennen sanonut, joka niiden johdattajaksi tuli, jotka Jesuksen ottivat kiinni."],[1,17,"Sillä hän oli meidän lukuumme luettu, ja oli tämän viran meidän kanssamme saanut.","Sillä hän oli meidän lukuumme luettu, ja oli tämän viran meidän kanssamme saanut."],[1,18,"Hän siis on ansainnut pellon vääryyden palkasta, ja kuin hän pudotettiin alas, on hän keskeltä kahtia pakahtunut, että kaikki hänen sisällyksensä läksivät ulos.","Hän siis on ansainnut pellon vääryyden palkasta, ja kuin hän pudotettiin alas, on hän keskeltä kahtia pakahtunut, että kaikki hänen sisällyksensä läksivät ulos."],[1,19,"Ja se oli tiettävä kaikille, jotka Jerusalemissa asuvat, että se pelto heidän kielellänsä kutsutaan Akeldama, se on: veripelto.","Ja se oli tiettävä kaikille, jotka Jerusalemissa asuvat, että se pelto heidän kielellänsä kutsutaan Akeldama, se on: veripelto."],[1,20,"Sillä se on kirjoitettu Psaltari-raamatussa: hänen kotonsa tulkoon kylmille eikä siinä pidä asujanta oleman, ja toisen pitää hänen piispautensa saaman.","Sillä se on kirjoitettu Psaltari-raamatussa: hänen kotonsa tulkoon kylmille eikä siinä pidä asujanta oleman, ja toisen pitää hänen piispautensa saaman."],[1,21,"Niin pitää näistä miehistä, jotka meidän kanssamme olleet ovat kaiken sen ajan kuin Herra Jesus meidän kanssamme ulos ja sisälle kävi,","Niin pitää näistä miehistä, jotka meidän kanssamme olleet ovat kaiken sen ajan kuin Herra Jesus meidän kanssamme ulos ja sisälle kävi,"],[1,22,"Ruveten Johanneksen kasteesta hamaan siihen päivään asti, jona hän meiltä otettiin ylös, yksi tuleman hänen ylösnousemisensa todistajaksi ynnä meidän kanssamme.","Ruveten Johanneksen kasteesta hamaan siihen päivään asti, jona hän meiltä otettiin ylös, yksi tuleman hänen ylösnousemisensa todistajaksi ynnä meidän kanssamme."],[1,23,"Ja he asettivat kaksi ehdolle: Josephin, joka kutsuttiin Barsabas ja liialta nimeltä Justus, ja Mattiaan.","Ja he asettivat kaksi ehdolle: Josephin, joka kutsuttiin Barsabas ja liialta nimeltä Justus, ja Mattiaan."],[1,24,"Ja he rukoilivat ja sanoivat: sinä Herra, joka kaikkein sydämet tiedät! osoita, kumman sinä näistä kahdesta olet valinnut,","Ja he rukoilivat ja sanoivat: sinä Herra, joka kaikkein sydämet tiedät! osoita, kumman sinä näistä kahdesta olet valinnut,"],[1,25,"Saamaan tämän palveluksen ja apostolin viran arpaa, josta Juudas on vilpistynyt pois, menemään pois siallensa.","Saamaan tämän palveluksen ja apostolin viran arpaa, josta Juudas on vilpistynyt pois, menemään pois siallensa."],[1,26,"Ja he heittivät heistä arpaa, ja arpa lankesi Mattiaan päälle, ja hän valittiin yksimielisesti yhdentoistakymmenen apostolin sekaan.","Ja he heittivät heistä arpaa, ja arpa lankesi Mattiaan päälle, ja hän valittiin yksimielisesti yhdentoistakymmenen apostolin sekaan."],[2,1,"Ja kuin viideskymmenes päivä täytettiin, olivat he kaikki yksimielisesti koossa.","Ja kuin viideskymmenes päivä täytettiin, olivat he kaikki yksimielisesti koossa."],[2,2,"Ja humaus tapahtui äkisti taivaasta, niinkuin suuri tuulispää olis tullut, ja täytti koko huoneen, kussa he olivat istumassa.","Ja humaus tapahtui äkisti taivaasta, niinkuin suuri tuulispää olis tullut, ja täytti koko huoneen, kussa he olivat istumassa."],[2,3,"Ja heille näkyivät viileskellyt kielet, niinkuin tuliset, ja istuivat kunkin heidän päällensä.","Ja heille näkyivät viileskellyt kielet, niinkuin tuliset, ja istuivat kunkin heidän päällensä."],[2,4,"Ja he täytettiin kaikki Pyhällä Hengellä ja rupesivat puhumaan muilla kielillä, senjälkeen kuin Henki antoi heidän puhua.","Ja he täytettiin kaikki Pyhällä Hengellä ja rupesivat puhumaan muilla kielillä, senjälkeen kuin Henki antoi heidän puhua."],[2,5,"Niin Jerusalemissa asui Juudalaisia, Jumalaa pelkääväisiä miehiä, kaikkinaisesta kansasta, joka taivaan alla on.","Niin Jerusalemissa asui Juudalaisia, Jumalaa pelkääväisiä miehiä, kaikkinaisesta kansasta, joka taivaan alla on."],[2,6,"Ja kuin tämä ääni tapahtui, niin kokoontui suuri kansan paljous, ja hämmästyivät; sillä kukin kuuli niiden puhuvan omalla kielellänsä.","Ja kuin tämä ääni tapahtui, niin kokoontui suuri kansan paljous, ja hämmästyivät; sillä kukin kuuli niiden puhuvan omalla kielellänsä."],[2,7,"Ja he tyhmistyivät kaikki ja ihmettelivät, sanoen keskenänsä: katso, eikö nämät kaikki, jotka puhuvat, ole Galilealaiset?","Ja he tyhmistyivät kaikki ja ihmettelivät, sanoen keskenänsä: katso, eikö nämät kaikki, jotka puhuvat, ole Galilealaiset?"],[2,8,"Ja kuinka me kukin kuulemme heidän puhuvan meidän omalla kielellämme, jossa me syntyneet olemme?","Ja kuinka me kukin kuulemme heidän puhuvan meidän omalla kielellämme, jossa me syntyneet olemme?"],[2,9,"Partilaiset ja Mediläiset ja Elamilaiset, ja jotka asumme Mesopotamiassa ja Juudeassa ja Kappadokiassa, Pontossa ja Asiassa,","Partilaiset ja Mediläiset ja Elamilaiset, ja jotka asumme Mesopotamiassa ja Juudeassa ja Kappadokiassa, Pontossa ja Asiassa,"],[2,10,"Phrygiassa ja Pamphiliassa, Egyptissä ja Libian maan rajoilla, liki Kyreniä, ja muukalaiset Roomista, Juudalaiset ja uudet Juudalaiset.","Phrygiassa ja Pamphiliassa, Egyptissä ja Libian maan rajoilla, liki Kyreniä, ja muukalaiset Roomista, Juudalaiset ja uudet Juudalaiset."],[2,11,"Kretalaiset ja Arabialaiset, me kuulemme heidän puhuvan meidän kielillämme Jumalan suuria tekoja.","Kretalaiset ja Arabialaiset, me kuulemme heidän puhuvan meidän kielillämme Jumalan suuria tekoja."],[2,12,"Niin he kaikki tyhmistyivät ja epäilivät, sanoen toinen toisellensa: mitäs luulet tämän olevan?","Niin he kaikki tyhmistyivät ja epäilivät, sanoen toinen toisellensa: mitäs luulet tämän olevan?"],[2,13,"Vaan muut nauroivat heitä ja sanoivat: he ovat täynnänsä makiaa viinaa.","Vaan muut nauroivat heitä ja sanoivat: he ovat täynnänsä makiaa viinaa."],[2,14,"Niin Pietari seisoi yhdentoistakymmenen kanssa, korotti äänensä ja puhui heille: te Juudan miehet ja kaikki, jotka asutte Jerusalemissa! tämä olkoon teille tiettävä, ja ottakaat minun sanani teidän korviinne.","Niin Pietari seisoi yhdentoistakymmenen kanssa, korotti äänensä ja puhui heille: te Juudan miehet ja kaikki, jotka asutte Jerusalemissa! tämä olkoon teille tiettävä, ja ottakaat minun sanani teidän korviinne."],[2,15,"Sillä ei nämät juovuksissa ole, niinkuin te luulette; sillä nyt on kolmas hetki päivästä.","Sillä ei nämät juovuksissa ole, niinkuin te luulette; sillä nyt on kolmas hetki päivästä."],[2,16,"Vaan tämä on se, mikä ennen sanottu on Joelin prophetan kautta:","Vaan tämä on se, mikä ennen sanottu on Joelin prophetan kautta:"],[2,17,"Ja pitää tapahtuman viimeisinä päivinä (sanoo Jumala), että minä tahdon vuodattaa minun Hengestäni kaiken lihan päälle: ja teidän poikanne ja tyttärenne pitää ennustaman, ja teidän nuorukaisenne pitää näkyjä näkemän, ja teidän vanhimpanne pitää unia uneksuman.","Ja pitää tapahtuman viimeisinä päivinä (sanoo Jumala), että minä tahdon vuodattaa minun Hengestäni kaiken lihan päälle: ja teidän poikanne ja tyttärenne pitää ennustaman, ja teidän nuorukaisenne pitää näkyjä näkemän, ja teidän vanhimpanne pitää unia uneksuman."],[2,18,"Ja myös minun palveliaini päälle ja minun piikaini päälle niinä päivinä vuodatan minä minun Hengestäni, ja heidän pitää ennustaman.","Ja myös minun palveliaini päälle ja minun piikaini päälle niinä päivinä vuodatan minä minun Hengestäni, ja heidän pitää ennustaman."],[2,19,"Ja minä annan tunnustähtiä ylhäällä taivaassa ja merkkejä alhaalla maan päällä, veren ja tulen ja savun ja suitsun.","Ja minä annan tunnustähtiä ylhäällä taivaassa ja merkkejä alhaalla maan päällä, veren ja tulen ja savun ja suitsun."],[2,20,"Auringon pitää muuttuman pimeydeksi ja kuun vereksi, ennenkuin se suuri ja julkinen Herran päivä on tuleva.","Auringon pitää muuttuman pimeydeksi ja kuun vereksi, ennenkuin se suuri ja julkinen Herran päivä on tuleva."],[2,21,"Ja pitää tapahtuman, että jokainen, joka avuksi huutaa Herran nimeä, se tulee autuaaksi.","Ja pitää tapahtuman, että jokainen, joka avuksi huutaa Herran nimeä, se tulee autuaaksi."],[2,22,"Te Israelin miehet! kuulkaat näitä sanoja: Jesuksen Natsarelaisen, sen miehen, joka teidän tykönänne on Jumalalta vahvistettu voimallisten tekoin, ihmetten ja merkkein kanssa, jotka Jumala hänen kauttansa teidän keskellänne teki, niinkuin te itsekin tiedätte,","Te Israelin miehet! kuulkaat näitä sanoja: Jesuksen Natsarelaisen, sen miehen, joka teidän tykönänne on Jumalalta vahvistettu voimallisten tekoin, ihmetten ja merkkein kanssa, jotka Jumala hänen kauttansa teidän keskellänne teki, niinkuin te itsekin tiedätte,"],[2,23,"Sen, joka Jumalan aivotun neuvon ja säännön jälkeen oli annettu ulos, te otitte ja vääräin miesten kätten kautta ristiinnaulitsitte ja surmasitte,","Sen, joka Jumalan aivotun neuvon ja säännön jälkeen oli annettu ulos, te otitte ja vääräin miesten kätten kautta ristiinnaulitsitte ja surmasitte,"],[2,24,"Jonka Jumala herätti ylös ja päästi kuoleman kivuista, että se oli mahdotoin, että hän piti siltä pidettämän.","Jonka Jumala herätti ylös ja päästi kuoleman kivuista, että se oli mahdotoin, että hän piti siltä pidettämän."],[2,25,"Sillä David sanoo hänestä: minä olen aina Herran minun kasvoini eteen pannut, sillä hän on minun oikialla puolellani, etten minä horjahtaisi.","Sillä David sanoo hänestä: minä olen aina Herran minun kasvoini eteen pannut, sillä hän on minun oikialla puolellani, etten minä horjahtaisi."],[2,26,"Sentähden iloitsi minun sydämeni, ja minun kieleni riemuitsi, ja minun lihani on myös lepäävä toivossa.","Sentähden iloitsi minun sydämeni, ja minun kieleni riemuitsi, ja minun lihani on myös lepäävä toivossa."],[2,27,"Sillä et sinä anna ylön minun sieluani helvetissä, etkä salli sinun pyhäs näkevän turmelusta.","Sillä et sinä anna ylön minun sieluani helvetissä, etkä salli sinun pyhäs näkevän turmelusta."],[2,28,"Sinä olet minulle tiettäväksi tehnyt elämän tiet, sinä täytät minun ilolla sinun kasvois edessä.","Sinä olet minulle tiettäväksi tehnyt elämän tiet, sinä täytät minun ilolla sinun kasvois edessä."],[2,29,"Te miehet, rakkaat veljet, olkoon lupa rohkiasti teille puhua patriarkasta Davidista! hän on sekä kuollut että haudattu ja hänen hautansa on meidän tykönämme hamaan tähän päivään asti:","Te miehet, rakkaat veljet, olkoon lupa rohkiasti teille puhua patriarkasta Davidista! hän on sekä kuollut että haudattu ja hänen hautansa on meidän tykönämme hamaan tähän päivään asti:"],[2,30,"Että hän siis oli propheta ja tiesi Jumalan hänelle valalla vannoneen, että hän oli hänen kupeensa hedelmästä lihan jälkeen herättävä Kristuksen hänen istuimellansa istumaan,","Että hän siis oli propheta ja tiesi Jumalan hänelle valalla vannoneen, että hän oli hänen kupeensa hedelmästä lihan jälkeen herättävä Kristuksen hänen istuimellansa istumaan,"],[2,31,"Näki hän ennen ja puhui Kristuksen ylösnousemisesta, ettei hänen sieluansa annettu ylön helvetissä, eikä hänen lihansa nähnyt turmelusta.","Näki hän ennen ja puhui Kristuksen ylösnousemisesta, ettei hänen sieluansa annettu ylön helvetissä, eikä hänen lihansa nähnyt turmelusta."],[2,32,"Tämän Jesuksen on Jumala herättänyt, jonka todistajat me kaikki olemme.","Tämän Jesuksen on Jumala herättänyt, jonka todistajat me kaikki olemme."],[2,33,"Hän on siis Jumalan oikialle kädelle korotettu ja on Isältä saanut lupauksen Pyhästä Hengestä: hän on tämän vuodattanut, kuin te nyt näette ja kuulette.","Hän on siis Jumalan oikialle kädelle korotettu ja on Isältä saanut lupauksen Pyhästä Hengestä: hän on tämän vuodattanut, kuin te nyt näette ja kuulette."],[2,34,"Sillä ei David ole taivaasen astunut, vaan hän sanoo: Herra sanoi minun Herralleni: istu minun oikialle kädelleni,","Sillä ei David ole taivaasen astunut, vaan hän sanoo: Herra sanoi minun Herralleni: istu minun oikialle kädelleni,"],[2,35,"Siihenasti kuin minä panen sinun vihollises sinun jalkais astinlaudaksi.","Siihenasti kuin minä panen sinun vihollises sinun jalkais astinlaudaksi."],[2,36,"Niin pitää siis totisesti kaiken Israelin huoneen tietämän, että Jumala on tämän Jesuksen, jonka te ristiinnaulitsitte, Herraksi ja Kristukseksi tehnyt.","Niin pitää siis totisesti kaiken Israelin huoneen tietämän, että Jumala on tämän Jesuksen, jonka te ristiinnaulitsitte, Herraksi ja Kristukseksi tehnyt."],[2,37,"Mutta kuin he nämät kuulivat, kävi se läpi heidän sydämensä, ja sanoivat Pietarille ja muille apostoleille: te miehet, rakkaat veljet! mitä meidän pitää tekemän?","Mutta kuin he nämät kuulivat, kävi se läpi heidän sydämensä, ja sanoivat Pietarille ja muille apostoleille: te miehet, rakkaat veljet! mitä meidän pitää tekemän?"],[2,38,"Vaan Pietari sanoi heille: tehkäät parannus, ja antakaan jokainen itsensä kastaa Jesuksen Kristuksen nimeen, syntein anteeksi antamiseksi, niin te saatte Pyhän Hengen lahjan.","Vaan Pietari sanoi heille: tehkäät parannus, ja antakaan jokainen itsensä kastaa Jesuksen Kristuksen nimeen, syntein anteeksi antamiseksi, niin te saatte Pyhän Hengen lahjan."],[2,39,"Sillä teille ja teidän lapsillenne on tämä lupaus annettu, ja kaikille, jotka taampana ovat, kutka ikänä Herra meidän Jumalamme kutsuu.","Sillä teille ja teidän lapsillenne on tämä lupaus annettu, ja kaikille, jotka taampana ovat, kutka ikänä Herra meidän Jumalamme kutsuu."],[2,40,"Ja monilla muillakin sanoilla todisti hän, ja neuvoi heitä, sanoen: antakaat teitänne autettaa tästä pahanilkisestä suvusta.","Ja monilla muillakin sanoilla todisti hän, ja neuvoi heitä, sanoen: antakaat teitänne autettaa tästä pahanilkisestä suvusta."],[2,41,"Jotka siis mielellänsä hänen sanansa ottivat vastaan, ne kastettiin; ja sinä päivänä lisääntyi lähes kolmetuhatta sielua.","Jotka siis mielellänsä hänen sanansa ottivat vastaan, ne kastettiin; ja sinä päivänä lisääntyi lähes kolmetuhatta sielua."],[2,42,"Ja he pysyivät alati apostolien opissa ja osallisuudessa, ja leivän murtamisessa ja rukouksissa.","Ja he pysyivät alati apostolien opissa ja osallisuudessa, ja leivän murtamisessa ja rukouksissa."],[2,43,"Mutta jokaiselle sielulle tuli pelko; ja tehtiin apostolien kautta monta ihmettä ja merkkiä.","Mutta jokaiselle sielulle tuli pelko; ja tehtiin apostolien kautta monta ihmettä ja merkkiä."],[2,44,"Mutta kaikki, jotka uskoivat, olivat yhdessä ja pitivät kaikki yhteisenä.","Mutta kaikki, jotka uskoivat, olivat yhdessä ja pitivät kaikki yhteisenä."],[2,45,"Ja he myivät hyvyytensä ja tavaransa, ja jakoivat ne kaikille, sen jälkeen kuin kukin tarvitsi.","Ja he myivät hyvyytensä ja tavaransa, ja jakoivat ne kaikille, sen jälkeen kuin kukin tarvitsi."],[2,46,"Ja he pysyivät joka päivä yksimielisesti templissä, ja mursivat huoneessa leipää, ja ottivat ruokaa riemulla ja sydämen yksinkertaisuudella,","Ja he pysyivät joka päivä yksimielisesti templissä, ja mursivat huoneessa leipää, ja ottivat ruokaa riemulla ja sydämen yksinkertaisuudella,"],[2,47,"Ja kiittäin Jumalaa olivat kaiken kansan suosiossa. Ja Herra lisäsi joka päivä autuaaksi tulevaisia seurakunnalle.","Ja kiittäin Jumalaa olivat kaiken kansan suosiossa. Ja Herra lisäsi joka päivä autuaaksi tulevaisia seurakunnalle."],[3,1,"Niin Pietari ja Johannes menivät ynnä ylös templiin yhdeksännellä rukouksen hetkelle,","Niin Pietari ja Johannes menivät ynnä ylös templiin yhdeksännellä rukouksen hetkelle,"],[3,2,"Ja mies, saattamatoin hamasta äitinsä kohdusta, kannettiin; jonka he panivat joka päivä sen templin oven eteen, joka kutsutaan Kauniiksi, anomaan niiltä almua, jotka templiin menivät.","Ja mies, saattamatoin hamasta äitinsä kohdusta, kannettiin; jonka he panivat joka päivä sen templin oven eteen, joka kutsutaan Kauniiksi, anomaan niiltä almua, jotka templiin menivät."],[3,3,"Kuin hän näki Pietarin ja Johanneksen tahtovan mennä templiin, anoi hän heiltä almua.","Kuin hän näki Pietarin ja Johanneksen tahtovan mennä templiin, anoi hän heiltä almua."],[3,4,"Niin Pietari Johanneksen kanssa katsoi hänen päällensä, ja sanoi: katso meidän päällemme.","Niin Pietari Johanneksen kanssa katsoi hänen päällensä, ja sanoi: katso meidän päällemme."],[3,5,"Ja hän katseli heidän päällensä, toivoen heiltä jotakin saavansa.","Ja hän katseli heidän päällensä, toivoen heiltä jotakin saavansa."],[3,6,"Niin Pietari sanoi: hopiaa ja kultaa ei minulla ole; vaan sitä mitä minulla on, annan minä sinulle: Jesuksen Kristuksen Natsarealaisen nimeen nouse ja käy.","Niin Pietari sanoi: hopiaa ja kultaa ei minulla ole; vaan sitä mitä minulla on, annan minä sinulle: Jesuksen Kristuksen Natsarealaisen nimeen nouse ja käy."],[3,7,"Ja hän tarttui hänen oikiaan käteensä ja ojensi hänen, ja kohta hänen säärensä ja kantansa vahvistuivat.","Ja hän tarttui hänen oikiaan käteensä ja ojensi hänen, ja kohta hänen säärensä ja kantansa vahvistuivat."],[3,8,"Ja hän karkasi ylös, seisoi ja kävi, ja meni heidän kanssansa templiin, käyden ja hypäten ja kiittäen Jumalaa.","Ja hän karkasi ylös, seisoi ja kävi, ja meni heidän kanssansa templiin, käyden ja hypäten ja kiittäen Jumalaa."],[3,9,"Ja kaikki kansa näki hänen käyvän ja kiittävän Jumalaa,","Ja kaikki kansa näki hänen käyvän ja kiittävän Jumalaa,"],[3,10,"Ja tunsi hänen siksi, joka almun tähden istui templin Kauniin oven edessä; ja he olivat täynnänsä pelkoa ja suurta hämmästystä siitä, mitä hänelle tapahtunut oli.","Ja tunsi hänen siksi, joka almun tähden istui templin Kauniin oven edessä; ja he olivat täynnänsä pelkoa ja suurta hämmästystä siitä, mitä hänelle tapahtunut oli."],[3,11,"Mutta kuin tämä saattamatoin, joka parannettu oli, piti itsensä Pietarin ja Johanneksen tykö, juoksi kaikki kansa hämmästyksissä heidän tykönsä porstuaan, joka kutsutaan Salomon porstuaksi.","Mutta kuin tämä saattamatoin, joka parannettu oli, piti itsensä Pietarin ja Johanneksen tykö, juoksi kaikki kansa hämmästyksissä heidän tykönsä porstuaan, joka kutsutaan Salomon porstuaksi."],[3,12,"Kuin Pietari sen näki, vastasi hän kansalle: Israelin miehet! mitä te tätä ihmettelette? eli mitä te meidän päällemme katsotte, niinkuin me olisimme meidän omalla voimallamme eli jumalisuudellamme tämän käymään saattaneet?","Kuin Pietari sen näki, vastasi hän kansalle: Israelin miehet! mitä te tätä ihmettelette? eli mitä te meidän päällemme katsotte, niinkuin me olisimme meidän omalla voimallamme eli jumalisuudellamme tämän käymään saattaneet?"],[3,13,"Abrahamin ja Isaakin ja Jakobin Jumala, meidän isäimme Jumala, on Poikansa Jesuksen kirkastanut, jonka te annoitte ylön ja kielsitte Pilatuksen edessä, kuin hän tuomitsi, että hän piti päästettämän.","Abrahamin ja Isaakin ja Jakobin Jumala, meidän isäimme Jumala, on Poikansa Jesuksen kirkastanut, jonka te annoitte ylön ja kielsitte Pilatuksen edessä, kuin hän tuomitsi, että hän piti päästettämän."],[3,14,"Mutta te kielsitte pyhän ja hurskaan, ja anoitte teillenne murhamiestä annettaa;","Mutta te kielsitte pyhän ja hurskaan, ja anoitte teillenne murhamiestä annettaa;"],[3,15,"Mutta elämän Pääruhtinaan te tapoitte: sen on Jumala kuolleista herättänyt, jonka todistajat me olemme.","Mutta elämän Pääruhtinaan te tapoitte: sen on Jumala kuolleista herättänyt, jonka todistajat me olemme."],[3,16,"Ja uskon kautta hänen nimensä päälle on hän tässä, jonka te näette ja tunnette, nimensä vahvistanut: ja usko hänen kauttansa antoi tälle terveytensä, kaikkein teidän nähtenne.","Ja uskon kautta hänen nimensä päälle on hän tässä, jonka te näette ja tunnette, nimensä vahvistanut: ja usko hänen kauttansa antoi tälle terveytensä, kaikkein teidän nähtenne."],[3,17,"Ja nyt rakkaat veljet! minä tiedän, että te sen tyhmyydestä tehneet olette, niinkuin teidän ylimmäisennekin.","Ja nyt rakkaat veljet! minä tiedän, että te sen tyhmyydestä tehneet olette, niinkuin teidän ylimmäisennekin."],[3,18,"Mutta Jumala, mitä hän kaikkein prophetainsa suun kautta oli ennustanut, että hänen Kristuksensa piti kärsimän, sen hän täytti.","Mutta Jumala, mitä hän kaikkein prophetainsa suun kautta oli ennustanut, että hänen Kristuksensa piti kärsimän, sen hän täytti."],[3,19,"Niin tehkäät parannus ja palatkaat, että teidän syntinne pyyhittäisiin pois, kuin virvoittamisen ajat tulevat Herran kasvoin edestä,","Niin tehkäät parannus ja palatkaat, että teidän syntinne pyyhittäisiin pois, kuin virvoittamisen ajat tulevat Herran kasvoin edestä,"],[3,20,"Ja hän lähettää sen, josta teille ennen saarnattu on, Jesuksen Kristuksen,","Ja hän lähettää sen, josta teille ennen saarnattu on, Jesuksen Kristuksen,"],[3,21,"Jonka tosin tulee omistaa taivas, niihin aikoihin asti kuin ne kaikki jälleen asetetaan, mitkä Jumala on puhunut kaikkein pyhäin prophetainsa suun kautta, hamasta maailman alusta.","Jonka tosin tulee omistaa taivas, niihin aikoihin asti kuin ne kaikki jälleen asetetaan, mitkä Jumala on puhunut kaikkein pyhäin prophetainsa suun kautta, hamasta maailman alusta."],[3,22,"Sillä Moses on tosin isille sanonut: Herra teidän Jumalanne on teille herättävä Prophetan teidän veljistänne, niinkuin minun: kuulkaat häntä kaikissa, mitä hän teille sanoo,","Sillä Moses on tosin isille sanonut: Herra teidän Jumalanne on teille herättävä Prophetan teidän veljistänne, niinkuin minun: kuulkaat häntä kaikissa, mitä hän teille sanoo,"],[3,23,"Ja pitää tapahtuman, että jokainen sielu, joka ei tätä Prophetaa kuule, pitää hävitettämän pois kansasta.","Ja pitää tapahtuman, että jokainen sielu, joka ei tätä Prophetaa kuule, pitää hävitettämän pois kansasta."],[3,24,"Ja kaikki prophetat hamasta Samuelista, ja sitte edespäin, niin monta, jotka puhuneet ovat, ovat myös kaikki näitä päiviä ennustaneet.","Ja kaikki prophetat hamasta Samuelista, ja sitte edespäin, niin monta, jotka puhuneet ovat, ovat myös kaikki näitä päiviä ennustaneet."],[3,25,"Te olette prophetain ja sen liiton lapset, jonka Jumala meidän isäimme kanssa teki, sanoen Abrahamille: ja sinun siemenessäs pitää kaikki kansat maan päällä siunattaman.","Te olette prophetain ja sen liiton lapset, jonka Jumala meidän isäimme kanssa teki, sanoen Abrahamille: ja sinun siemenessäs pitää kaikki kansat maan päällä siunattaman."],[3,26,"Teille on Jumala ensin Poikansa Jesuksen herättänyt ja on hänen lähettänyt teitä siunaamaan, että te kukin teidän pahuudestanne palajaisitte.","Teille on Jumala ensin Poikansa Jesuksen herättänyt ja on hänen lähettänyt teitä siunaamaan, että te kukin teidän pahuudestanne palajaisitte."],[4,1,"Mutta kuin he kansalle puhuivat, niin papit ja templin esimies ja Saddukealaiset tulivat sinne,","Mutta kuin he kansalle puhuivat, niin papit ja templin esimies ja Saddukealaiset tulivat sinne,"],[4,2,"Ja närkästyivät, että he kansaa opettivat ja ilmoittivat Jesuksen kautta ylösnousemisen kuolleista,","Ja närkästyivät, että he kansaa opettivat ja ilmoittivat Jesuksen kautta ylösnousemisen kuolleista,"],[4,3,"Ja heittivät kätensä heidän päällensä ja panivat heidät huomeneksi kiinni; sillä jo oli ehtoo.","Ja heittivät kätensä heidän päällensä ja panivat heidät huomeneksi kiinni; sillä jo oli ehtoo."],[4,4,"Mutta monta niistä, jotka sanan kuulivat, uskoivat ja miesten luku tuli lähes viisituhatta.","Mutta monta niistä, jotka sanan kuulivat, uskoivat ja miesten luku tuli lähes viisituhatta."],[4,5,"Mutta toisena päivänä tapahtui, että heidän ylimmäisensä ja vanhimpansa kokoontuivat ja kirjanoppineet Jerusalemissa,","Mutta toisena päivänä tapahtui, että heidän ylimmäisensä ja vanhimpansa kokoontuivat ja kirjanoppineet Jerusalemissa,"],[4,6,"Ja Hannas ylimmäinen pappi, ja Kaiphas, ja Johannes, ja Aleksander, ja niin monta kuin ylimmäisten pappein suvusta oli,","Ja Hannas ylimmäinen pappi, ja Kaiphas, ja Johannes, ja Aleksander, ja niin monta kuin ylimmäisten pappein suvusta oli,"],[4,7,"Ja asettivat heidät keskellensä ja kysyivät heiltä: millä voimalla taikka kenenkä nimeen te olette tämän tehneet?","Ja asettivat heidät keskellensä ja kysyivät heiltä: millä voimalla taikka kenenkä nimeen te olette tämän tehneet?"],[4,8,"Niin Pietari, täynnänsä Pyhää Henkeä, sanoi heille: te kansan ylimmäiset ja Israelin vanhimmat!","Niin Pietari, täynnänsä Pyhää Henkeä, sanoi heille: te kansan ylimmäiset ja Israelin vanhimmat!"],[4,9,"Jos me tänäpänä tuomitaan sen hyvän työn edestä sille sairaalle miehelle, jonka kautta hän parannettu on,","Jos me tänäpänä tuomitaan sen hyvän työn edestä sille sairaalle miehelle, jonka kautta hän parannettu on,"],[4,10,"Niin olkoon teille ja kaikelle Israelin kansalle tiettävä, että Jesuksen Kristuksen Natsarealaisen nimeen, jonka te ristiinnaulitsitte, jonka Jumala kuolleista herätti, sen kautta tämä seisoo teidän edessänne terveenä.","Niin olkoon teille ja kaikelle Israelin kansalle tiettävä, että Jesuksen Kristuksen Natsarealaisen nimeen, jonka te ristiinnaulitsitte, jonka Jumala kuolleista herätti, sen kautta tämä seisoo teidän edessänne terveenä."],[4,11,"Hän on se kivi, joka teiltä rakentajilta hyljätty on, joka on nurkkakiveksi tullut.","Hän on se kivi, joka teiltä rakentajilta hyljätty on, joka on nurkkakiveksi tullut."],[4,12,"Ja ei yhdessäkään toisessa ole autuutta; sillä ei myös ole muuta nimeä taivaan alla ihmisille annettu, jossa meidän pitää autuaaksi tuleman.","Ja ei yhdessäkään toisessa ole autuutta; sillä ei myös ole muuta nimeä taivaan alla ihmisille annettu, jossa meidän pitää autuaaksi tuleman."],[4,13,"Mutta kuin he näkivät Pietarin ja Johanneksen puheen rohkeuden, sillä he ymmärsivät heidät oppimattomiksi ja kirjantaitamattomiksi miehiksi, ihmettelivät he ja tunsivat heidät, että he Jesuksen kanssa olleet olivat.","Mutta kuin he näkivät Pietarin ja Johanneksen puheen rohkeuden, sillä he ymmärsivät heidät oppimattomiksi ja kirjantaitamattomiksi miehiksi, ihmettelivät he ja tunsivat heidät, että he Jesuksen kanssa olleet olivat."],[4,14,"Mutta kuin he näkivät sen ihmisen seisovan heidän kanssansa, joka parannettu oli, ei he taitaneet mitään sitä vastaan puhua.","Mutta kuin he näkivät sen ihmisen seisovan heidän kanssansa, joka parannettu oli, ei he taitaneet mitään sitä vastaan puhua."],[4,15,"Mutta he käskivät heitä ulos raadista mennä pois, ja pitivät neuvoa keskenänsä,","Mutta he käskivät heitä ulos raadista mennä pois, ja pitivät neuvoa keskenänsä,"],[4,16,"Sanoen: mitä me näille miehille teemme? Sillä julkinen merkki on heidän kauttansa tehty, joka kaikille Jerusalemin asuvaisille tiettävä on, ja emme taida kieltää.","Sanoen: mitä me näille miehille teemme? Sillä julkinen merkki on heidän kauttansa tehty, joka kaikille Jerusalemin asuvaisille tiettävä on, ja emme taida kieltää."],[4,17,"Mutta ettei se enempi kansan keskelle hajoisi, niin haastakaamme heitä kovin, ettei he tästedes yhdellekään ihmiselle tästä nimestä puhuisi.","Mutta ettei se enempi kansan keskelle hajoisi, niin haastakaamme heitä kovin, ettei he tästedes yhdellekään ihmiselle tästä nimestä puhuisi."],[4,18,"Ja he kutsuivat heidät ja kaiketi kielsivät heitä puhumasta ja opettamasta Jesuksen nimeen.","Ja he kutsuivat heidät ja kaiketi kielsivät heitä puhumasta ja opettamasta Jesuksen nimeen."],[4,19,"Mutta Pietari ja Johannes vastasivat heitä ja sanoivat: tuomitkaat itse, jos se on oikia Jumalan edessä, että me teitä enemmän kuulemme kuin Jumalaa.","Mutta Pietari ja Johannes vastasivat heitä ja sanoivat: tuomitkaat itse, jos se on oikia Jumalan edessä, että me teitä enemmän kuulemme kuin Jumalaa."],[4,20,"Sillä emme taida niitä puhumatta olla, joita me nähneet ja kuulleet olemme.","Sillä emme taida niitä puhumatta olla, joita me nähneet ja kuulleet olemme."],[4,21,"Mutta he uhkasivat heitä, ja antoivat heidän mennä, ja ei löytäneet mitään, josta he olisivat heitä vaivanneet, kansan tähden; sillä kaikki kiittivät Jumalaa sen edestä mikä tapahtunut oli.","Mutta he uhkasivat heitä, ja antoivat heidän mennä, ja ei löytäneet mitään, josta he olisivat heitä vaivanneet, kansan tähden; sillä kaikki kiittivät Jumalaa sen edestä mikä tapahtunut oli."],[4,22,"Sillä se ihminen oli ylitse neljänkymmenen ajastajan vanha, jossa tämä parantamisen tunnusmerkki tehty oli.","Sillä se ihminen oli ylitse neljänkymmenen ajastajan vanha, jossa tämä parantamisen tunnusmerkki tehty oli."],[4,23,"Mutta kuin he päästetyt olivat, tulivat he omainsa tykö ja ilmoittivat, mitä pappein päämiehet ja vanhimmat heille sanoneet olivat.","Mutta kuin he päästetyt olivat, tulivat he omainsa tykö ja ilmoittivat, mitä pappein päämiehet ja vanhimmat heille sanoneet olivat."],[4,24,"Kuin he sen kuulivat, korottivat he yksimielisesti äänensä Jumalan tykö ja sanoivat: Herra, sinä olet Jumala, joka taivaan ja maan ja meren, ja kaikki, mitä niissä on, tehnyt olet,","Kuin he sen kuulivat, korottivat he yksimielisesti äänensä Jumalan tykö ja sanoivat: Herra, sinä olet Jumala, joka taivaan ja maan ja meren, ja kaikki, mitä niissä on, tehnyt olet,"],[4,25,"Joka Davidin sinun palvelias suun kautta puhunut olet: miksi pakanat kiukuitsevat ja kansat turhaa aikovat?","Joka Davidin sinun palvelias suun kautta puhunut olet: miksi pakanat kiukuitsevat ja kansat turhaa aikovat?"],[4,26,"Vaan kuninkaat yhteen menevät ja päämiehet kokoovat heitänsä Herraa vastaan ja hänen Kristustansa vastaan?","Vaan kuninkaat yhteen menevät ja päämiehet kokoovat heitänsä Herraa vastaan ja hänen Kristustansa vastaan?"],[4,27,"Sillä he ovat tosin kokoontuneet sinun pyhää Poikaas Jesusta vastaan, jonka sinä voitelit, sekä Herodes että Pontius Pilatus pakanain ja Israelin kansan kanssa,","Sillä he ovat tosin kokoontuneet sinun pyhää Poikaas Jesusta vastaan, jonka sinä voitelit, sekä Herodes että Pontius Pilatus pakanain ja Israelin kansan kanssa,"],[4,28,"Tekemään mitä sinun kätes ja neuvos ennen aikonut oli, että tapahtuman pitäis.","Tekemään mitä sinun kätes ja neuvos ennen aikonut oli, että tapahtuman pitäis."],[4,29,"Ja nyt Herra, katso heidän uhkaustansa ja anna sinun palveliais kaikella uskalluksella sinun sanaas puhua.","Ja nyt Herra, katso heidän uhkaustansa ja anna sinun palveliais kaikella uskalluksella sinun sanaas puhua."],[4,30,"Ja ojenna kätes parantamaan, ja että merkit ja ihmeet sinun pyhän Poikas Jesuksen nimen kautta tehtäisiin.","Ja ojenna kätes parantamaan, ja että merkit ja ihmeet sinun pyhän Poikas Jesuksen nimen kautta tehtäisiin."],[4,31,"Ja kuin he rukoilleet olivat, liikkui se paikka, jossa he koossa olivat, ja he täytettiin kaikki Pyhällä Hengellä ja puhuivat Jumalan sanaa uskalluksella.","Ja kuin he rukoilleet olivat, liikkui se paikka, jossa he koossa olivat, ja he täytettiin kaikki Pyhällä Hengellä ja puhuivat Jumalan sanaa uskalluksella."],[4,32,"Ja niiden paljoudessa, jotka uskoivat, oli yksi sydän ja yksi sielu, ei myös kenkään heistä sanonut mitään omaksensa, mitä hänellä oli, vaan kaikki olivat heillä yhteiset.","Ja niiden paljoudessa, jotka uskoivat, oli yksi sydän ja yksi sielu, ei myös kenkään heistä sanonut mitään omaksensa, mitä hänellä oli, vaan kaikki olivat heillä yhteiset."],[4,33,"Ja apostolit todistivat suurella voimalla Herran Jesuksen ylösnousemisesta, ja suuri armo oli kaikkein heidän päällänsä.","Ja apostolit todistivat suurella voimalla Herran Jesuksen ylösnousemisesta, ja suuri armo oli kaikkein heidän päällänsä."],[4,34,"Ja ei myös ollut yhtään tarvitsevaa heissä; sillä niin monta, joilla pellot eli huoneet olivat, ne myivät ja toivat myytyin hinnan,","Ja ei myös ollut yhtään tarvitsevaa heissä; sillä niin monta, joilla pellot eli huoneet olivat, ne myivät ja toivat myytyin hinnan,"],[4,35,"Ja panivat apostolien jalkain eteen: ja jokaiselle jaettiin niinkuin kukin tarvitsi.","Ja panivat apostolien jalkain eteen: ja jokaiselle jaettiin niinkuin kukin tarvitsi."],[4,36,"Mutta Joses, joka liialta nimeltä apostoleilta kutsutaan Barnabas (se on niin paljo sanottu kuin lohdutuksen poika) Leviläinen, Kypristä sukuisin,","Mutta Joses, joka liialta nimeltä apostoleilta kutsutaan Barnabas (se on niin paljo sanottu kuin lohdutuksen poika) Leviläinen, Kypristä sukuisin,"],[4,37,"Hänellä oli pelto, sen hän myi, ja toi hinnan ja pani apostolitten jalkain eteen.","Hänellä oli pelto, sen hän myi, ja toi hinnan ja pani apostolitten jalkain eteen."],[5,1,"Mutta mies, Ananias nimeltä, emäntänsä Saphiran kanssa myi tavaransa,","Mutta mies, Ananias nimeltä, emäntänsä Saphiran kanssa myi tavaransa,"],[5,2,"Ja kätki jotain hinnasta emäntänsä tieten, ja toi osan edes ja pani apostolitten jalkain eteen.","Ja kätki jotain hinnasta emäntänsä tieten, ja toi osan edes ja pani apostolitten jalkain eteen."],[5,3,"Niin Pietari sanoi: Ananias, miksi saatana täytti sinun sydämes Pyhän Hengen edessä valhettelemaan, että jotakin pellon hinnasta kätkit?","Niin Pietari sanoi: Ananias, miksi saatana täytti sinun sydämes Pyhän Hengen edessä valhettelemaan, että jotakin pellon hinnasta kätkit?"],[5,4,"Etkös olisi saanut sitä pitää, kuin se sinulla oli, ja se myytykin oli sinun hallussas? miksis senkaltaista olet sydämees päästänyt? Et sinä ole ihmisten, vaan Jumalan edessä valehdellut.","Etkös olisi saanut sitä pitää, kuin se sinulla oli, ja se myytykin oli sinun hallussas? miksis senkaltaista olet sydämees päästänyt? Et sinä ole ihmisten, vaan Jumalan edessä valehdellut."],[5,5,"Kuin Ananias nämät sanat kuuli, lankesi hän maahan ja antoi henkensä. Ja suuri pelko tuli kaikkein niiden päälle, jotka tämän kuulivat.","Kuin Ananias nämät sanat kuuli, lankesi hän maahan ja antoi henkensä. Ja suuri pelko tuli kaikkein niiden päälle, jotka tämän kuulivat."],[5,6,"Niin nuoret miehet nousivat ja korjasivat hänen, veivät pois ja hautasivat hänen.","Niin nuoret miehet nousivat ja korjasivat hänen, veivät pois ja hautasivat hänen."],[5,7,"Mutta tapahtui liki kolmen hetken perästä, että myös hänen emäntänsä tuli sisälle eikä tietänyt, mitä tapahtunut oli.","Mutta tapahtui liki kolmen hetken perästä, että myös hänen emäntänsä tuli sisälle eikä tietänyt, mitä tapahtunut oli."],[5,8,"Niin Pietari vastasi häntä: sanos minulle: oletteko sen pellon siihen hintaan myyneet? mutta hän sanoi: olemme niinkin siihen hintaan.","Niin Pietari vastasi häntä: sanos minulle: oletteko sen pellon siihen hintaan myyneet? mutta hän sanoi: olemme niinkin siihen hintaan."],[5,9,"Sanoi Pietari hänelle: miksi te olette mielistyneet keskenänne Herran Henkeä kiusaamaan? Katso, niiden jalat, jotka sinun miehes hautasivat, ovat oven edessä ja vievät pois sinun.","Sanoi Pietari hänelle: miksi te olette mielistyneet keskenänne Herran Henkeä kiusaamaan? Katso, niiden jalat, jotka sinun miehes hautasivat, ovat oven edessä ja vievät pois sinun."],[5,10,"Ja hän kohta lankesi maahan hänen jalkainsa eteen ja antoi henkensä. Niin nuoret miehet tulivat sisälle ja löysivät hänen kuolleena, ja he veivät hänen ulos ja hautasivat miehensä tykö.","Ja hän kohta lankesi maahan hänen jalkainsa eteen ja antoi henkensä. Niin nuoret miehet tulivat sisälle ja löysivät hänen kuolleena, ja he veivät hänen ulos ja hautasivat miehensä tykö."],[5,11,"Ja suuri pelko tuli koko seurakunnalle ja kaikille niille, jotka tämän kuulivat.","Ja suuri pelko tuli koko seurakunnalle ja kaikille niille, jotka tämän kuulivat."],[5,12,"Ja apostolitten kätten kautta tehtiin monta merkkiä ja ihmettä kansan seassa. Ja olivat kaikki yksimielisesti Salomon esihuoneessa.","Ja apostolitten kätten kautta tehtiin monta merkkiä ja ihmettä kansan seassa. Ja olivat kaikki yksimielisesti Salomon esihuoneessa."],[5,13,"Mutta ei niistä muista uskaltanut yksikään itsiänsä antaa heidän sekaansa; vaan kansa piti paljon heistä.","Mutta ei niistä muista uskaltanut yksikään itsiänsä antaa heidän sekaansa; vaan kansa piti paljon heistä."],[5,14,"Ja joukko paljon eneni miehistä ja vaimoista, jotka Herran päälle uskoivat:","Ja joukko paljon eneni miehistä ja vaimoista, jotka Herran päälle uskoivat:"],[5,15,"Niin että he kantoivat sairaita kaduille ja panivat niitä vuoteille ja paareille, että Pietarin tullessa ainoasti hänen varjonsa jonkun heistä olis varjonnut.","Niin että he kantoivat sairaita kaduille ja panivat niitä vuoteille ja paareille, että Pietarin tullessa ainoasti hänen varjonsa jonkun heistä olis varjonnut."],[5,16,"Ja tuli myös suuri joukko kokoon lähimmäisistä kaupungeista Jerusalemiin, ja toviat sairaita ja saastaisilta hengiltä vaivatuita, jotka kaikki parannettiin.","Ja tuli myös suuri joukko kokoon lähimmäisistä kaupungeista Jerusalemiin, ja toviat sairaita ja saastaisilta hengiltä vaivatuita, jotka kaikki parannettiin."],[5,17,"Niin nousi ylimmäinen pappi, ja kaikki, jotka hänen kanssansa olivat, Saddukealaisten lahko, ja olivat täynnänsä kiivautta,","Niin nousi ylimmäinen pappi, ja kaikki, jotka hänen kanssansa olivat, Saddukealaisten lahko, ja olivat täynnänsä kiivautta,"],[5,18,"Ja paiskasivat kätensä apostolitten päälle ja panivat heidät yhteiseen vankihuoneesen.","Ja paiskasivat kätensä apostolitten päälle ja panivat heidät yhteiseen vankihuoneesen."],[5,19,"Mutta Herran enkeli avasi yöllä tornin oven, ja vei heidät sieltä ulos ja sanoi:","Mutta Herran enkeli avasi yöllä tornin oven, ja vei heidät sieltä ulos ja sanoi:"],[5,20,"Menkäät, seisokaat ja puhukaat templissä kansalle kaikki tämän elämän sanat.","Menkäät, seisokaat ja puhukaat templissä kansalle kaikki tämän elämän sanat."],[5,21,"Mutta kuin he sen kuulivat, menivät he varhain aamulla templiin ja opettivat. Niin ylimmäinen pappi tuli, ja ne, jotka hänen kanssansa olivat, kutsuivat raadin kokoon ja kaikki Israelin lasten vanhimmat, ja lähettivät vankihuoneesen heitä noutamaan.","Mutta kuin he sen kuulivat, menivät he varhain aamulla templiin ja opettivat. Niin ylimmäinen pappi tuli, ja ne, jotka hänen kanssansa olivat, kutsuivat raadin kokoon ja kaikki Israelin lasten vanhimmat, ja lähettivät vankihuoneesen heitä noutamaan."],[5,22,"Kuin palveliat menivät, eikä heitä tornista löytäneet, niin he palasivat ja ilmoittivat,","Kuin palveliat menivät, eikä heitä tornista löytäneet, niin he palasivat ja ilmoittivat,"],[5,23,"Sanoen: tornin me tosin löysimme kyllä visusti suljetuksi ja vartiat ulkona oven edessä seisovan; mutta kuin me sen avasimme, emme ketään sieltä löytäneet.","Sanoen: tornin me tosin löysimme kyllä visusti suljetuksi ja vartiat ulkona oven edessä seisovan; mutta kuin me sen avasimme, emme ketään sieltä löytäneet."],[5,24,"Kuin ylimmäinen pappi ja templin esimies ja pappein päämiehet nämät kuulivat, epäilivät he heistä, miksi se viimeinkin tulis.","Kuin ylimmäinen pappi ja templin esimies ja pappein päämiehet nämät kuulivat, epäilivät he heistä, miksi se viimeinkin tulis."],[5,25,"Niin tuli yksi ja ilmoitti heille, sanoen: katso, ne miehet, jotka te torniin panitte, ovat templissa ja seisovat opettamassa kansaa.","Niin tuli yksi ja ilmoitti heille, sanoen: katso, ne miehet, jotka te torniin panitte, ovat templissa ja seisovat opettamassa kansaa."],[5,26,"Niin esimies meni palvelijoinensa ja toi heidät suosiolla sieltä (sillä he pelkäsivät kansan heitä kivittävän).","Niin esimies meni palvelijoinensa ja toi heidät suosiolla sieltä (sillä he pelkäsivät kansan heitä kivittävän)."],[5,27,"Ja kuin he toivat heidät, asettivat he heidät raadin eteen. Ja ylimmäinen pappi kysyi heiltä,","Ja kuin he toivat heidät, asettivat he heidät raadin eteen. Ja ylimmäinen pappi kysyi heiltä,"],[5,28,"Sanoen: emmekö ole kovasti teitä kieltäneet puhumasta kansalle tähän nimeen? Ja katso, te olette Jerusalemin täyttäneet teidän opetuksellanne, ja tahdotte tämän ihmisen veren vetää meidän päällemme.","Sanoen: emmekö ole kovasti teitä kieltäneet puhumasta kansalle tähän nimeen? Ja katso, te olette Jerusalemin täyttäneet teidän opetuksellanne, ja tahdotte tämän ihmisen veren vetää meidän päällemme."],[5,29,"Mutta Pietari ja muut apostolit vastasivat ja sanoivat: enempi tulee kuulla Jumalaa kuin Ihmisiä.","Mutta Pietari ja muut apostolit vastasivat ja sanoivat: enempi tulee kuulla Jumalaa kuin Ihmisiä."],[5,30,"Meidän isäimme Jumala herätti Jesuksen, jonka te tapoitte ja ripustitte puuhun.","Meidän isäimme Jumala herätti Jesuksen, jonka te tapoitte ja ripustitte puuhun."],[5,31,"Sen on Jumala korottanut oikialle kädellensä Päämieheksi ja Vapahtajaksi, antamaan Israelille parannusta ja syntein anteeksi antamusta.","Sen on Jumala korottanut oikialle kädellensä Päämieheksi ja Vapahtajaksi, antamaan Israelille parannusta ja syntein anteeksi antamusta."],[5,32,"Ja me olemme näiden sanain todistajat, ja myös Pyhä Henki, jonka Jumala on niille antanut, jotka häntä kuulevat.","Ja me olemme näiden sanain todistajat, ja myös Pyhä Henki, jonka Jumala on niille antanut, jotka häntä kuulevat."],[5,33,"Mutta kuin he nämät kuulivat, kävi se lävitse heidän sydämensä, ja he pitivät neuvoa tappaaksensa heitä.","Mutta kuin he nämät kuulivat, kävi se lävitse heidän sydämensä, ja he pitivät neuvoa tappaaksensa heitä."],[5,34,"Niin nousi raadista yksi Pharisealainen, nimeltä Gamaliel, lainopettaja, josta kaikki kansa paljon piti: se käsi apostoleita pikimältänsä viedä ulos,","Niin nousi raadista yksi Pharisealainen, nimeltä Gamaliel, lainopettaja, josta kaikki kansa paljon piti: se käsi apostoleita pikimältänsä viedä ulos,"],[5,35,"Ja sanoi heille: Israelin miehet! kavahtakaat itseänne, mitä te mielitte tehdä näille miehille.","Ja sanoi heille: Israelin miehet! kavahtakaat itseänne, mitä te mielitte tehdä näille miehille."],[5,36,"Sillä ennen näitä päiviä nousi Teudas ja sanoi itsensä joksikin, niin hänen tykönsä tuli lähes neljäsataa miestä: joka sitte tapettiin ja kaikki, jotka häneen mielistyivät, ne hajoitettiin ja hävitettiin.","Sillä ennen näitä päiviä nousi Teudas ja sanoi itsensä joksikin, niin hänen tykönsä tuli lähes neljäsataa miestä: joka sitte tapettiin ja kaikki, jotka häneen mielistyivät, ne hajoitettiin ja hävitettiin."],[5,37,"Tämän jälkeen nousi Juudas Galileasta veronlaskemisen päivinä ja käänsi paljon kansaa jälkeensä; hän myös hukkui ja kaikki, jotka häneen mielistyivät, hajoitettiin.","Tämän jälkeen nousi Juudas Galileasta veronlaskemisen päivinä ja käänsi paljon kansaa jälkeensä; hän myös hukkui ja kaikki, jotka häneen mielistyivät, hajoitettiin."],[5,38,"Ja nyt sanon minä teille: lakatkaat näistä miehistä ja sallikaat heidän olla; sillä jos tämä neuvo eli teko on ihmisistä, niin se tyhjään raukee;","Ja nyt sanon minä teille: lakatkaat näistä miehistä ja sallikaat heidän olla; sillä jos tämä neuvo eli teko on ihmisistä, niin se tyhjään raukee;"],[5,39,"Vaan jos se on Jumalalta, niin ette voi sitä tyhjäksi tehdä, ettette myös löydettäisi sotineen jumalaa vastaan.","Vaan jos se on Jumalalta, niin ette voi sitä tyhjäksi tehdä, ettette myös löydettäisi sotineen jumalaa vastaan."],[5,40,"Niin kaikki mielistyivät hänen neuvoonsa; ja kuin he apostolit sisälle kutsuivat, niin he hosuivat heitä ja kielsivät heitä Jesuksen nimeen puhumasta, ja päästivät heidät menemään.","Niin kaikki mielistyivät hänen neuvoonsa; ja kuin he apostolit sisälle kutsuivat, niin he hosuivat heitä ja kielsivät heitä Jesuksen nimeen puhumasta, ja päästivät heidät menemään."],[5,41,"Niin he menivät pois raadin edestä, iloiten että he olivat mahdolliset pilkkaa kärsimään hänen nimensä tähden,","Niin he menivät pois raadin edestä, iloiten että he olivat mahdolliset pilkkaa kärsimään hänen nimensä tähden,"],[5,42,"Ja ei lakanneet joka päivä templissä ja joka huoneessa opettamasta ja saarnaamasta evankeliumia Jesuksesta Kristuksesta.","Ja ei lakanneet joka päivä templissä ja joka huoneessa opettamasta ja saarnaamasta evankeliumia Jesuksesta Kristuksesta."],[6,1,"Mutta niinä päivinä, koska opetuslasten luku eneni, napisivat Grekiläiset Hebrealaisia vastaan, että heidän leskensä katsottiin ylön jokapäiväisessä palveluksessa.","Mutta niinä päivinä, koska opetuslasten luku eneni, napisivat Grekiläiset Hebrealaisia vastaan, että heidän leskensä katsottiin ylön jokapäiväisessä palveluksessa."],[6,2,"Niin ne kaksi toistakymmentä kutsuivat kokoon opetuslasten joukon, ja sanoivat: ei se ole kohtuullinen, että me annamme ylön Jumalan sanan, ja pöytäin edessä palvelemme.","Niin ne kaksi toistakymmentä kutsuivat kokoon opetuslasten joukon, ja sanoivat: ei se ole kohtuullinen, että me annamme ylön Jumalan sanan, ja pöytäin edessä palvelemme."],[6,3,"Sentähden, rakkaat veljet, valitkaat teistä seitsemän miestä joista hyvä todistus on, jotka ovat Pyhää Henkeä ja viisautta täynnänsä, joiden haltuun me tämän viran annamme.","Sentähden, rakkaat veljet, valitkaat teistä seitsemän miestä joista hyvä todistus on, jotka ovat Pyhää Henkeä ja viisautta täynnänsä, joiden haltuun me tämän viran annamme."],[6,4,"Mutta me tahdomme rukouksessa ja sanan palveluksessa pysyväiset olla.","Mutta me tahdomme rukouksessa ja sanan palveluksessa pysyväiset olla."],[6,5,"Ja se puhe kelpasi kaikelle joukolle, ja he valitsivat Stephanin, miehen täynnä uskoa ja Pyhää Henkeä, ja Philippuksen, ja Prokoron, ja Nikanorin, ja Timonin, ja Parmenaan, ja Nikolaon, uuden Juudalaisen Antiokiasta.","Ja se puhe kelpasi kaikelle joukolle, ja he valitsivat Stephanin, miehen täynnä uskoa ja Pyhää Henkeä, ja Philippuksen, ja Prokoron, ja Nikanorin, ja Timonin, ja Parmenaan, ja Nikolaon, uuden Juudalaisen Antiokiasta."],[6,6,"Nämät he asettivat apostoleitten eteen: ja rukoilivat, ja panivat kätensä heidän päällensä.","Nämät he asettivat apostoleitten eteen: ja rukoilivat, ja panivat kätensä heidän päällensä."],[6,7,"Ja Jumalan sana kasvoi ja opetuslasten luku tuli sangen suureksi Jerusalemissa; ja suuri joukko pappeja oli myös uskolle kuuliainen.","Ja Jumalan sana kasvoi ja opetuslasten luku tuli sangen suureksi Jerusalemissa; ja suuri joukko pappeja oli myös uskolle kuuliainen."],[6,8,"Mutta Stephanus, joka oli uskoa täynnänsä ja väkevyyttä, teki ihmeitä ja suuria tunnustähtiä kansan seassa.","Mutta Stephanus, joka oli uskoa täynnänsä ja väkevyyttä, teki ihmeitä ja suuria tunnustähtiä kansan seassa."],[6,9,"Niin nousivat muutamat Libertinein synagogasta, ja Kyreniläisten, ja Aleksandrialaisten, ja jotka Kilikiasta ja Asiasta olivat, ja riitelivät Stephanin kanssa.","Niin nousivat muutamat Libertinein synagogasta, ja Kyreniläisten, ja Aleksandrialaisten, ja jotka Kilikiasta ja Asiasta olivat, ja riitelivät Stephanin kanssa."],[6,10,"Ja eivät voineet sitä viisautta vastaan olla ja sitä Henkeä, jonka kautta hän puhui.","Ja eivät voineet sitä viisautta vastaan olla ja sitä Henkeä, jonka kautta hän puhui."],[6,11,"Niin he sääsivät miehiä, jotka sanoivat: me olemme hänen kuulleet puhuvan pilkkasanoja Mosesta ja Jumalaa vastaan.","Niin he sääsivät miehiä, jotka sanoivat: me olemme hänen kuulleet puhuvan pilkkasanoja Mosesta ja Jumalaa vastaan."],[6,12,"Niin he yllyttivät kansan ja vanhimmat ja kirjanoppineet, ja menivät ja ottivat hänen kiinni, ja veivät hänen raadin eteen,","Niin he yllyttivät kansan ja vanhimmat ja kirjanoppineet, ja menivät ja ottivat hänen kiinni, ja veivät hänen raadin eteen,"],[6,13,"Ja asettivat väärät todistajat sanomaan: ei tämä mies lakkaa puhumasta pilkkasanoja tätä pyhää siaa ja lakia vastaan.","Ja asettivat väärät todistajat sanomaan: ei tämä mies lakkaa puhumasta pilkkasanoja tätä pyhää siaa ja lakia vastaan."],[6,14,"Sillä me olemme kuulleet hänen sanovan: Jesus Natsarealainen hävittää tämän sian, ja muuttaa säädyt, jotka Moses meille antoi.","Sillä me olemme kuulleet hänen sanovan: Jesus Natsarealainen hävittää tämän sian, ja muuttaa säädyt, jotka Moses meille antoi."],[6,15,"Ja kaikki ne, jotka raadissa istuivat, katsoivat hänen päällensä ja näkivät hänen kasvonsa niinkuin enkelin kasvot.","Ja kaikki ne, jotka raadissa istuivat, katsoivat hänen päällensä ja näkivät hänen kasvonsa niinkuin enkelin kasvot."],[7,1,"Niin ylimmäinen pappi sanoi: lienevätkö nämät näin?","Niin ylimmäinen pappi sanoi: lienevätkö nämät näin?"],[7,2,"Vaan hän sanoi: miehet, rakkaat veljet ja isät, kuulkaat: kunnian Jumala ilmestyi Abrahamille meidän isällemme, kuin hän oli Mesopotamiassa, ennenkuin hän Haranissa asui,","Vaan hän sanoi: miehet, rakkaat veljet ja isät, kuulkaat: kunnian Jumala ilmestyi Abrahamille meidän isällemme, kuin hän oli Mesopotamiassa, ennenkuin hän Haranissa asui,"],[7,3,"Ja sanoi hänelle: lähde sinun maaltas ja suvustas, ja tule siihen maahan, jonka minä sinulle osoitan.","Ja sanoi hänelle: lähde sinun maaltas ja suvustas, ja tule siihen maahan, jonka minä sinulle osoitan."],[7,4,"Silloin hän läksi Kaldeasta, ja asui Haranissa. Ja kuin hänen isänsä kuollut oli, toi hän hänen sieltä tähän maahan, jossa te nyt asutte.","Silloin hän läksi Kaldeasta, ja asui Haranissa. Ja kuin hänen isänsä kuollut oli, toi hän hänen sieltä tähän maahan, jossa te nyt asutte."],[7,5,"Ja ei antanut hänelle siinä perintöä, ei jalankaan leveyttä; ja hän lupasi hänelle sen antaa asuaksensa, ja hänen siemenellensä hänen jälkeensä, kuin ei hänellä vielä lasta ollut.","Ja ei antanut hänelle siinä perintöä, ei jalankaan leveyttä; ja hän lupasi hänelle sen antaa asuaksensa, ja hänen siemenellensä hänen jälkeensä, kuin ei hänellä vielä lasta ollut."],[7,6,"Ja Jumala puhui hänelle näin: sinun siemenes pitää oleman muukalainen vieraalla maalla, ja heidän pitää sen orjaksi tekemän, ja pahasti sen kanssa menemän neljäsataa ajastaikaa.","Ja Jumala puhui hänelle näin: sinun siemenes pitää oleman muukalainen vieraalla maalla, ja heidän pitää sen orjaksi tekemän, ja pahasti sen kanssa menemän neljäsataa ajastaikaa."],[7,7,"Ja sen kansan, jota he palvelevat, tahdon minä tuomita, sanoi Jumala, ja sitte pitää heidän lähtemän ja minua tässä siassa palveleman.","Ja sen kansan, jota he palvelevat, tahdon minä tuomita, sanoi Jumala, ja sitte pitää heidän lähtemän ja minua tässä siassa palveleman."],[7,8,"Ja hän antoi hänelle ympärileikkauksen liiton; ja niin hän siitti Isaakin, ja ympärileikkasi hänen kahdeksantena päivänä. Ja Isaak siitti Jakobin, ja Jakob kaksitoistakymmentä patriarkkaa.","Ja hän antoi hänelle ympärileikkauksen liiton; ja niin hän siitti Isaakin, ja ympärileikkasi hänen kahdeksantena päivänä. Ja Isaak siitti Jakobin, ja Jakob kaksitoistakymmentä patriarkkaa."],[7,9,"Ja ne patriarkat myivät kateudesta Josefin Egyptiin. Ja Jumala oli hänen kanssansa,","Ja ne patriarkat myivät kateudesta Josefin Egyptiin. Ja Jumala oli hänen kanssansa,"],[7,10,"Ja pelasti hänen kaikista tuskistansa, ja antoi hänelle armon ja viisauden Pharaon, Egyptin kuninkaan, kasvoin edessä, ja hän pani hänen Egyptin valtamieheksi ja kaiken huoneensa päälle.","Ja pelasti hänen kaikista tuskistansa, ja antoi hänelle armon ja viisauden Pharaon, Egyptin kuninkaan, kasvoin edessä, ja hän pani hänen Egyptin valtamieheksi ja kaiken huoneensa päälle."],[7,11,"Mutta nälkä tuli kaikkeen Egyptiin ja Kanaanin maahan, ja suuri tuska; ja ei meidän isämme löytäneet ravintoa.","Mutta nälkä tuli kaikkeen Egyptiin ja Kanaanin maahan, ja suuri tuska; ja ei meidän isämme löytäneet ravintoa."],[7,12,"Mutta kuin Jakob kuuli Egyptissä jyviä olevan, lähetti hän sinne meidän isämme ensimmäisen kerran.","Mutta kuin Jakob kuuli Egyptissä jyviä olevan, lähetti hän sinne meidän isämme ensimmäisen kerran."],[7,13,"Ja kuin hän toistamiseen heidät lähetti, tunnettiin Joseph veljiltänsä; ja Josephin suku tuli Pharaolle tiettäväksi.","Ja kuin hän toistamiseen heidät lähetti, tunnettiin Joseph veljiltänsä; ja Josephin suku tuli Pharaolle tiettäväksi."],[7,14,"Niin Joseph lähetti ja antoi tuoda isänsä Jakobin ja kaiken hänen sukunsa, viisi sielua kahdeksattakymmentä.","Niin Joseph lähetti ja antoi tuoda isänsä Jakobin ja kaiken hänen sukunsa, viisi sielua kahdeksattakymmentä."],[7,15,"Ja Jakob meni alas Egyptiin, ja hän kuoli, niin myös meidän isämme.","Ja Jakob meni alas Egyptiin, ja hän kuoli, niin myös meidän isämme."],[7,16,"Ja he vietiin Sikemiin ja pantiin siihen hautaan, jonka Abraham oli Hemorin lapsilta rahalla ostanut Sikemissä.","Ja he vietiin Sikemiin ja pantiin siihen hautaan, jonka Abraham oli Hemorin lapsilta rahalla ostanut Sikemissä."],[7,17,"Mutta kuin lupauksen aika lähestyi, josta Jumala oli Abrahamille vannonut, kasvoi ja eneni kansa Egyptissä,","Mutta kuin lupauksen aika lähestyi, josta Jumala oli Abrahamille vannonut, kasvoi ja eneni kansa Egyptissä,"],[7,18,"Siihenasti kuin toinen kuningas tuli, joka ei Josephista mitään tietänyt.","Siihenasti kuin toinen kuningas tuli, joka ei Josephista mitään tietänyt."],[7,19,"Tämä meidän sukuamme kavalasti juonitteli, ja meni pahasti meidän isäimme kanssa, niin että heidän piti nuoret lapsensa heittämän pois, ettei he olisi saaneet elää.","Tämä meidän sukuamme kavalasti juonitteli, ja meni pahasti meidän isäimme kanssa, niin että heidän piti nuoret lapsensa heittämän pois, ettei he olisi saaneet elää."],[7,20,"Siihen aikaan syntyi Moses, ja hän oli Jumalalle otollinen, ja elätettiin kolme kuukautta isänsä huoneessa.","Siihen aikaan syntyi Moses, ja hän oli Jumalalle otollinen, ja elätettiin kolme kuukautta isänsä huoneessa."],[7,21,"Mutta kuin hän heitetty oli ulos, otti Pharaon tytär hänen ja kasvatti itsellensä pojaksi.","Mutta kuin hän heitetty oli ulos, otti Pharaon tytär hänen ja kasvatti itsellensä pojaksi."],[7,22,"Ja Moses opetettiin kaikessa Egyptiläisten viisaudessa, ja oli voimallinen sanoissa ja töissä.","Ja Moses opetettiin kaikessa Egyptiläisten viisaudessa, ja oli voimallinen sanoissa ja töissä."],[7,23,"Mutta kuin hän oli neljänkymmenen ajastajan vanha, joukahtui hänen sydämeensä mennä katsomaan veljiänsä Israelin lapsia.","Mutta kuin hän oli neljänkymmenen ajastajan vanha, joukahtui hänen sydämeensä mennä katsomaan veljiänsä Israelin lapsia."],[7,24,"Ja kuin hän näki yhdelle vääryyttä tehtävän, autti hän häntä ja kosti hänen puolestansa, joka vääryyttä kärsi, ja löi Egyptin miehen.","Ja kuin hän näki yhdelle vääryyttä tehtävän, autti hän häntä ja kosti hänen puolestansa, joka vääryyttä kärsi, ja löi Egyptin miehen."],[7,25,"Mutta hän luuli veljiensä sen ymmärtävän, että Jumala hänen kätensä kautta oli heille vapauden antava; vaan eivät he ymmärtäneet.","Mutta hän luuli veljiensä sen ymmärtävän, että Jumala hänen kätensä kautta oli heille vapauden antava; vaan eivät he ymmärtäneet."],[7,26,"Ja hän tuli toisena päivänä heidän tykönsä, jotka keskenänsä riitelivät, ja sovitti heitä, sanoen: rakkaat miehet, te olette veljekset: miksi te toinen toisellenne vääryyttä teette?","Ja hän tuli toisena päivänä heidän tykönsä, jotka keskenänsä riitelivät, ja sovitti heitä, sanoen: rakkaat miehet, te olette veljekset: miksi te toinen toisellenne vääryyttä teette?"],[7,27,"Mutta se, joka lähimmäisellensä vääryyttä teki, lykkäsi häntä, sanoen: kuka sinun on pannut päämieheksi ja tuomariksi meidän ylitsemme?","Mutta se, joka lähimmäisellensä vääryyttä teki, lykkäsi häntä, sanoen: kuka sinun on pannut päämieheksi ja tuomariksi meidän ylitsemme?"],[7,28,"Vai tahdotkos sinä minua niin tappaa, kuin sinä Egyptiläisen eilen tapoit?","Vai tahdotkos sinä minua niin tappaa, kuin sinä Egyptiläisen eilen tapoit?"],[7,29,"Niin Moses pakeni tämän puheen tähden, ja oli Madiamin maakunnassa muukalainen, jossa hän kaksi poikaa siitti.","Niin Moses pakeni tämän puheen tähden, ja oli Madiamin maakunnassa muukalainen, jossa hän kaksi poikaa siitti."],[7,30,"Ja neljänkymmenen ajastajan perästä ilmestyi hänelle Herran enkeli korvessa, Sinain vuorella, pensaan tulen liekissä.","Ja neljänkymmenen ajastajan perästä ilmestyi hänelle Herran enkeli korvessa, Sinain vuorella, pensaan tulen liekissä."],[7,31,"Mutta kuin Moses sen näki, ihmetteli hän sitä näkyä, ja kuin hän meni lähes katsomaan, niin tapahtui Herran ääni hänelle:","Mutta kuin Moses sen näki, ihmetteli hän sitä näkyä, ja kuin hän meni lähes katsomaan, niin tapahtui Herran ääni hänelle:"],[7,32,"Minä olen sinun isäis Jumala, Abrahamin Jumala, ja Isaakin Jumala, ja Jakobin Jumala. Niin Moses vapisi eikä tohtinut sinne katsoa.","Minä olen sinun isäis Jumala, Abrahamin Jumala, ja Isaakin Jumala, ja Jakobin Jumala. Niin Moses vapisi eikä tohtinut sinne katsoa."],[7,33,"Ja Herra sanoi hänelle: riisu kenkäs jaloistas; sillä sia, jossas seisot, on pyhä maa.","Ja Herra sanoi hänelle: riisu kenkäs jaloistas; sillä sia, jossas seisot, on pyhä maa."],[7,34,"Minä olen nähden nähnyt kansani tuskan Egyptissä, ja olen heidän huokauksensa kuullut, ja tulin alas heitä ottamaan ulos: tule siis nyt tänne, minä lähetän sinun Egyptiin.","Minä olen nähden nähnyt kansani tuskan Egyptissä, ja olen heidän huokauksensa kuullut, ja tulin alas heitä ottamaan ulos: tule siis nyt tänne, minä lähetän sinun Egyptiin."],[7,35,"Tämän Moseksen, jota he kielsivät, sanoen: kuka sinun on pannut päämieheksi ja tuomariksi? tämän on Jumala lähettänyt päämieheksi ja vapahtajaksi, enkelin käden kautta, joka hänelle pensaassa ilmestyi.","Tämän Moseksen, jota he kielsivät, sanoen: kuka sinun on pannut päämieheksi ja tuomariksi? tämän on Jumala lähettänyt päämieheksi ja vapahtajaksi, enkelin käden kautta, joka hänelle pensaassa ilmestyi."],[7,36,"Tämä johdatti heitä ulos, ja teki ihmeitä ja merkkejä Egyptin maassa ja Punaisessa meressä ja korvessa, neljäkymmentä ajastaikaa.","Tämä johdatti heitä ulos, ja teki ihmeitä ja merkkejä Egyptin maassa ja Punaisessa meressä ja korvessa, neljäkymmentä ajastaikaa."],[7,37,"Tämä on se Moses, joka sanoi Israelin lapsille: Herra teidän Jumalanne herättää teille teidän veljistänne yhden Prophetan, niinkuin minun, jota teidän pitää kuuleman.","Tämä on se Moses, joka sanoi Israelin lapsille: Herra teidän Jumalanne herättää teille teidän veljistänne yhden Prophetan, niinkuin minun, jota teidän pitää kuuleman."],[7,38,"Tämä oli seurakunnassa enkelin kanssa korvessa, joka puhui hänen kanssansa Sinain vuorella, ja meidän isäimme kanssa. Tämä sai elämän puheen meille antaaksensa,","Tämä oli seurakunnassa enkelin kanssa korvessa, joka puhui hänen kanssansa Sinain vuorella, ja meidän isäimme kanssa. Tämä sai elämän puheen meille antaaksensa,"],[7,39,"Jota ei meidän isämme totelleet, vaan sysäsivät pois sen tyköänsä, ja palasivat sydämessänsä Egyptiin,","Jota ei meidän isämme totelleet, vaan sysäsivät pois sen tyköänsä, ja palasivat sydämessänsä Egyptiin,"],[7,40,"Sanoen Aaronille: tee meille jumalia, jotka meidän edellämme kävisivät; sillä emme tiedä, mitä Mosekselle, joka meidän Egyptin maasta toi ulos, on tapahtunut.","Sanoen Aaronille: tee meille jumalia, jotka meidän edellämme kävisivät; sillä emme tiedä, mitä Mosekselle, joka meidän Egyptin maasta toi ulos, on tapahtunut."],[7,41,"Ja niinä päivinä tekivät he vasikan, ja uhrasivat epäjumalille uhria, ja riemuitsivat kättensä töistä.","Ja niinä päivinä tekivät he vasikan, ja uhrasivat epäjumalille uhria, ja riemuitsivat kättensä töistä."],[7,42,"Niin Jumala käänsi itsensä, ja antoi ylön heidät palvelemaan taivaan sotajoukkoa, niinkuin prophetain Raamatussa on kirjoitettu: oletteko te Israelin huoneesta minulle teurasuhria ja ruokauhria tehneet neljänäkymmenenä ajastaikana korvessa?","Niin Jumala käänsi itsensä, ja antoi ylön heidät palvelemaan taivaan sotajoukkoa, niinkuin prophetain Raamatussa on kirjoitettu: oletteko te Israelin huoneesta minulle teurasuhria ja ruokauhria tehneet neljänäkymmenenä ajastaikana korvessa?"],[7,43,"Ja te kannoitte Molokin majaa ja teidän jumalanne Remphan tähteä, joita kuvia te teitte kumartaaksenne niitä, ja minä tahdon teidät viedä pois edemmä Babelia.","Ja te kannoitte Molokin majaa ja teidän jumalanne Remphan tähteä, joita kuvia te teitte kumartaaksenne niitä, ja minä tahdon teidät viedä pois edemmä Babelia."],[7,44,"Meidän isillä oli todistuksen maja korvessa, niinkuin se oli säätänyt, joka Moseksen kanssa puhui, että hänen piti sen tekemän sen esikuvan perään, jonka hän nähnyt oli;","Meidän isillä oli todistuksen maja korvessa, niinkuin se oli säätänyt, joka Moseksen kanssa puhui, että hänen piti sen tekemän sen esikuvan perään, jonka hän nähnyt oli;"],[7,45,"Jonka myös meidän isämme vastaan ottivat, ja veivät Josuan kanssa siihen maahan, jossa pakanat asuivat, jotka Jumala hävitti meidän isäimme kasvoin edestä, hamaan Davidin aikaan asti,","Jonka myös meidän isämme vastaan ottivat, ja veivät Josuan kanssa siihen maahan, jossa pakanat asuivat, jotka Jumala hävitti meidän isäimme kasvoin edestä, hamaan Davidin aikaan asti,"],[7,46,"Joka löysi armon Jumalan tykönä, ja anoi, että hän olis majan löytänyt Jakobin Jumalalle.","Joka löysi armon Jumalan tykönä, ja anoi, että hän olis majan löytänyt Jakobin Jumalalle."],[7,47,"Mutta Salomo rakensi hänelle huoneen.","Mutta Salomo rakensi hänelle huoneen."],[7,48,"Vaan se kaikkein Ylimmäinen ei asu käsillä tehdyissä templeissä, niinkuin propheta sanoo:","Vaan se kaikkein Ylimmäinen ei asu käsillä tehdyissä templeissä, niinkuin propheta sanoo:"],[7,49,"Taivas on minun istuimeni ja maa jalkaini astinlauta. Minkä huoneen te siis tahdotte minulle rakentaa, sanoo Herra, eli kuka on minun leposiani?","Taivas on minun istuimeni ja maa jalkaini astinlauta. Minkä huoneen te siis tahdotte minulle rakentaa, sanoo Herra, eli kuka on minun leposiani?"],[7,50,"Eikö minun käteni ole kaikkia näitä tehnyt?","Eikö minun käteni ole kaikkia näitä tehnyt?"],[7,51,"Te niskurit ja ympärileikkaamattomat sydämestä ja korvista! te olette aina Pyhää Henkeä vastaan, niinkuin teidän isänne, niin myös tekin.","Te niskurit ja ympärileikkaamattomat sydämestä ja korvista! te olette aina Pyhää Henkeä vastaan, niinkuin teidän isänne, niin myös tekin."],[7,52,"Ketä prophetaista ei teidän isänne vainonneet? Ja he tappoivat ne, jotka vanhurskaan tulemista ennustivat, jonka pettäjät ja murhaajat te nyt olitte,","Ketä prophetaista ei teidän isänne vainonneet? Ja he tappoivat ne, jotka vanhurskaan tulemista ennustivat, jonka pettäjät ja murhaajat te nyt olitte,"],[7,53,"Jotka saitte lain enkelien asetuksen kautta, jota ette pitäneet.","Jotka saitte lain enkelien asetuksen kautta, jota ette pitäneet."],[7,54,"Mutta kuin he nämät kuulivat, kävi se läpi heidän sydämensä, ja kiristelivät hampaitansa hänen päällensä.","Mutta kuin he nämät kuulivat, kävi se läpi heidän sydämensä, ja kiristelivät hampaitansa hänen päällensä."],[7,55,"Mutta että hän oli täynnä Pyhää Henkeä, katsahti hän ylös taivaasen, näki Jumalan kunnian ja Jesuksen seisovan Jumalan oikialla kädellä,","Mutta että hän oli täynnä Pyhää Henkeä, katsahti hän ylös taivaasen, näki Jumalan kunnian ja Jesuksen seisovan Jumalan oikialla kädellä,"],[7,56,"Ja sanoi: katso, minä näen taivaat avoinna, ja Ihmisen Pojan seisovan Jumalan oikialla kädellä.","Ja sanoi: katso, minä näen taivaat avoinna, ja Ihmisen Pojan seisovan Jumalan oikialla kädellä."],[7,57,"Niin he huusivat suurella äänellä, ja tukitsivat korviansa, ja karkasivat kaikki yksimielisesti hänen päällensä,","Niin he huusivat suurella äänellä, ja tukitsivat korviansa, ja karkasivat kaikki yksimielisesti hänen päällensä,"],[7,58,"Ja ajoivat hänen ulos kaupungista, ja kivittivät. Ja todistajat panivat vaatteensa nuorukaisen jalkain juureen, joka kutsuttiin Saulus.","Ja ajoivat hänen ulos kaupungista, ja kivittivät. Ja todistajat panivat vaatteensa nuorukaisen jalkain juureen, joka kutsuttiin Saulus."],[7,59,"Ja he kivittivät Stephanin, joka rukoili ja sanoi: Herra Jesus, ota minun henkeni.","Ja he kivittivät Stephanin, joka rukoili ja sanoi: Herra Jesus, ota minun henkeni."],[7,60,"Niin hän pani polvillensa, ja huusi suurella äänellä: Herra, älä lue heille tätä syntiä. Ja kuin hän tämän sanonut oli, niin hän nukkui.","Niin hän pani polvillensa, ja huusi suurella äänellä: Herra, älä lue heille tätä syntiä. Ja kuin hän tämän sanonut oli, niin hän nukkui."],[8,1,"Ja Saulus oli myös mielistynyt hänen kuolemaansa. Niin sinä päivänä nousi suuri vaino seurakuntaa vastaan, joka oli Jerusalemissa; ja hajosivat kaikki ympäri Juudan ja Samarian maakuntaa, paitsi apostoleita.","Ja Saulus oli myös mielistynyt hänen kuolemaansa. Niin sinä päivänä nousi suuri vaino seurakuntaa vastaan, joka oli Jerusalemissa; ja hajosivat kaikki ympäri Juudan ja Samarian maakuntaa, paitsi apostoleita."],[8,2,"Ja muutamat Jumalaa pelkääväiset miehet korjasivat Stephanin, ja valittivat häntä suuresti.","Ja muutamat Jumalaa pelkääväiset miehet korjasivat Stephanin, ja valittivat häntä suuresti."],[8,3,"Mutta Saulus raateli seurakuntaa ja kävi huone huoneelta, otti miehet ja vaimot ja panetti vankiuteen.","Mutta Saulus raateli seurakuntaa ja kävi huone huoneelta, otti miehet ja vaimot ja panetti vankiuteen."],[8,4,"Ja ne hajonneet vaelsivat ympärinsä ja saarnasivat Jumalan sanaa.","Ja ne hajonneet vaelsivat ympärinsä ja saarnasivat Jumalan sanaa."],[8,5,"Niin Philippus tuli Samarian kaupunkiin ja saarnasi heille Kristuksesta.","Niin Philippus tuli Samarian kaupunkiin ja saarnasi heille Kristuksesta."],[8,6,"Mutta kansa otti vaarin yksimielisesti ja visusti Philippuksen sanoista, kuullen ja nähden ne merkit, jotka hän teki:","Mutta kansa otti vaarin yksimielisesti ja visusti Philippuksen sanoista, kuullen ja nähden ne merkit, jotka hän teki:"],[8,7,"Sillä rumat henget läksivät ulos monesta, huutain suurella äänellä ja monta halvattua ja saattamatointa parani.","Sillä rumat henget läksivät ulos monesta, huutain suurella äänellä ja monta halvattua ja saattamatointa parani."],[8,8,"Ja suuri ilo tuli siihen kaupunkiin.","Ja suuri ilo tuli siihen kaupunkiin."],[8,9,"Mutta siellä oli mies, Simon nimeltä, joka siinä kaupungissa ennen noituuden virkaa piti ja oli Samarian kansan villinnyt, sanoen itsensä olevan jonkun suuren,","Mutta siellä oli mies, Simon nimeltä, joka siinä kaupungissa ennen noituuden virkaa piti ja oli Samarian kansan villinnyt, sanoen itsensä olevan jonkun suuren,"],[8,10,"Jota kaikki sekä pienet että suuret kuulivat, sanoen: tämä on Jumalan voima, joka suuri on.","Jota kaikki sekä pienet että suuret kuulivat, sanoen: tämä on Jumalan voima, joka suuri on."],[8,11,"Mutta he kuultelivat häntä mielellänsä, että hän kauvan aikaa oli heitä noituudellansa villinnyt.","Mutta he kuultelivat häntä mielellänsä, että hän kauvan aikaa oli heitä noituudellansa villinnyt."],[8,12,"Mutta kuin he uskoivat Philippuksen, joka saarnasi Jumalan valtakunnasta ja Jesuksen Kristuksen nimestä, niin he kastettiin sekä miehet että vaimot.","Mutta kuin he uskoivat Philippuksen, joka saarnasi Jumalan valtakunnasta ja Jesuksen Kristuksen nimestä, niin he kastettiin sekä miehet että vaimot."],[8,13,"Niin Simon myös itse uskoi, ja kuin hän kastettu oli, viipyi hän Philippuksen tykönä. Ja kuin hän näki ne merkit ja suuret voimalliset työt tapahtuvan, niin hän hämmästyi.","Niin Simon myös itse uskoi, ja kuin hän kastettu oli, viipyi hän Philippuksen tykönä. Ja kuin hän näki ne merkit ja suuret voimalliset työt tapahtuvan, niin hän hämmästyi."],[8,14,"Mutta kuin apostolit, jotka Jerusalemissa olivat, kuulivat Samarian Jumalan sanan ottaneen vastaan, lähettivät he heidän tykönsä Pietarin ja Johanneksen,","Mutta kuin apostolit, jotka Jerusalemissa olivat, kuulivat Samarian Jumalan sanan ottaneen vastaan, lähettivät he heidän tykönsä Pietarin ja Johanneksen,"],[8,15,"Jotka, kuin he sinne tulivat alas, rukoilivat niiden edestä, että he olisivat saaneet Pyhän Hengen;","Jotka, kuin he sinne tulivat alas, rukoilivat niiden edestä, että he olisivat saaneet Pyhän Hengen;"],[8,16,"(Sillä ei hän ollut vielä yhdenkään niiden päälle laskettu alas, vaan olivat ainoastaan Herran Jesuksen nimeen kastetut.)","(Sillä ei hän ollut vielä yhdenkään niiden päälle laskettu alas, vaan olivat ainoastaan Herran Jesuksen nimeen kastetut.)"],[8,17,"Niin he panivat kätensä heidän päällensä, ja he saivat Pyhän Hengen.","Niin he panivat kätensä heidän päällensä, ja he saivat Pyhän Hengen."],[8,18,"Mutta kuin Simon näki, että apostolien kätten päälle-panemisen kautta Pyhä Henki annettiin, taritsi hän heille rahaa,","Mutta kuin Simon näki, että apostolien kätten päälle-panemisen kautta Pyhä Henki annettiin, taritsi hän heille rahaa,"],[8,19,"Sanoen: antakaat minullekin se voima, että kenenkä päälle minä käteni panen, se sais Pyhän Hengen.","Sanoen: antakaat minullekin se voima, että kenenkä päälle minä käteni panen, se sais Pyhän Hengen."],[8,20,"Vaan Pietari sanoi hänelle: sinun rahas olkoon sinun kanssas kadotuksessa, että Jumalan lahjan luulet rahoilla ostettavan.","Vaan Pietari sanoi hänelle: sinun rahas olkoon sinun kanssas kadotuksessa, että Jumalan lahjan luulet rahoilla ostettavan."],[8,21,"Ei sinulla ole osaa eikä arpaa tässä sanassa; sillä ei sinun sydämes ole oikia Jumalan edessä.","Ei sinulla ole osaa eikä arpaa tässä sanassa; sillä ei sinun sydämes ole oikia Jumalan edessä."],[8,22,"Sentähden tee parannus sinun pahuudestas, ja rukoile Jumalaa, että sydämes ajatukset sinulle anteeksi annettaisiin.","Sentähden tee parannus sinun pahuudestas, ja rukoile Jumalaa, että sydämes ajatukset sinulle anteeksi annettaisiin."],[8,23,"Sillä minä näen sinun olevan katkerassa sapessa ja vääryyden solmussa.","Sillä minä näen sinun olevan katkerassa sapessa ja vääryyden solmussa."],[8,24,"Niin Simon vastasi ja sanoi: rukoilkaat te Herraa minun edestäni, ettei mitään näistä, mitä te sanoitte, minun päälleni tulisi.","Niin Simon vastasi ja sanoi: rukoilkaat te Herraa minun edestäni, ettei mitään näistä, mitä te sanoitte, minun päälleni tulisi."],[8,25,"Mutta kuin he olivat todistaneet ja puhuneet Herran sanan, palasivat he Jerusalemiin, ja saarnasivat evankeliumia monessa Samarian kylässä.","Mutta kuin he olivat todistaneet ja puhuneet Herran sanan, palasivat he Jerusalemiin, ja saarnasivat evankeliumia monessa Samarian kylässä."],[8,26,"Mutta Herran enkeli puhui Philippukselle ja sanoi: nouse ja mene lounaaseen päin, sitä tietä, joka Jerusalemista menee alas Gatsaan, joka kylmillä on.","Mutta Herran enkeli puhui Philippukselle ja sanoi: nouse ja mene lounaaseen päin, sitä tietä, joka Jerusalemista menee alas Gatsaan, joka kylmillä on."],[8,27,"Niin hän nousi ja meni. Ja katso, yksi Etiopian mies, Etiopian kuningattaren Kandasen voimallinen kamaripalvelia, joka oli pantu kaiken hänen tavaransa päälle, se oli tullut Jerusalemiin rukoilemaan,","Niin hän nousi ja meni. Ja katso, yksi Etiopian mies, Etiopian kuningattaren Kandasen voimallinen kamaripalvelia, joka oli pantu kaiken hänen tavaransa päälle, se oli tullut Jerusalemiin rukoilemaan,"],[8,28,"Ja palasi sieltä, istuen vaunuissansa, ja luki Jesaias prophetaa.","Ja palasi sieltä, istuen vaunuissansa, ja luki Jesaias prophetaa."],[8,29,"Niin Henki sanoi Philippukselle: käy ja mene lähemmä tätä vaunua.","Niin Henki sanoi Philippukselle: käy ja mene lähemmä tätä vaunua."],[8,30,"Niin Philippus juoksi lähemmä, ja kuuli hänen lukevan Jesaias prophetaa, ja sanoi: ymmärrätkös, mitäs luet?","Niin Philippus juoksi lähemmä, ja kuuli hänen lukevan Jesaias prophetaa, ja sanoi: ymmärrätkös, mitäs luet?"],[8,31,"Mutta hän sanoi: kuinka minä taidan ymmärtää, ellei joku minua johdata? Ja hän rukoili Philippusta, että hän tulis ja istuis hänen kanssansa.","Mutta hän sanoi: kuinka minä taidan ymmärtää, ellei joku minua johdata? Ja hän rukoili Philippusta, että hän tulis ja istuis hänen kanssansa."],[8,32,"Mutta se, mitä hän Raamatusta luki, oli tämä: hän on niinkuin lammas teuraaksi talutettu: ja niinkuin karitsa keritsiänsä edessä on ääneti, niin ei hänkään avannut suutansa,","Mutta se, mitä hän Raamatusta luki, oli tämä: hän on niinkuin lammas teuraaksi talutettu: ja niinkuin karitsa keritsiänsä edessä on ääneti, niin ei hänkään avannut suutansa,"],[8,33,"Hänen nöyryydessänsä on hänen tuomionsa otettu pois, mutta kuka taitaa sanoa ulos hänen elämänsä pituuden? sillä hänen elämänsä otetaan pois maasta.","Hänen nöyryydessänsä on hänen tuomionsa otettu pois, mutta kuka taitaa sanoa ulos hänen elämänsä pituuden? sillä hänen elämänsä otetaan pois maasta."],[8,34,"Niin kamaripalvelija vastasi Philippusta: minä rukoilen sinua, sanos: kenestä propheta näitä puhuu? itsestäänkö eli jostakin toisesta?","Niin kamaripalvelija vastasi Philippusta: minä rukoilen sinua, sanos: kenestä propheta näitä puhuu? itsestäänkö eli jostakin toisesta?"],[8,35,"Niin Philippus avasi suunsa ja rupesi tästä kirjoituksesta hänelle saarnaamaan evankeliumia Jesuksesta.","Niin Philippus avasi suunsa ja rupesi tästä kirjoituksesta hänelle saarnaamaan evankeliumia Jesuksesta."],[8,36,"Ja kuin he tiellä vaelsivat, tulivat he veden tykö, ja kamaripalvelia sanoi: katso, tässä on vesi: mikä estää minua kastamasta?","Ja kuin he tiellä vaelsivat, tulivat he veden tykö, ja kamaripalvelia sanoi: katso, tässä on vesi: mikä estää minua kastamasta?"],[8,37,"Mutta Philippus sanoi: jos sinä kaikesta sydämestä uskot, niin tapahtukoon. Hän vastasi ja sanoi: minä uskon Jesuksen Kristuksen Jumalan Pojaksi.","Mutta Philippus sanoi: jos sinä kaikesta sydämestä uskot, niin tapahtukoon. Hän vastasi ja sanoi: minä uskon Jesuksen Kristuksen Jumalan Pojaksi."],[8,38,"Niin hän käski seisahtaa vaunun; ja he astuivat molemmat veteen, Philippus ja kamaripalvelia, ja hän kasti hänen.","Niin hän käski seisahtaa vaunun; ja he astuivat molemmat veteen, Philippus ja kamaripalvelia, ja hän kasti hänen."],[8,39,"Mutta kuin he vedestä astuivat ylös, tempasi Herran Henki Philippuksen, ja ei kamaripalvelia häntä enään nähnyt, vaan meni iloiten tietänsä myöten.","Mutta kuin he vedestä astuivat ylös, tempasi Herran Henki Philippuksen, ja ei kamaripalvelia häntä enään nähnyt, vaan meni iloiten tietänsä myöten."],[8,40,"Mutta Philippus löydettiin Atsotissa, ja vaelsi ympäri ja saarnasi joka kaupungissa evankeliumia, siihenasti kuin hän tuli Kesareaan.","Mutta Philippus löydettiin Atsotissa, ja vaelsi ympäri ja saarnasi joka kaupungissa evankeliumia, siihenasti kuin hän tuli Kesareaan."],[9,1,"Mutta Saulus puskui vielä uhkauksia ja murhaa Herran opetuslapsia vastaan ja meni ylimmäisen papin tykö,","Mutta Saulus puskui vielä uhkauksia ja murhaa Herran opetuslapsia vastaan ja meni ylimmäisen papin tykö,"],[9,2,"Ja anoi häneltä kirjaa Damaskuun synagogain tykö, että kutka ikänä hän sen tien miehistä eli vaimoista löytäis, ne hän olis vienyt sidottuna Jerusalemiin.","Ja anoi häneltä kirjaa Damaskuun synagogain tykö, että kutka ikänä hän sen tien miehistä eli vaimoista löytäis, ne hän olis vienyt sidottuna Jerusalemiin."],[9,3,"Mutta kuin hän matkusti, tapahtui, että hän Damaskua lähestyi, ja äkisti leimahti valkeus taivaasta ympäri häntä.","Mutta kuin hän matkusti, tapahtui, että hän Damaskua lähestyi, ja äkisti leimahti valkeus taivaasta ympäri häntä."],[9,4,"Ja hän lankesi maahan ja kuuli äänen hänelle sanovan: Saul, Saul, miksi vainoot minua?","Ja hän lankesi maahan ja kuuli äänen hänelle sanovan: Saul, Saul, miksi vainoot minua?"],[9,5,"Mutta hän sanoi: kuka sinä olet, Herra? Ja Herra sanoi: minä olen Jesus, jota sinä vainoot: työläs on sinun potkia tutkainta vastaan.","Mutta hän sanoi: kuka sinä olet, Herra? Ja Herra sanoi: minä olen Jesus, jota sinä vainoot: työläs on sinun potkia tutkainta vastaan."],[9,6,"Niin hän vapisi, hämmästyi ja sanoi: Herra, mitäs minua tahdot tekemään? Ja Herra sanoi hänelle: nouse ja mene kaupunkiin; siellä sinulle sanotaan, mitä sinun pitää tekemän.","Niin hän vapisi, hämmästyi ja sanoi: Herra, mitäs minua tahdot tekemään? Ja Herra sanoi hänelle: nouse ja mene kaupunkiin; siellä sinulle sanotaan, mitä sinun pitää tekemän."],[9,7,"Mutta ne miehet, jotka hänen seurassansa olivat, seisoivat hämmästyksissä; he kuulivat tosin äänen, mutta ei he ketään nähneet.","Mutta ne miehet, jotka hänen seurassansa olivat, seisoivat hämmästyksissä; he kuulivat tosin äänen, mutta ei he ketään nähneet."],[9,8,"Niin Saulus nousi maasta ja ei nähnyt ketään avoimilla silmillä; mutta he taluttivat häntä kädestä ja veivät Damaskuun.","Niin Saulus nousi maasta ja ei nähnyt ketään avoimilla silmillä; mutta he taluttivat häntä kädestä ja veivät Damaskuun."],[9,9,"Ja hän oli kolme päivää näkemättä ja ei syönyt eikä juonut.","Ja hän oli kolme päivää näkemättä ja ei syönyt eikä juonut."],[9,10,"Niin yksi opetuslapsi oli Damaskussa, Ananias nimeltä, jolle Herra sanoi näyssä: Ananias! Hän sanoi: Herra, tässä minä olen.","Niin yksi opetuslapsi oli Damaskussa, Ananias nimeltä, jolle Herra sanoi näyssä: Ananias! Hän sanoi: Herra, tässä minä olen."],[9,11,"Herra sanoi hänelle: nouse ja mene sille kadulle, joka Oikiaksi kutsutaan, ja kysy Juudan huoneessa sitä, joka Saulus Tarsilaiseksi kutsutaan; sillä katso, hän rukoilee.","Herra sanoi hänelle: nouse ja mene sille kadulle, joka Oikiaksi kutsutaan, ja kysy Juudan huoneessa sitä, joka Saulus Tarsilaiseksi kutsutaan; sillä katso, hän rukoilee."],[9,12,"Ja hän näki näyssä yhden miehen, nimeltä Ananias, tulevan sisälle ja panevan kätensä hänen päällensä, että hän sais näkönsä jälleen.","Ja hän näki näyssä yhden miehen, nimeltä Ananias, tulevan sisälle ja panevan kätensä hänen päällensä, että hän sais näkönsä jälleen."],[9,13,"Niin Ananias vastasi: Herra, minä olen kuullut monelta tästä miehestä, kuinka paljon pahaa hän sinun pyhilles on tehnyt Jerusalemissa.","Niin Ananias vastasi: Herra, minä olen kuullut monelta tästä miehestä, kuinka paljon pahaa hän sinun pyhilles on tehnyt Jerusalemissa."],[9,14,"Ja hänellä on nytkin valta ylimmäisiltä papeilta täällä kiinni sitoa kaikki ne, jotka sinun nimeäs rukoilevat.","Ja hänellä on nytkin valta ylimmäisiltä papeilta täällä kiinni sitoa kaikki ne, jotka sinun nimeäs rukoilevat."],[9,15,"Niin sanoi Herra hänelle: mene! sillä hän on minulle valittu ase, kantamaan minun nimeäni pakanain, ja kuningasten, ja Israelin lasten eteen.","Niin sanoi Herra hänelle: mene! sillä hän on minulle valittu ase, kantamaan minun nimeäni pakanain, ja kuningasten, ja Israelin lasten eteen."],[9,16,"Sillä minä tahdon hänelle näyttää, kuinka paljon hänen pitää kärsimän minun nimeni tähden.","Sillä minä tahdon hänelle näyttää, kuinka paljon hänen pitää kärsimän minun nimeni tähden."],[9,17,"Niin Ananias meni sinne ja tuli huoneeseen sisälle ja pani kätensä hänen päällensä, ja sanoi: rakas veljeni Saul! se Herra lähetti minun, (Jesus, joka sinulle ilmestyi tiellä, jotas vaelsit,) että sinä saisit näkös jälleen, ja Pyhällä Hengellä täytettäisiin.","Niin Ananias meni sinne ja tuli huoneeseen sisälle ja pani kätensä hänen päällensä, ja sanoi: rakas veljeni Saul! se Herra lähetti minun, (Jesus, joka sinulle ilmestyi tiellä, jotas vaelsit,) että sinä saisit näkös jälleen, ja Pyhällä Hengellä täytettäisiin."],[9,18,"Ja hänen silmistänsä putosivat kohta niinkuin suomukset, ja hän sai sillä hetkellä näkönsä jällensä, nousi ja kastettiin.","Ja hänen silmistänsä putosivat kohta niinkuin suomukset, ja hän sai sillä hetkellä näkönsä jällensä, nousi ja kastettiin."],[9,19,"Ja kuin hän otti ruokaa, niin hän vahvistui. Ja Saulus oli muutamat päivät opetuslasten kanssa, jotka olivat Damaskussa,","Ja kuin hän otti ruokaa, niin hän vahvistui. Ja Saulus oli muutamat päivät opetuslasten kanssa, jotka olivat Damaskussa,"],[9,20,"Ja saarnasi kohta synagogassa Kristuksesta, että hän on Jumalan Poika.","Ja saarnasi kohta synagogassa Kristuksesta, että hän on Jumalan Poika."],[9,21,"Niin kaikki, jotka sen kuulivat, hämmästyivät ja sanoivat: eikö tämä ole se, joka kaikkia niitä hävitti Jerusalemissa, jotka sitä nimeä rukoilivat, ja tuli myös tänne sitä varten, että hän ne sidottuna veis ylimmäisille papeille?","Niin kaikki, jotka sen kuulivat, hämmästyivät ja sanoivat: eikö tämä ole se, joka kaikkia niitä hävitti Jerusalemissa, jotka sitä nimeä rukoilivat, ja tuli myös tänne sitä varten, että hän ne sidottuna veis ylimmäisille papeille?"],[9,22,"Mutta Saulus tuli aina jalommaksi ja ajoi Juudalaisia takaperin, jotka Damaskussa olivat, täydellisesti vahvistain, että tämä on Kristus.","Mutta Saulus tuli aina jalommaksi ja ajoi Juudalaisia takaperin, jotka Damaskussa olivat, täydellisesti vahvistain, että tämä on Kristus."],[9,23,"Ja monen päivän perästä pitivät Juudalaiset neuvoa keskenänsä tappaaksensa häntä.","Ja monen päivän perästä pitivät Juudalaiset neuvoa keskenänsä tappaaksensa häntä."],[9,24,"Mutta Saulukselle ilmoitettiin heidän väijymisensä. Ja he vartioitsivat portissa yötä ja päivää tappaaksensa häntä.","Mutta Saulukselle ilmoitettiin heidän väijymisensä. Ja he vartioitsivat portissa yötä ja päivää tappaaksensa häntä."],[9,25,"Niin opetuslapset ottivat hänen yöllä, päästivät alas ylitse muurin, ja laskivat korissa maahan.","Niin opetuslapset ottivat hänen yöllä, päästivät alas ylitse muurin, ja laskivat korissa maahan."],[9,26,"Mutta kuin Saulus tuli Jerusalemiin, tahtoi hän itsiänsä antaa opetuslasten sekaan, mutta he pelkäsivät kaikki häntä, eikä uskoneet häntä opetuslapseksi.","Mutta kuin Saulus tuli Jerusalemiin, tahtoi hän itsiänsä antaa opetuslasten sekaan, mutta he pelkäsivät kaikki häntä, eikä uskoneet häntä opetuslapseksi."],[9,27,"Vaan Barnabas otti hänen ja vei apostolien tykö, ja jutteli heille, kuinka hän tiellä Herran nähnyt oli, ja että hän oli puhunut hänen kanssansa, ja kuinka hän oli rohkiasti Damaskussa Jesuksen nimestä puhunut.","Vaan Barnabas otti hänen ja vei apostolien tykö, ja jutteli heille, kuinka hän tiellä Herran nähnyt oli, ja että hän oli puhunut hänen kanssansa, ja kuinka hän oli rohkiasti Damaskussa Jesuksen nimestä puhunut."],[9,28,"Ja niin hän oli heidän kanssansa Jerusalemissa, kävi sisälle ja ulos, ja saarnasi pelkäämättä Herran Jesuksen nimeen.","Ja niin hän oli heidän kanssansa Jerusalemissa, kävi sisälle ja ulos, ja saarnasi pelkäämättä Herran Jesuksen nimeen."],[9,29,"Hän puhui myös ja kamppaili Grekiläisiä vastaan; mutta ne pyysivät häntä tappaa.","Hän puhui myös ja kamppaili Grekiläisiä vastaan; mutta ne pyysivät häntä tappaa."],[9,30,"Kuin veljet sen ymmärsivät, niin he veivät hänen Kesareaan ja lähettivät Tarsiin.","Kuin veljet sen ymmärsivät, niin he veivät hänen Kesareaan ja lähettivät Tarsiin."],[9,31,"Ja niin seurakunnilla oli rauha kaikessa Juudeassa, ja Galileassa, ja Samariassa, ja enenivät vaeltain Herran pelvossa, ja täytettiin Pyhän Hengen lohdutuksella.","Ja niin seurakunnilla oli rauha kaikessa Juudeassa, ja Galileassa, ja Samariassa, ja enenivät vaeltain Herran pelvossa, ja täytettiin Pyhän Hengen lohdutuksella."],[9,32,"Niin tapahtui, kuin Pietari vaelsi joka paikassa, että hän myös tuli pyhäin tykö, jotka Lyddassa asuivat.","Niin tapahtui, kuin Pietari vaelsi joka paikassa, että hän myös tuli pyhäin tykö, jotka Lyddassa asuivat."],[9,33,"Niin hän löysi siellä yhden miehen, Eneas nimeltä, joka jo kahdeksan ajastaikaa oli vuoteessa halvattuna maannut.","Niin hän löysi siellä yhden miehen, Eneas nimeltä, joka jo kahdeksan ajastaikaa oli vuoteessa halvattuna maannut."],[9,34,"Ja Pietari sanoi hänelle: Eneas, Jesus Kristus sinun paratkoon! nouse ja tee itse vuotees; ja hän kohta nousi.","Ja Pietari sanoi hänelle: Eneas, Jesus Kristus sinun paratkoon! nouse ja tee itse vuotees; ja hän kohta nousi."],[9,35,"Ja kaikki Lyddan ja Saronin asuvaiset näkivät hänen, jotka tulivat käännetyksi Herran tykö.","Ja kaikki Lyddan ja Saronin asuvaiset näkivät hänen, jotka tulivat käännetyksi Herran tykö."],[9,36,"Mutta Jopessa oli yksi opetuspiika, nimeltä Tabita, joka tulkiten on niin paljon sanottu kuin: metsävuohi (a); tämä oli täynnänsä hyviä töitä ja almua, joita hän teki.","Mutta Jopessa oli yksi opetuspiika, nimeltä Tabita, joka tulkiten on niin paljon sanottu kuin: metsävuohi (a); tämä oli täynnänsä hyviä töitä ja almua, joita hän teki."],[9,37,"Niin tapahtui niinä päivinä, että se sairasti ja kuoli; jonka he pesivät ja panivat saliin.","Niin tapahtui niinä päivinä, että se sairasti ja kuoli; jonka he pesivät ja panivat saliin."],[9,38,"Ja että Lydda oli läsnä Joppea, niin opetuslapset, kuin he kuulivat Pietarin siellä olevan, lähettivät hänen tykönsä kaksi miestä rukoilemaan, ettei hän viivyttelisi heidän tykönsä tulla.","Ja että Lydda oli läsnä Joppea, niin opetuslapset, kuin he kuulivat Pietarin siellä olevan, lähettivät hänen tykönsä kaksi miestä rukoilemaan, ettei hän viivyttelisi heidän tykönsä tulla."],[9,39,"Niin Pietari nousi ja tuli heidän kanssansa; ja kuin hän sinne tuli, veivät he hänen saliin. Ja hänen ympärillänsä seisoivat kaikki lesket, jotka itkivät ja osoittivat hänelle niitä hameita ja vaatteita, joita Dorkas heille tehnyt oli, ollessansa heidän kanssansa.","Niin Pietari nousi ja tuli heidän kanssansa; ja kuin hän sinne tuli, veivät he hänen saliin. Ja hänen ympärillänsä seisoivat kaikki lesket, jotka itkivät ja osoittivat hänelle niitä hameita ja vaatteita, joita Dorkas heille tehnyt oli, ollessansa heidän kanssansa."],[9,40,"Mutta kuin Pietari oli heidät kaikki ajanut ulos, laski hän polvillensa ja rukoili, ja käänsi itsensä ruumiin puoleen, ja sanoi: Tabita, nouse ylös! niin se avasi silmänsä; ja kuin hän Pietarin näki, nousi hän istualle.","Mutta kuin Pietari oli heidät kaikki ajanut ulos, laski hän polvillensa ja rukoili, ja käänsi itsensä ruumiin puoleen, ja sanoi: Tabita, nouse ylös! niin se avasi silmänsä; ja kuin hän Pietarin näki, nousi hän istualle."],[9,41,"Ja hän antoi hänelle kättä ja ojensi hänen, ja kutsui pyhät ja lesket, ja antoi hänen heille elävänä.","Ja hän antoi hänelle kättä ja ojensi hänen, ja kutsui pyhät ja lesket, ja antoi hänen heille elävänä."],[9,42,"Ja se tuli kaikelle Jopelle tiettäväksi; ja moni uskoi Herran päälle.","Ja se tuli kaikelle Jopelle tiettäväksi; ja moni uskoi Herran päälle."],[9,43,"Ja tapahtui, että hän viipyi Jopessa kauvan aikaa Simon parkkarin tykönä.","Ja tapahtui, että hän viipyi Jopessa kauvan aikaa Simon parkkarin tykönä."],[10,1,"Niin oli Kesareassa mies, nimeltä Kornelius, sadanpäämies, Italian joukosta,","Niin oli Kesareassa mies, nimeltä Kornelius, sadanpäämies, Italian joukosta,"],[10,2,"Jumalinen ja Jumalaa pelkääväinen kaiken huoneensa kanssa, joka jakoi paljon almua kansalle, ja rukoili alati Jumalaa.","Jumalinen ja Jumalaa pelkääväinen kaiken huoneensa kanssa, joka jakoi paljon almua kansalle, ja rukoili alati Jumalaa."],[10,3,"Hän näki julkisesti näyssä, liki yhdeksättä hetkeä päivästä, Jumalan enkelin tulevan tykönsä ja sanovan hänelle: Kornelius!","Hän näki julkisesti näyssä, liki yhdeksättä hetkeä päivästä, Jumalan enkelin tulevan tykönsä ja sanovan hänelle: Kornelius!"],[10,4,"Ja hän katseli hänen päällensä, peljästyi ja sanoi: Herra, mikä on? Hän sanoi hänelle: sinun rukoukses ja almus ovat tulleet muistoon Jumalan edessä.","Ja hän katseli hänen päällensä, peljästyi ja sanoi: Herra, mikä on? Hän sanoi hänelle: sinun rukoukses ja almus ovat tulleet muistoon Jumalan edessä."],[10,5,"Ja nyt lähetä miehiä Joppeen, ja anna noutaa Simonin, jota Pietariksi kutsutaan.","Ja nyt lähetä miehiä Joppeen, ja anna noutaa Simonin, jota Pietariksi kutsutaan."],[10,6,"Hän pitää majaa Simon parkkarilla, jonka huone on meren tykönä; hän sanoo sinulle, mitä sinun pitää tekemän.","Hän pitää majaa Simon parkkarilla, jonka huone on meren tykönä; hän sanoo sinulle, mitä sinun pitää tekemän."],[10,7,"Ja kuin enkeli, joka Korneliusta puhutteli, meni pois, kutsui hän kaksi palveliaansa ja yhden Jumalaa pelkääväisen sotamiehen niistä, jotka hänen tykönänsä oleskelivat,","Ja kuin enkeli, joka Korneliusta puhutteli, meni pois, kutsui hän kaksi palveliaansa ja yhden Jumalaa pelkääväisen sotamiehen niistä, jotka hänen tykönänsä oleskelivat,"],[10,8,"Ja hän jutteli kaikki nämät niille, ja lähetti ne Joppeen.","Ja hän jutteli kaikki nämät niille, ja lähetti ne Joppeen."],[10,9,"Toisena päivänä, kuin he matkassa olivat ja kaupunkia lähestyivät, meni Pietari ylös katon päälle rukoilemaan, liki kuudetta hetkeä.","Toisena päivänä, kuin he matkassa olivat ja kaupunkia lähestyivät, meni Pietari ylös katon päälle rukoilemaan, liki kuudetta hetkeä."],[10,10,"Ja kuin hän isosi, tahtoi hän suurustaa. Mutta kuin he hänelle valmistivat, tuli hän horroksiin,","Ja kuin hän isosi, tahtoi hän suurustaa. Mutta kuin he hänelle valmistivat, tuli hän horroksiin,"],[10,11,"Ja näki taivaan auki, ja tulevan alas tykönsä yhden astian, niinkuin suuren liinaisen, neljältä kulmalta sidotun, joka laskettiin alas taivaasta maan päälle,","Ja näki taivaan auki, ja tulevan alas tykönsä yhden astian, niinkuin suuren liinaisen, neljältä kulmalta sidotun, joka laskettiin alas taivaasta maan päälle,"],[10,12,"Jossa oli kaikkinaisia nelijalkaisia maan eläimiä ja metsillisiä, ja matelevaisia, ja taivaan lintuja.","Jossa oli kaikkinaisia nelijalkaisia maan eläimiä ja metsillisiä, ja matelevaisia, ja taivaan lintuja."],[10,13,"Ja ääni tuli hänelle: Pietari, nouse, tapa ja syö.","Ja ääni tuli hänelle: Pietari, nouse, tapa ja syö."],[10,14,"Pietari sanoi: en suinkaan, Herra; sillä en ole minä ikänä syönyt mitään yhteistä eli saastaista.","Pietari sanoi: en suinkaan, Herra; sillä en ole minä ikänä syönyt mitään yhteistä eli saastaista."],[10,15,"Ja ääni sanoi taas toisen kerran hänelle: mitä Jumala on puhdistanut, älä sitä sinä sano yhteiseksi.","Ja ääni sanoi taas toisen kerran hänelle: mitä Jumala on puhdistanut, älä sitä sinä sano yhteiseksi."],[10,16,"Ja se tapahtui kolme kertaa ja astia otettiin jälleen ylös taivaaseen.","Ja se tapahtui kolme kertaa ja astia otettiin jälleen ylös taivaaseen."],[10,17,"Ja kuin Pietari itsellänsä epäili, mikä näky se olis, jonka hän näki, niin katso, miehet, jotka lähetetyt olivat Korneliukselta, kyselivät Simonin huonetta ja seisoivat oven edessä,","Ja kuin Pietari itsellänsä epäili, mikä näky se olis, jonka hän näki, niin katso, miehet, jotka lähetetyt olivat Korneliukselta, kyselivät Simonin huonetta ja seisoivat oven edessä,"],[10,18,"Ja kutsuivat yhden ulos ja kysyivät, pitikö Simon, joka liialta nimeltä Pietariksi kutsutaan, siellä majaa.","Ja kutsuivat yhden ulos ja kysyivät, pitikö Simon, joka liialta nimeltä Pietariksi kutsutaan, siellä majaa."],[10,19,"Mutta kuin Pietari sitä näkyä ajatteli, sanoi Henki hänelle: katso, kolme miestä etsivät sinua.","Mutta kuin Pietari sitä näkyä ajatteli, sanoi Henki hänelle: katso, kolme miestä etsivät sinua."],[10,20,"Nouse siis, astu alas ja mene ilman epäilemättä heidän kanssansa; sillä minä lähetin heidät.","Nouse siis, astu alas ja mene ilman epäilemättä heidän kanssansa; sillä minä lähetin heidät."],[10,21,"Niin Pietari astui alas miesten tykö, jotka hänen tykönsä Korneliukselta lähetetyt olivat, ja sanoi: katso, minä se olen, jota te etsitte; mitä varten te tulleet olette?","Niin Pietari astui alas miesten tykö, jotka hänen tykönsä Korneliukselta lähetetyt olivat, ja sanoi: katso, minä se olen, jota te etsitte; mitä varten te tulleet olette?"],[10,22,"Mutta he sanoivat: sadanpäämies Kornelius, hurskas ja Jumalaa pelkääväinen mies, jolla on todistus kaikelta Juudan kansalta, on pyhältä enkeliltä käskyn saanut, että hänen piti sinun antaman kutsua huoneesensa, sinulta sanoja kuullaksensa,","Mutta he sanoivat: sadanpäämies Kornelius, hurskas ja Jumalaa pelkääväinen mies, jolla on todistus kaikelta Juudan kansalta, on pyhältä enkeliltä käskyn saanut, että hänen piti sinun antaman kutsua huoneesensa, sinulta sanoja kuullaksensa,"],[10,23,"Niin hän kutsui heitä sisälle, ja otti heidät majaan. Toisena päivänä meni Pietari heidän kanssansa, ja muutamat veljet Jopesta seurasivat myös häntä.","Niin hän kutsui heitä sisälle, ja otti heidät majaan. Toisena päivänä meni Pietari heidän kanssansa, ja muutamat veljet Jopesta seurasivat myös häntä."],[10,24,"Ja toisena päivänä tulivat he Kesareaan; ja Kornelius odotti heitä, ja oli kutsunut kokoon lankonsa ja parhaat ystävänsä.","Ja toisena päivänä tulivat he Kesareaan; ja Kornelius odotti heitä, ja oli kutsunut kokoon lankonsa ja parhaat ystävänsä."],[10,25,"Mutta kuin Pietari tuli sisälle, meni Kornelius häntä vastaan, ja lankesi hänen jalkainsa juureen, ja rukoili häntä.","Mutta kuin Pietari tuli sisälle, meni Kornelius häntä vastaan, ja lankesi hänen jalkainsa juureen, ja rukoili häntä."],[10,26,"Mutta Pietari nosti häntä ja sanoi: nouse! minäkin olen ihminen.","Mutta Pietari nosti häntä ja sanoi: nouse! minäkin olen ihminen."],[10,27,"Ja kuin hän oli häntä puhutellut, meni hän sisälle ja löysi monta tulleen kokoon.","Ja kuin hän oli häntä puhutellut, meni hän sisälle ja löysi monta tulleen kokoon."],[10,28,"Ja hän sanoi heille: te tiedätte, ettei ole ollut luvallinen Juudalaisen olla jonkun muukalaisen tykönä eli hänen tykönsä mennä; mutta minulle osoitti Jumala, etten minä ketään ihmistä yhteisenä eli saastaisena pitäisi.","Ja hän sanoi heille: te tiedätte, ettei ole ollut luvallinen Juudalaisen olla jonkun muukalaisen tykönä eli hänen tykönsä mennä; mutta minulle osoitti Jumala, etten minä ketään ihmistä yhteisenä eli saastaisena pitäisi."],[10,29,"Sentähden minä myös epäilemättä tulin, teiltä kutsuttu. Niin minä siis teiltä kysyn: mitä varten te minua kutsuitte?","Sentähden minä myös epäilemättä tulin, teiltä kutsuttu. Niin minä siis teiltä kysyn: mitä varten te minua kutsuitte?"],[10,30,"Ja Kornelius sanoi: minä olen neljä päivää sitten paastonnut tähän hetkeen asti, ja rukoilin huoneessani yhdeksännellä hetkellä, ja katso, mies seisoi kiiltävissä vaatteissa minun edessäni,","Ja Kornelius sanoi: minä olen neljä päivää sitten paastonnut tähän hetkeen asti, ja rukoilin huoneessani yhdeksännellä hetkellä, ja katso, mies seisoi kiiltävissä vaatteissa minun edessäni,"],[10,31,"Ja sanoi: Kornelius, rukoukses on kuultu ja almus ovat Jumalan edessä muistetut.","Ja sanoi: Kornelius, rukoukses on kuultu ja almus ovat Jumalan edessä muistetut."],[10,32,"Niin lähetä Joppeen ja kutsuta Simonin, joka Pietariksi kutsutaan; hän pitää majaa Simon Parkkarin huoneessa, meren tykönä: se puhuttelee sinua, kuin hän tulee.","Niin lähetä Joppeen ja kutsuta Simonin, joka Pietariksi kutsutaan; hän pitää majaa Simon Parkkarin huoneessa, meren tykönä: se puhuttelee sinua, kuin hän tulee."],[10,33,"Niin minä lähetin kohta sinun tykös, ja sinä teit hyvin, ettäs tulit. Ja me olemme siis kaikki nyt Jumalan edessä, kuulemassa kaikkia, mitä sinulle on Jumalalta käsketty.","Niin minä lähetin kohta sinun tykös, ja sinä teit hyvin, ettäs tulit. Ja me olemme siis kaikki nyt Jumalan edessä, kuulemassa kaikkia, mitä sinulle on Jumalalta käsketty."],[10,34,"Niin Pietari avasi suunsa ja sanoi: nyt minä todeksi löydän, ettei Jumala katso ihmisen muotoa:","Niin Pietari avasi suunsa ja sanoi: nyt minä todeksi löydän, ettei Jumala katso ihmisen muotoa:"],[10,35,"Vaan kaikissa kansoissa, joka häntä pelkää ja tekee vanhurskautta, se on Jumalalle otollinen.","Vaan kaikissa kansoissa, joka häntä pelkää ja tekee vanhurskautta, se on Jumalalle otollinen."],[10,36,"Sen sanan, jonka Jumala Israelin lapsille lähetti ja julisti rauhan Jesuksen Kristuksen kautta, joka kaikkein Herra on,","Sen sanan, jonka Jumala Israelin lapsille lähetti ja julisti rauhan Jesuksen Kristuksen kautta, joka kaikkein Herra on,"],[10,37,"Te tiedätte sen sanan, joka on tapahtunut ympäri kaiken Juudean, ensin alkain Galileasta, sen kasteen jälkeen, josta Johannes saarnasi:","Te tiedätte sen sanan, joka on tapahtunut ympäri kaiken Juudean, ensin alkain Galileasta, sen kasteen jälkeen, josta Johannes saarnasi:"],[10,38,"Kuinka Jumala oli voidellut Jesuksen Nasaretista Pyhällä Hengellä ja voimalla, joka vaelsi ympäri, teki hyvää ja paransi kaikki, jotka perkeleeltä vaivattiin; sillä Jumala oli hänen kanssansa.","Kuinka Jumala oli voidellut Jesuksen Nasaretista Pyhällä Hengellä ja voimalla, joka vaelsi ympäri, teki hyvää ja paransi kaikki, jotka perkeleeltä vaivattiin; sillä Jumala oli hänen kanssansa."],[10,39,"Ja me olemme kaikkien niiden todistajat, mitkä hän Juudean maakunnassa ja Jerusalemissa teki, jonka he tappoivat ja ripustivat puuhun:","Ja me olemme kaikkien niiden todistajat, mitkä hän Juudean maakunnassa ja Jerusalemissa teki, jonka he tappoivat ja ripustivat puuhun:"],[10,40,"Sen Jumala herätti kolmantena päivänä, ja ilmoitti hänen,","Sen Jumala herätti kolmantena päivänä, ja ilmoitti hänen,"],[10,41,"Ei kaikelle kansalle, vaan meille, jotka Jumala oli ennen todistajiksi valinnut, me jotka söimme ja joimme hänen kanssansa, sittenkuin hän nousi kuolleista.","Ei kaikelle kansalle, vaan meille, jotka Jumala oli ennen todistajiksi valinnut, me jotka söimme ja joimme hänen kanssansa, sittenkuin hän nousi kuolleista."],[10,42,"Ja hän käski meitä kansalle saarnaamaan ja todistamaan, että hän on se, joka Jumalalta on säätty elävien ja kuolleiden tuomariksi.","Ja hän käski meitä kansalle saarnaamaan ja todistamaan, että hän on se, joka Jumalalta on säätty elävien ja kuolleiden tuomariksi."],[10,43,"Hänestä kaikki prophetat todistavat, että jokainen, joka uskoo hänen päällensä, pitää hänen nimensä kautta synnit anteeksi saaman.","Hänestä kaikki prophetat todistavat, että jokainen, joka uskoo hänen päällensä, pitää hänen nimensä kautta synnit anteeksi saaman."],[10,44,"Kuin Pietari vielä näitä puhui, lankesi Pyhä Henki kaikkein niiden päälle, jotka puheen kuulivat.","Kuin Pietari vielä näitä puhui, lankesi Pyhä Henki kaikkein niiden päälle, jotka puheen kuulivat."],[10,45,"Niin ne uskovaiset ympärileikkauksesta, jotka Pietarin kanssa tulleet olivat, hämmästyivät, että pakanainkin päälle Pyhän Hengen lahja vuodatettiin.","Niin ne uskovaiset ympärileikkauksesta, jotka Pietarin kanssa tulleet olivat, hämmästyivät, että pakanainkin päälle Pyhän Hengen lahja vuodatettiin."],[10,46,"Sillä he kuulivat heidän kielillä puhuvan ja Jumalaa ylistävän. Niin vastasi Pietari:","Sillä he kuulivat heidän kielillä puhuvan ja Jumalaa ylistävän. Niin vastasi Pietari:"],[10,47,"Taitaako joku kieltää näitä, jotka ovat niin Pyhän Hengen saaneet kuin mekin, vedellä kastamasta?","Taitaako joku kieltää näitä, jotka ovat niin Pyhän Hengen saaneet kuin mekin, vedellä kastamasta?"],[10,48,"Ja hän käski kastaa heitä Herran nimeen. Silloin he rukoilivat häntä siellä muutamia päiviä viipymään.","Ja hän käski kastaa heitä Herran nimeen. Silloin he rukoilivat häntä siellä muutamia päiviä viipymään."],[11,1,"Mutta apostolit ja veljet, jotka Juudeassa olivat, kuulivat, että pakanatkin Jumalan sanan ottivat vastaan.","Mutta apostolit ja veljet, jotka Juudeassa olivat, kuulivat, että pakanatkin Jumalan sanan ottivat vastaan."],[11,2,"Ja kuin Pietari tuli ylös Jerusalemiin, riitelivät ne hänen kanssansa, jotka ympärileikkauksesta olivat,","Ja kuin Pietari tuli ylös Jerusalemiin, riitelivät ne hänen kanssansa, jotka ympärileikkauksesta olivat,"],[11,3,"Sanoen: sinä olet mennyt niiden miesten tykö, joilla esinahka on, ja söit heidän kanssansa.","Sanoen: sinä olet mennyt niiden miesten tykö, joilla esinahka on, ja söit heidän kanssansa."],[11,4,"Niin Pietari rupesi heille järjestänsä luettelemaan, sanoen:","Niin Pietari rupesi heille järjestänsä luettelemaan, sanoen:"],[11,5,"Minä olin Jopen kaupungissa rukouksissa, ja tulin horroksiin, ja näin näyn, yhden astian tulevan alas, niinkuin suuren liinaisen neljältä kulmalta lasketun alas taivaasta, joka tuli juuri minun tyköni.","Minä olin Jopen kaupungissa rukouksissa, ja tulin horroksiin, ja näin näyn, yhden astian tulevan alas, niinkuin suuren liinaisen neljältä kulmalta lasketun alas taivaasta, joka tuli juuri minun tyköni."],[11,6,"Kuin minä katsoin sen päälle, äkkäsin minä ja näin maan neljäjalkaisia eläimiä, ja petoja, ja matelevaisia, ja taivaan lintuja.","Kuin minä katsoin sen päälle, äkkäsin minä ja näin maan neljäjalkaisia eläimiä, ja petoja, ja matelevaisia, ja taivaan lintuja."],[11,7,"Mutta minä kuulin äänen minulle sanovan: Pietari, nouse, tapa ja syö.","Mutta minä kuulin äänen minulle sanovan: Pietari, nouse, tapa ja syö."],[11,8,"Mutta minä sanoin: en suinkaan, Herra; sillä ei ole mitään yhteistä eli saastaista minun suuhuni koskaan tullut.","Mutta minä sanoin: en suinkaan, Herra; sillä ei ole mitään yhteistä eli saastaista minun suuhuni koskaan tullut."],[11,9,"Mutta ääni vastasi minua toisen kerran taivaasta: mitä Jumala on puhdistanut, älä sinä sano yhteiseksi.","Mutta ääni vastasi minua toisen kerran taivaasta: mitä Jumala on puhdistanut, älä sinä sano yhteiseksi."],[11,10,"Ja se tapahtui kolmasti, ja vietiin taas kaikki ylös taivaaseen.","Ja se tapahtui kolmasti, ja vietiin taas kaikki ylös taivaaseen."],[11,11,"Ja katso, kolme miestä seisoi kohta huoneen edessä, jossa minä olin, jotka Kesareasta olivat minun perääni lähetetyt.","Ja katso, kolme miestä seisoi kohta huoneen edessä, jossa minä olin, jotka Kesareasta olivat minun perääni lähetetyt."],[11,12,"Mutta Henki käski minun epäilemättä mennä heidän kanssansa; ja nämät kuusi veljeä seurasivat myös minua, ja me menimme sen miehen huoneeseen.","Mutta Henki käski minun epäilemättä mennä heidän kanssansa; ja nämät kuusi veljeä seurasivat myös minua, ja me menimme sen miehen huoneeseen."],[11,13,"Ja hän jutteli meille, kuinka hän oli enkelin nähnyt huoneessansa seisovan ja sanovan hänelle: lähetä miehiä Joppeen, ja anna noutaa Simonin, joka Pietariksi kutsutaan:","Ja hän jutteli meille, kuinka hän oli enkelin nähnyt huoneessansa seisovan ja sanovan hänelle: lähetä miehiä Joppeen, ja anna noutaa Simonin, joka Pietariksi kutsutaan:"],[11,14,"Hän on sanova sinulle ne sanat, joiden kautta sinä autuaaksi tulet ja kaikki sinun huonees.","Hän on sanova sinulle ne sanat, joiden kautta sinä autuaaksi tulet ja kaikki sinun huonees."],[11,15,"Mutta kuin minä rupesin puhumaan, lankesi Pyhä Henki heidän päällensä, niinkuin hän alussa meidänkin päällemme lankesi.","Mutta kuin minä rupesin puhumaan, lankesi Pyhä Henki heidän päällensä, niinkuin hän alussa meidänkin päällemme lankesi."],[11,16,"Niin minä muistin Herran sanan, jonka hän sanonut oli: Johannes tosin kasti vedellä, mutta te kastetaan Pyhällä Hengellä.","Niin minä muistin Herran sanan, jonka hän sanonut oli: Johannes tosin kasti vedellä, mutta te kastetaan Pyhällä Hengellä."],[11,17,"Että nyt Jumala yhdenkaltaisen lahjan heille antoi kuin meillekin, jotka Herran Jesuksen Kristuksen päälle uskoimme: mikäs minä olisin, joka voisin kieltää Jumalaa?","Että nyt Jumala yhdenkaltaisen lahjan heille antoi kuin meillekin, jotka Herran Jesuksen Kristuksen päälle uskoimme: mikäs minä olisin, joka voisin kieltää Jumalaa?"],[11,18,"Kuin he nämät kuulivat, vaikenivat he ja kunnioittivat Jumalaa, sanoen: niin on siis Jumala antanut pakanoillekin kääntymyksen elämään.","Kuin he nämät kuulivat, vaikenivat he ja kunnioittivat Jumalaa, sanoen: niin on siis Jumala antanut pakanoillekin kääntymyksen elämään."],[11,19,"Ja ne, jotka siitä vainosta hajonneet olivat, joka Stephanin tähden tapahtui, vaelsivat ympäri hamaan Phenisiaan ja Kypriin ja Antiokiaan asti, eikä kellenkään sitä sanaa puhuneet, vaan ainoasti Juudalaisille.","Ja ne, jotka siitä vainosta hajonneet olivat, joka Stephanin tähden tapahtui, vaelsivat ympäri hamaan Phenisiaan ja Kypriin ja Antiokiaan asti, eikä kellenkään sitä sanaa puhuneet, vaan ainoasti Juudalaisille."],[11,20,"Ja oli muutamia miehiä heidän seassansa Kypristä ja Kyrenistä: kuin ne tulivat Antiokiaan, puhuivat he Grekiläisille ja saarnasivat evankeliumia Herrasta Jesuksesta.","Ja oli muutamia miehiä heidän seassansa Kypristä ja Kyrenistä: kuin ne tulivat Antiokiaan, puhuivat he Grekiläisille ja saarnasivat evankeliumia Herrasta Jesuksesta."],[11,21,"Ja Herran käsi oli heidän kanssansa, ja suuri joukko uskoi ja kääntyi Herran tykö.","Ja Herran käsi oli heidän kanssansa, ja suuri joukko uskoi ja kääntyi Herran tykö."],[11,22,"Niin tämä sanoma heistä tuli seurakunnan korville, joka Jerusalemissa oli, ja he lähettivät Barnabaan Antiokiaan.","Niin tämä sanoma heistä tuli seurakunnan korville, joka Jerusalemissa oli, ja he lähettivät Barnabaan Antiokiaan."],[11,23,"Kuin hän sinne tuli ja näki Jumalan armon, ihastui hän, ja neuvoi kaikkia vahvalla sydämellä Herrassa pysymään;","Kuin hän sinne tuli ja näki Jumalan armon, ihastui hän, ja neuvoi kaikkia vahvalla sydämellä Herrassa pysymään;"],[11,24,"Sillä hän oli jalo mies ja täynnänsä Pyhää Henkeä ja uskoa, ja suuri joukko kansaa eneni Herralle.","Sillä hän oli jalo mies ja täynnänsä Pyhää Henkeä ja uskoa, ja suuri joukko kansaa eneni Herralle."],[11,25,"Niin Barnabas meni Tarsiin Saulusta etsimään; ja kuin hän löysi hänen, toi hän hänen Antiokiaan.","Niin Barnabas meni Tarsiin Saulusta etsimään; ja kuin hän löysi hänen, toi hän hänen Antiokiaan."],[11,26,"Ja tapahtui, että he koko ajastajan kokoontuivat seurakunnassa ja opettivat paljon kansaa; ja opetuslapsia ruvettiin ensin Antiokiassa kristityiksi kutsumaan.","Ja tapahtui, että he koko ajastajan kokoontuivat seurakunnassa ja opettivat paljon kansaa; ja opetuslapsia ruvettiin ensin Antiokiassa kristityiksi kutsumaan."],[11,27,"Ja niinä päivinä tuli prophetaita Jerusalemista Antiokiaan.","Ja niinä päivinä tuli prophetaita Jerusalemista Antiokiaan."],[11,28,"Ja yksi heistä, Agabus nimeltä, nousi ja ilmoitti heille hengen kautta, kaikkeen maailmaan suuren nälän tulevan, joka myös Klaudius keisarin alla tapahtui.","Ja yksi heistä, Agabus nimeltä, nousi ja ilmoitti heille hengen kautta, kaikkeen maailmaan suuren nälän tulevan, joka myös Klaudius keisarin alla tapahtui."],[11,29,"Mutta opetuslapset sääsivät jotakin lähettää, kuin kullakin varaa oli, veljien avuksi, jotka Juudeassa asuivat,","Mutta opetuslapset sääsivät jotakin lähettää, kuin kullakin varaa oli, veljien avuksi, jotka Juudeassa asuivat,"],[11,30,"Niinkuin he tekivätkin, ja lähettivät vanhimmille Barnabaan ja Sauluksen kätten kautta.","Niinkuin he tekivätkin, ja lähettivät vanhimmille Barnabaan ja Sauluksen kätten kautta."],[12,1,"Mutta sillä ajalla otti kuningas Herodes muutamia seurakunnasta kiinni, vaivataksensa,","Mutta sillä ajalla otti kuningas Herodes muutamia seurakunnasta kiinni, vaivataksensa,"],[12,2,"Ja mestasi Jakobin, Johanneksen veljen miekalla.","Ja mestasi Jakobin, Johanneksen veljen miekalla."],[12,3,"Ja kuin hän näki sen Juudalaisille kelpaavan, pyysi hän myös Pietaria käsittää, (ja se oli makian leivän päivänä.)","Ja kuin hän näki sen Juudalaisille kelpaavan, pyysi hän myös Pietaria käsittää, (ja se oli makian leivän päivänä.)"],[12,4,"Jonka hän myös käsitti, ja pani vankiuteen, ja antoi hänen neljän sotamiesten neljänneksen haltuun vartioida häntä, ja ajatteli pääsiäisen jälkeen asettaa hänen kansan eteen.","Jonka hän myös käsitti, ja pani vankiuteen, ja antoi hänen neljän sotamiesten neljänneksen haltuun vartioida häntä, ja ajatteli pääsiäisen jälkeen asettaa hänen kansan eteen."],[12,5,"Niin Pietari pidettiin tornissa; mutta seurakunnassa tapahtuivat rukoukset hartaasti hänen edestänsä Jumalan tykö.","Niin Pietari pidettiin tornissa; mutta seurakunnassa tapahtuivat rukoukset hartaasti hänen edestänsä Jumalan tykö."],[12,6,"Ja kuin Herodes tahtoi hänen ottaa edes, makasi Pietari sinä yönä kahden sotamiehen vaiheella, sidottuna kaksilla kahleilla, ja vartiat oven edessä vartioitsivat tornia.","Ja kuin Herodes tahtoi hänen ottaa edes, makasi Pietari sinä yönä kahden sotamiehen vaiheella, sidottuna kaksilla kahleilla, ja vartiat oven edessä vartioitsivat tornia."],[12,7,"Ja katso, Herran enkeli seisoi hänen tykönänsä ja kirkkaus paisti huoneessa, lykkäsi Pietaria kylkeen, herätti hänen ja sanoi: nouse nopiasti. Ja kahleet putosivat hänen käsistänsä.","Ja katso, Herran enkeli seisoi hänen tykönänsä ja kirkkaus paisti huoneessa, lykkäsi Pietaria kylkeen, herätti hänen ja sanoi: nouse nopiasti. Ja kahleet putosivat hänen käsistänsä."],[12,8,"Niin enkeli sanoi hänelle: sonnusta ja kengitä sinus. Ja hän teki niin. Ja hän sanoi vielä hänelle: pue itses vaatteisiis ja seuraa minua.","Niin enkeli sanoi hänelle: sonnusta ja kengitä sinus. Ja hän teki niin. Ja hän sanoi vielä hänelle: pue itses vaatteisiis ja seuraa minua."],[12,9,"Ja hän meni ulos ja seurasi häntä, eikä tietänyt sitä todeksi, mitä enkeliltä tehtiin, vaan luuli näyn näkevänsä.","Ja hän meni ulos ja seurasi häntä, eikä tietänyt sitä todeksi, mitä enkeliltä tehtiin, vaan luuli näyn näkevänsä."],[12,10,"Mutta kuin he menivät ensimäisen ja toisen vartion lävitse, ja tulivat rautaiseen porttiin, joka vie kaupunkiin, niin se aukeni heille itsestänsä; ja he menivät siitä ulos, käyden katua myöten, ja kohta erkani enkeli hänestä.","Mutta kuin he menivät ensimäisen ja toisen vartion lävitse, ja tulivat rautaiseen porttiin, joka vie kaupunkiin, niin se aukeni heille itsestänsä; ja he menivät siitä ulos, käyden katua myöten, ja kohta erkani enkeli hänestä."],[12,11,"Ja kuin Pietari tointui entisellensä, sanoi hän: nyt minä totisesti tiedän, että Herra on enkelinsä lähettänyt, ja minun Herodeksen käsistä päästänyt ja kaikesta Juudan kansan toivosta.","Ja kuin Pietari tointui entisellensä, sanoi hän: nyt minä totisesti tiedän, että Herra on enkelinsä lähettänyt, ja minun Herodeksen käsistä päästänyt ja kaikesta Juudan kansan toivosta."],[12,12,"Ja kuin hän tätä ajatellut oli, tuli hän Marian, Johanneksen äidin, huoneen tykö, joka Markukseksi kutsuttiin, jossa monta oli koossa, ja rukoilivat.","Ja kuin hän tätä ajatellut oli, tuli hän Marian, Johanneksen äidin, huoneen tykö, joka Markukseksi kutsuttiin, jossa monta oli koossa, ja rukoilivat."],[12,13,"Mutta kuin Pietari porstuan oveen kolkutti, tuli piika, Roode nimeltä, kuultelemaan.","Mutta kuin Pietari porstuan oveen kolkutti, tuli piika, Roode nimeltä, kuultelemaan."],[12,14,"Ja kuin hän Pietarin äänen tunsi, ei hän ovea ilon tähden avannutkaan, vaan juoksi sisälle ja ilmoitti heille Pietarin porstuan edessä seisovan.","Ja kuin hän Pietarin äänen tunsi, ei hän ovea ilon tähden avannutkaan, vaan juoksi sisälle ja ilmoitti heille Pietarin porstuan edessä seisovan."],[12,15,"Niin he sanoivat hänelle: oletkos hullu? Vaan hän sanoi totisesti niin olevan. Niin he sanoivat: se on hänen enkelinsä.","Niin he sanoivat hänelle: oletkos hullu? Vaan hän sanoi totisesti niin olevan. Niin he sanoivat: se on hänen enkelinsä."],[12,16,"Mutta Pietari kolkutti lakkaamatta. Kuin he avasivat, niin he näkivät hänen ja hämmästyivät.","Mutta Pietari kolkutti lakkaamatta. Kuin he avasivat, niin he näkivät hänen ja hämmästyivät."],[12,17,"Mutta hän viittasi kädellänsä heitä vaikenemaan, ja jutteli heille, kuinka Herra oli hänen vankiudesta johdattanut ulos, ja sanoi: ilmoittakaat näitä Jakobille ja veljille. Ja läksi ulos ja meni toiseen paikkaan.","Mutta hän viittasi kädellänsä heitä vaikenemaan, ja jutteli heille, kuinka Herra oli hänen vankiudesta johdattanut ulos, ja sanoi: ilmoittakaat näitä Jakobille ja veljille. Ja läksi ulos ja meni toiseen paikkaan."],[12,18,"Mutta kuin päivä tuli, niin ei sotamiehillä ollut vähin kapina, kuhunka Pietari tullut oli.","Mutta kuin päivä tuli, niin ei sotamiehillä ollut vähin kapina, kuhunka Pietari tullut oli."],[12,19,"Ja kuin Herodes piti sanan hänen perässänsä, eikä häntä löytänyt, antoi hän vartiat tutkia ja käski heitä rangaista. Ja meni Juudeasta alas Kesareaan ja viipyi siellä.","Ja kuin Herodes piti sanan hänen perässänsä, eikä häntä löytänyt, antoi hän vartiat tutkia ja käski heitä rangaista. Ja meni Juudeasta alas Kesareaan ja viipyi siellä."],[12,20,"Ja Herodes oli vihoissansa Tyron ja Sidonin asuvaisille; mutta he tulivat yksimielisesti hänen tykönsä ja lepyttivät kuninkaan kamaripalvelian Blastuksen, ja anoivat rauhaa; sillä heidän maakuntansa sai kuninkaan maasta elatuksensa.","Ja Herodes oli vihoissansa Tyron ja Sidonin asuvaisille; mutta he tulivat yksimielisesti hänen tykönsä ja lepyttivät kuninkaan kamaripalvelian Blastuksen, ja anoivat rauhaa; sillä heidän maakuntansa sai kuninkaan maasta elatuksensa."],[12,21,"Mutta määrättynä päivänä oli Herodes puetettu kuninkaallisissa vaatteissa, istuen tuomioistuimella, ja piti puheen heidän tykönsä.","Mutta määrättynä päivänä oli Herodes puetettu kuninkaallisissa vaatteissa, istuen tuomioistuimella, ja piti puheen heidän tykönsä."],[12,22,"Mutta kansa huusi: Jumalan ääni, ja ei ihmisen.","Mutta kansa huusi: Jumalan ääni, ja ei ihmisen."],[12,23,"Ja Herran enkeli löi kohta häntä, ettei hän kunniaa Jumalalle antanut. Ja hän syötiin madoilta, ja antoi henkensä.","Ja Herran enkeli löi kohta häntä, ettei hän kunniaa Jumalalle antanut. Ja hän syötiin madoilta, ja antoi henkensä."],[12,24,"Mutta Jumalan sana kasvoi ja eneni.","Mutta Jumalan sana kasvoi ja eneni."],[12,25,"Mutta Barnabas ja Saulus palasivat Jerusalemista, kuin he olivat palveluksen päättäneet, ja ottivat Johanneksen kanssansa, joka myös Markukseksi kutsuttiin.","Mutta Barnabas ja Saulus palasivat Jerusalemista, kuin he olivat palveluksen päättäneet, ja ottivat Johanneksen kanssansa, joka myös Markukseksi kutsuttiin."],[13,1,"Mutta Antiokian seurakunnassa oli muutamia prophetaita ja opettajia, Barnabas ja Simeon, joka Nigeriksi kutsuttiin, ja Lukius Kyreniläinen, ja Manahen, joka Herodes tetrarkan kanssa kasvatettu oli, ja Saulus.","Mutta Antiokian seurakunnassa oli muutamia prophetaita ja opettajia, Barnabas ja Simeon, joka Nigeriksi kutsuttiin, ja Lukius Kyreniläinen, ja Manahen, joka Herodes tetrarkan kanssa kasvatettu oli, ja Saulus."],[13,2,"Kuin siis nämät Herraa palvelivat ja paastosivat, sanoi Pyhä Henki: eroittakaat minulle Barnabas ja Saulus siihen työhön, johon minä heidät olen kutsunut.","Kuin siis nämät Herraa palvelivat ja paastosivat, sanoi Pyhä Henki: eroittakaat minulle Barnabas ja Saulus siihen työhön, johon minä heidät olen kutsunut."],[13,3,"Ja kuin he olivat paastonneet ja rukoilleet, ja kätensä heidän päällensä panneet, päästivät he heidät menemään.","Ja kuin he olivat paastonneet ja rukoilleet, ja kätensä heidän päällensä panneet, päästivät he heidät menemään."],[13,4,"Ja kuin he Pyhältä Hengeltä lähetetyt olivat, menivät he Seleukiaan ja purjehtivat sieltä Kypriin.","Ja kuin he Pyhältä Hengeltä lähetetyt olivat, menivät he Seleukiaan ja purjehtivat sieltä Kypriin."],[13,5,"Ja kuin he Salaminassa olivat, ilmoittivat he Jumalan sanan Juudalaisten synagogissa; ja heillä oli myös Johannes palveliana.","Ja kuin he Salaminassa olivat, ilmoittivat he Jumalan sanan Juudalaisten synagogissa; ja heillä oli myös Johannes palveliana."],[13,6,"Ja kuin he sen luodon lävitse matkustaneet olivat hamaan Paphoon asti, löysivät he velhon, väärän prophetan, Juudalaisen, jonka nimi oli Barjesus,","Ja kuin he sen luodon lävitse matkustaneet olivat hamaan Paphoon asti, löysivät he velhon, väärän prophetan, Juudalaisen, jonka nimi oli Barjesus,"],[13,7,"Joka oli maaherran Sergius Pauluksen, toimellisen miehen kanssa. Se kutsui Barnabaan ja Sauluksen tykönsä, ja halusi kuulla Jumalan sanaa.","Joka oli maaherran Sergius Pauluksen, toimellisen miehen kanssa. Se kutsui Barnabaan ja Sauluksen tykönsä, ja halusi kuulla Jumalan sanaa."],[13,8,"Mutta heitä vastaan seisoi Elimas velho (sillä niin tulkitaan hänen nimensä) ja pyysi kääntää maaherraa pois uskosta.","Mutta heitä vastaan seisoi Elimas velho (sillä niin tulkitaan hänen nimensä) ja pyysi kääntää maaherraa pois uskosta."],[13,9,"Mutta Saulus (joka myös Paavaliksi kutsutaan,) oli täynnä Pyhää Henkeä, katsoi hänen päällensä,","Mutta Saulus (joka myös Paavaliksi kutsutaan,) oli täynnä Pyhää Henkeä, katsoi hänen päällensä,"],[13,10,"Ja sanoi: voi sinä perkeleen poika, täynnä kaikkea vilppiä ja petosta, ja kaiken vanhurskauden vihamies, et sinä lakkaa vääntelemästä Herran oikeita teitä.","Ja sanoi: voi sinä perkeleen poika, täynnä kaikkea vilppiä ja petosta, ja kaiken vanhurskauden vihamies, et sinä lakkaa vääntelemästä Herran oikeita teitä."],[13,11,"Ja nyt katso, Herran käsi on sinun päälläs; ja sinun pitää sokiana oleman eikä näkemän aurinkoa hetkessä aikaa. Ja hänen päällensä lankesi kohta synkeys ja pimeys, ja hän kävi ympäri, etsein kuka häntä kädestä taluttais.","Ja nyt katso, Herran käsi on sinun päälläs; ja sinun pitää sokiana oleman eikä näkemän aurinkoa hetkessä aikaa. Ja hänen päällensä lankesi kohta synkeys ja pimeys, ja hän kävi ympäri, etsein kuka häntä kädestä taluttais."],[13,12,"Kuin maaherra näki, mitä tapahtui, uskoi hän ja ihmetteli Herran opetusta.","Kuin maaherra näki, mitä tapahtui, uskoi hän ja ihmetteli Herran opetusta."],[13,13,"Mutta kuin Paavali ja ne, jotka hänen kanssansa olivat, Paphosta purjehtivat, tulivat he Pamphilian Pergeen; mutta Johannes erkani heistä ja palasi Jerusalemiin.","Mutta kuin Paavali ja ne, jotka hänen kanssansa olivat, Paphosta purjehtivat, tulivat he Pamphilian Pergeen; mutta Johannes erkani heistä ja palasi Jerusalemiin."],[13,14,"Mutta he vaelsivat Pergestä ja tulivat Pisidian Antiokiaan, ja menivät sabbatina synagogaan, ja istuivat.","Mutta he vaelsivat Pergestä ja tulivat Pisidian Antiokiaan, ja menivät sabbatina synagogaan, ja istuivat."],[13,15,"Ja sitte kuin laki ja prophetat olivat luetut, lähettivät synagogan päämiehet heidän tykönsä, sanoen: miehet, rakkaat veljet, onko teillä mitään kansaa neuvomista, niin sanokaat.","Ja sitte kuin laki ja prophetat olivat luetut, lähettivät synagogan päämiehet heidän tykönsä, sanoen: miehet, rakkaat veljet, onko teillä mitään kansaa neuvomista, niin sanokaat."],[13,16,"Niin Paavali nousi ja viittasi kädellänsä heitä vaikenemaan, ja sanoi: Israelin miehet, ja jotka Jumalaa pelkäätte, kuulkaat.","Niin Paavali nousi ja viittasi kädellänsä heitä vaikenemaan, ja sanoi: Israelin miehet, ja jotka Jumalaa pelkäätte, kuulkaat."],[13,17,"Tämän kansan, Israelin, Jumala valitsi meidän isämme, ja korotti tämän kansan, muukalaisena ollessa Egyptin maalla, ja toi heidät sieltä ulos korkialla käsivarrella,","Tämän kansan, Israelin, Jumala valitsi meidän isämme, ja korotti tämän kansan, muukalaisena ollessa Egyptin maalla, ja toi heidät sieltä ulos korkialla käsivarrella,"],[13,18,"Ja kärsi heidän tapojansa korvessa lähes neljäkymmentä ajastaikaa.","Ja kärsi heidän tapojansa korvessa lähes neljäkymmentä ajastaikaa."],[13,19,"Ja peräti kadotti Kanaanin maalla seitsemän kansaa, ja arvalla jakoi heille niiden maan.","Ja peräti kadotti Kanaanin maalla seitsemän kansaa, ja arvalla jakoi heille niiden maan."],[13,20,"Ja sitte lähes neljäsataa ja viisikymmentä ajastaikaa antoi hän heille tuomarit, Samuel prophetaan asti.","Ja sitte lähes neljäsataa ja viisikymmentä ajastaikaa antoi hän heille tuomarit, Samuel prophetaan asti."],[13,21,"Ja he pyysivät sitte kuningasta, ja Jumala antoi heille Saulin, Kisin pojan, miehen Benjaminin suvusta, neljäksikymmeneksi vuodeksi.","Ja he pyysivät sitte kuningasta, ja Jumala antoi heille Saulin, Kisin pojan, miehen Benjaminin suvusta, neljäksikymmeneksi vuodeksi."],[13,22,"Ja kuin hän oli sen pannut pois, herätti hän Davidin heidän kuninkaaksensa, josta hän myös todisti ja sanoi: minä löysin Davidin, Jessen pojan, miehen minun sydämeni jälkeen, joka on kaikki minun tahtoni tekevä.","Ja kuin hän oli sen pannut pois, herätti hän Davidin heidän kuninkaaksensa, josta hän myös todisti ja sanoi: minä löysin Davidin, Jessen pojan, miehen minun sydämeni jälkeen, joka on kaikki minun tahtoni tekevä."],[13,23,"Tämän siemenestä on Jumala lupauksensa perään herättänyt Jesuksen Israelille Vapahtajaksi,","Tämän siemenestä on Jumala lupauksensa perään herättänyt Jesuksen Israelille Vapahtajaksi,"],[13,24,"Niinkuin Johannes saarnasi hänen tulemisensa edellä kaikelle Israelin kansalle parannuksen kastetta.","Niinkuin Johannes saarnasi hänen tulemisensa edellä kaikelle Israelin kansalle parannuksen kastetta."],[13,25,"Mutta kuin Johannes juoksun täyttänyt oli, sanoi hän: kenenkä te luulette minun olevan? En minä se ole, mutta katso, hän tulee minun jälkeeni, jonka kenkiä en minä ole kelvollinen jaloista riisumaan.","Mutta kuin Johannes juoksun täyttänyt oli, sanoi hän: kenenkä te luulette minun olevan? En minä se ole, mutta katso, hän tulee minun jälkeeni, jonka kenkiä en minä ole kelvollinen jaloista riisumaan."],[13,26,"Miehet, rakkaat veljet, Abrahamin suvun lapset, ja jotka teissä ovat Jumalaa pelkääväiset, teille on tämän autuuden sana lähetetty.","Miehet, rakkaat veljet, Abrahamin suvun lapset, ja jotka teissä ovat Jumalaa pelkääväiset, teille on tämän autuuden sana lähetetty."],[13,27,"Sillä Jerusalemin asuvaiset ja heidän ylimmäisensä, ettei he tätä tunteneet, ovat he myös prophetain äänet, joita kunakin sabbatina luetaan, tuomitessansa täyttäneet.","Sillä Jerusalemin asuvaiset ja heidän ylimmäisensä, ettei he tätä tunteneet, ovat he myös prophetain äänet, joita kunakin sabbatina luetaan, tuomitessansa täyttäneet."],[13,28,"Ja vaikka ei he yhtään kuoleman syytä löytäneet, anoivat he kuitenkin Pilatukselta, että hän piti tapettaman.","Ja vaikka ei he yhtään kuoleman syytä löytäneet, anoivat he kuitenkin Pilatukselta, että hän piti tapettaman."],[13,29,"Ja kuin he kaikki olivat täyttäneet, mitä hänestä kirjoitettu oli, ottivat he hänen puun päältä ja panivat hautaan.","Ja kuin he kaikki olivat täyttäneet, mitä hänestä kirjoitettu oli, ottivat he hänen puun päältä ja panivat hautaan."],[13,30,"Mutta Jumala herätti hänen kuolleista.","Mutta Jumala herätti hänen kuolleista."],[13,31,"Ja hän on monta päivää niiltä nähty, jotka hänen kanssansa Galileasta Jerusalemiin olivat menneet ylös, jotka ovat hänen todistajansa kansan edessä.","Ja hän on monta päivää niiltä nähty, jotka hänen kanssansa Galileasta Jerusalemiin olivat menneet ylös, jotka ovat hänen todistajansa kansan edessä."],[13,32,"Ja me ilmoitamme myös teille sen lupauksen, joka isille luvattiin, että Jumala on sen meille heidän lapsillensa täyttänyt, herättäin Jesuksen.","Ja me ilmoitamme myös teille sen lupauksen, joka isille luvattiin, että Jumala on sen meille heidän lapsillensa täyttänyt, herättäin Jesuksen."],[13,33,"Niinkuin toisessa psalmissa kirjoitettu on: sinä olet minun Poikani, tänäpänä minä sinun synnytin.","Niinkuin toisessa psalmissa kirjoitettu on: sinä olet minun Poikani, tänäpänä minä sinun synnytin."],[13,34,"Mutta siitä, että hän hänen kuolleista herätti, eikä silleen tule turmelukseen, sanoi hän näin: minä tahdon teille antaa ne lujat Davidin armot.","Mutta siitä, että hän hänen kuolleista herätti, eikä silleen tule turmelukseen, sanoi hän näin: minä tahdon teille antaa ne lujat Davidin armot."],[13,35,"Sentähden hän myös sanoo toisessa paikassa: et sinä salli sinun Pyhäs turmelusta näkevän.","Sentähden hän myös sanoo toisessa paikassa: et sinä salli sinun Pyhäs turmelusta näkevän."],[13,36,"Sillä David, kuin hän ajallansa oli Jumalan tahtoa palvellut, nukkui, ja pantiin isäinsä tykö, ja näki turmeluksen.","Sillä David, kuin hän ajallansa oli Jumalan tahtoa palvellut, nukkui, ja pantiin isäinsä tykö, ja näki turmeluksen."],[13,37,"Mutta se, jonka Jumala herätti, ei ole nähnyt turmelusta.","Mutta se, jonka Jumala herätti, ei ole nähnyt turmelusta."],[13,38,"Sentähden olkoon teille tiettävä, miehet, rakkaat veljet, että teille tämän kautta ilmoitetaan syntein anteeksi antamus:","Sentähden olkoon teille tiettävä, miehet, rakkaat veljet, että teille tämän kautta ilmoitetaan syntein anteeksi antamus:"],[13,39,"Ja kaikista niistä, joista ette voineet Moseksen lain kautta vanhurskaaksi tulla, tämän kautta jokainen, joka uskoo, tulee vanhurskaaksi.","Ja kaikista niistä, joista ette voineet Moseksen lain kautta vanhurskaaksi tulla, tämän kautta jokainen, joka uskoo, tulee vanhurskaaksi."],[13,40,"Katsokaat siis, ettei teidän päällenne se tule, mitä prophetain kautta sanottu on:","Katsokaat siis, ettei teidän päällenne se tule, mitä prophetain kautta sanottu on:"],[13,41,"Katsokaat, te ylönkatsojat, ja ihmetelkäät ja hukkukaat; sillä minä teen yhden työn teidän aikananne, sen työn, jota ei teidän pidä uskoman, jos joku sanois teille.","Katsokaat, te ylönkatsojat, ja ihmetelkäät ja hukkukaat; sillä minä teen yhden työn teidän aikananne, sen työn, jota ei teidän pidä uskoman, jos joku sanois teille."],[13,42,"Kuin Juudalaiset synagogasta läksivät, rukoilivat pakanat, että sabbatin välissä heille niitä sanoja puhuttaisiin.","Kuin Juudalaiset synagogasta läksivät, rukoilivat pakanat, että sabbatin välissä heille niitä sanoja puhuttaisiin."],[13,43,"Ja kuin synagogan joukko erkani, seurasi monta Juudalaista ja myös monta jumalista uutta Juudalaista Paavalia ja Barnabasta, jotka heille puhuivat, ja heitä neuvoivat Jumalan armossa pysymään.","Ja kuin synagogan joukko erkani, seurasi monta Juudalaista ja myös monta jumalista uutta Juudalaista Paavalia ja Barnabasta, jotka heille puhuivat, ja heitä neuvoivat Jumalan armossa pysymään."],[13,44,"Mutta sitte lähimmäisenä lepopäivänä kokoontui lähes kaikki kaupunki Jumalan sanaa kuulemaan.","Mutta sitte lähimmäisenä lepopäivänä kokoontui lähes kaikki kaupunki Jumalan sanaa kuulemaan."],[13,45,"Kuin Juudalaiset näkivät kansan, täytettiin he kateudesta, ja sanoivat vastaan niitä, mitä Paavalilta sanoittiin, sanoen vastaan ja pilkaten.","Kuin Juudalaiset näkivät kansan, täytettiin he kateudesta, ja sanoivat vastaan niitä, mitä Paavalilta sanoittiin, sanoen vastaan ja pilkaten."],[13,46,"Niin Paavali ja Barnabas puhuivat rohkiasti ja sanoivat: teille piti ensin Jumalan sanaa puhuttaman; vaan että te sen hylkäätte ja luette itsenne mahdottomaksi ijankaikkiseen elämään, katso, niin me käännymme pakanain tykö.","Niin Paavali ja Barnabas puhuivat rohkiasti ja sanoivat: teille piti ensin Jumalan sanaa puhuttaman; vaan että te sen hylkäätte ja luette itsenne mahdottomaksi ijankaikkiseen elämään, katso, niin me käännymme pakanain tykö."],[13,47,"Sillä niin on Herra meitä käskenyt: minä panin sinun pakanain valkeudeksi, ettäs olisit autuus, maan ääriin asti.","Sillä niin on Herra meitä käskenyt: minä panin sinun pakanain valkeudeksi, ettäs olisit autuus, maan ääriin asti."],[13,48,"Ja kuin pakanat sen kuulivat, iloitsivat he ja kunnioittivat Herran sanaa; ja niin monta uskoi, kuin ijankaikkiseen elämään säädetty oli.","Ja kuin pakanat sen kuulivat, iloitsivat he ja kunnioittivat Herran sanaa; ja niin monta uskoi, kuin ijankaikkiseen elämään säädetty oli."],[13,49,"Ja Herran sana leveni kaikkeen siihen maakuntaan.","Ja Herran sana leveni kaikkeen siihen maakuntaan."],[13,50,"Mutta Juudalaiset yllyttivät jumalisia ja kunniallisia vaimoja, niin myös kaupungin ylimmäisiä, ja kehoittivat vainon Paavalia ja Barnabasta vastaan; ja he sysäsivät heidät ulos maansa ääristä.","Mutta Juudalaiset yllyttivät jumalisia ja kunniallisia vaimoja, niin myös kaupungin ylimmäisiä, ja kehoittivat vainon Paavalia ja Barnabasta vastaan; ja he sysäsivät heidät ulos maansa ääristä."],[13,51,"Mutta he pudistivat tomun jaloistansa heidän päällensä, ja tulivat Ikonioon.","Mutta he pudistivat tomun jaloistansa heidän päällensä, ja tulivat Ikonioon."],[13,52,"Niin opetuslapset täytettiin ilolla ja Pyhällä Hengellä.","Niin opetuslapset täytettiin ilolla ja Pyhällä Hengellä."],[14,1,"Niin Ikoniossa tapahtui, että he ynnä menivät sisälle Juudalaisten synagogaan, ja niin puhuivat, että suuri joukko Juudalaisia ja Grekiläisiä uskoi.","Niin Ikoniossa tapahtui, että he ynnä menivät sisälle Juudalaisten synagogaan, ja niin puhuivat, että suuri joukko Juudalaisia ja Grekiläisiä uskoi."],[14,2,"Mutta uskomattomat Juudalaiset yllyttivät ja pahoittivat pakanain sielut veljiä vastaan.","Mutta uskomattomat Juudalaiset yllyttivät ja pahoittivat pakanain sielut veljiä vastaan."],[14,3,"Niin he olivat siellä kauvan aikaa ja puhuivat rohkiasti Herrassa, joka antoi todistuksen armonsa sanoihin, ja antoi merkit ja ihmeet heidän kättensä kautta tapahtua.","Niin he olivat siellä kauvan aikaa ja puhuivat rohkiasti Herrassa, joka antoi todistuksen armonsa sanoihin, ja antoi merkit ja ihmeet heidän kättensä kautta tapahtua."],[14,4,"Niin sen kaupungin väki erkani: muutamat pitivät Juudalaisten kanssa, ja muutamat apostolien kanssa.","Niin sen kaupungin väki erkani: muutamat pitivät Juudalaisten kanssa, ja muutamat apostolien kanssa."],[14,5,"Kuin siis pakanoilta ja Juudalaisilta kapina nousi, ynnä heidän päämiestensä kanssa, pilkkaamaan ja kivittämään heitä,","Kuin siis pakanoilta ja Juudalaisilta kapina nousi, ynnä heidän päämiestensä kanssa, pilkkaamaan ja kivittämään heitä,"],[14,6,"Ja kuin he sen ymmärsivät, pakenivat he Lykaonian kaupunkeihin Lystraan ja Derbeen, ja ympäri sitä lähimaakuntaa,","Ja kuin he sen ymmärsivät, pakenivat he Lykaonian kaupunkeihin Lystraan ja Derbeen, ja ympäri sitä lähimaakuntaa,"],[14,7,"Ja saarnasivat niissä evankeliumia.","Ja saarnasivat niissä evankeliumia."],[14,8,"Ja mies Lystrassa, sairas jaloista, istui, rampa hamasta äitinsä kohdusta, joka ei ikänänsä ollut käynyt.","Ja mies Lystrassa, sairas jaloista, istui, rampa hamasta äitinsä kohdusta, joka ei ikänänsä ollut käynyt."],[14,9,"Tämä kuuli Paavalin puhuvan; ja kuin hän katsahti hänen päällensä, ja näki hänellä uskon olevan terveeksi tulla,","Tämä kuuli Paavalin puhuvan; ja kuin hän katsahti hänen päällensä, ja näki hänellä uskon olevan terveeksi tulla,"],[14,10,"Sanoi hän suurella äänellä: ojenna sinus jalkais päälle. Ja hän karkasi ylös ja kävi.","Sanoi hän suurella äänellä: ojenna sinus jalkais päälle. Ja hän karkasi ylös ja kävi."],[14,11,"Kuin kansa sen näki, mitä Paavali tehnyt oli, korottivat he äänensä Lykaonian kielellä sanoen: jumalat ovat ihmisten hahmolla alas meidän tykömme tulleet.","Kuin kansa sen näki, mitä Paavali tehnyt oli, korottivat he äänensä Lykaonian kielellä sanoen: jumalat ovat ihmisten hahmolla alas meidän tykömme tulleet."],[14,12,"Ja he kutsuivat Barnabaan Jupiteriksi ja Paavalin Merkuriukseksi; sillä hän oli sanansaattaja.","Ja he kutsuivat Barnabaan Jupiteriksi ja Paavalin Merkuriukseksi; sillä hän oli sanansaattaja."],[14,13,"Ja pappi Jupiterin templissä, joka heidän kaupunkinsa edessä oli, toi härkiä ja seppeleitä oven eteen, ja tahtoi ynnä kaupungin väen kanssa uhrata.","Ja pappi Jupiterin templissä, joka heidän kaupunkinsa edessä oli, toi härkiä ja seppeleitä oven eteen, ja tahtoi ynnä kaupungin väen kanssa uhrata."],[14,14,"Kuin apostolit Barnabas ja Paavali sen kuulivat, repäisivät he vaattensa ja karkasivat kansan sekaan, huutain,","Kuin apostolit Barnabas ja Paavali sen kuulivat, repäisivät he vaattensa ja karkasivat kansan sekaan, huutain,"],[14,15,"Ja sanoen: miehet, miksi te tätä teette? Mekin olemme ihmiset, puuttuvaiset kuin tekin. Ja me saarnaamme teille evankeliumia, että te näistä turhista kääntyisitte elävän Jumalan tykö, joka teki taivaan, ja maan, ja meren, ja kaikki mitä niissä on,","Ja sanoen: miehet, miksi te tätä teette? Mekin olemme ihmiset, puuttuvaiset kuin tekin. Ja me saarnaamme teille evankeliumia, että te näistä turhista kääntyisitte elävän Jumalan tykö, joka teki taivaan, ja maan, ja meren, ja kaikki mitä niissä on,"],[14,16,"Joka entisillä ajoilla antoi kaikki pakanat vaeltaa omilla teillänsä.","Joka entisillä ajoilla antoi kaikki pakanat vaeltaa omilla teillänsä."],[14,17,"Vaikka ei hän itsiänsä antanut olla ilman todistusta, tehden hyvää, antain meille taivaasta sateen ja hedelmälliset ajat, täyttäin meidän sydämemme rualla ja ilolla.","Vaikka ei hän itsiänsä antanut olla ilman todistusta, tehden hyvää, antain meille taivaasta sateen ja hedelmälliset ajat, täyttäin meidän sydämemme rualla ja ilolla."],[14,18,"Ja kuin he näitä sanoivat, saivat he kansan tuskalla hillityksi, ettei he heille uhranneet.","Ja kuin he näitä sanoivat, saivat he kansan tuskalla hillityksi, ettei he heille uhranneet."],[14,19,"Niin sinne myös tuli muutamia Juudalaisia Antiokiasta ja Ikoniosta, ja kuin he kansan olivat saattaneet Paavalia kivittämään, riepoittivat he hänen ulos kaupungista, ja luulivat hänen kuolleeksi.","Niin sinne myös tuli muutamia Juudalaisia Antiokiasta ja Ikoniosta, ja kuin he kansan olivat saattaneet Paavalia kivittämään, riepoittivat he hänen ulos kaupungista, ja luulivat hänen kuolleeksi."],[14,20,"Mutta kuin opetuslapset hänen ympärillänsä seisoivat, nousi hän ja meni kaupunkiin, ja vaelsi toisena päivänä Barnabaan kanssa Derbeen.","Mutta kuin opetuslapset hänen ympärillänsä seisoivat, nousi hän ja meni kaupunkiin, ja vaelsi toisena päivänä Barnabaan kanssa Derbeen."],[14,21,"Ja kuin he olivat saarnanneet siinä kaupungissa evankeliumia ja monta opettaneet, palasivat he Lystraan ja Ikonioon ja Antiokiaan,","Ja kuin he olivat saarnanneet siinä kaupungissa evankeliumia ja monta opettaneet, palasivat he Lystraan ja Ikonioon ja Antiokiaan,"],[14,22,"Vahvistain opetuslasten sieluja, ja neuvoivat heitä uskossa pysymään (sanoen): että meidän pitää monen vaivan kautta Jumalan valtakuntaan tuleman sisälle.","Vahvistain opetuslasten sieluja, ja neuvoivat heitä uskossa pysymään (sanoen): että meidän pitää monen vaivan kautta Jumalan valtakuntaan tuleman sisälle."],[14,23,"Ja kuin he olivat valinneet vanhimmat jokaiselle seurakunnalle, ja rukoilleet ja paastonneet, antoivat he heidät Herran haltuun, jonka päälle he uskoivat.","Ja kuin he olivat valinneet vanhimmat jokaiselle seurakunnalle, ja rukoilleet ja paastonneet, antoivat he heidät Herran haltuun, jonka päälle he uskoivat."],[14,24,"Ja he vaelsivat lävitse Pisidian ja tulivat Pamphiliaan.","Ja he vaelsivat lävitse Pisidian ja tulivat Pamphiliaan."],[14,25,"Ja kuin he olivat saarnanneet sanaa Pergessä, menivät he alas Attaliaan,","Ja kuin he olivat saarnanneet sanaa Pergessä, menivät he alas Attaliaan,"],[14,26,"Ja purjehtivat sieltä Antiokiaan, jossa he olivat Jumalan armon haltuun annetut, siihen työhön, jonka he toimittaneet olivat.","Ja purjehtivat sieltä Antiokiaan, jossa he olivat Jumalan armon haltuun annetut, siihen työhön, jonka he toimittaneet olivat."],[14,27,"Mutta kuin he sinne tulivat ja seurakunnan kokosivat, ilmoittivat he, kuinka paljon Jumala oli heidän kanssansa tehnyt ja pakanoille uskon oven avannut.","Mutta kuin he sinne tulivat ja seurakunnan kokosivat, ilmoittivat he, kuinka paljon Jumala oli heidän kanssansa tehnyt ja pakanoille uskon oven avannut."],[14,28,"Ja he viipyivät siellä opetuslasten kanssa hetken aikaa.","Ja he viipyivät siellä opetuslasten kanssa hetken aikaa."],[15,1,"Ja muutamat tulivat alas Juudeasta ja opettivat veljiä: ellei teitä ympärileikata Moseksen tavan jälkeen, niin ette taida autuaaksi tulla.","Ja muutamat tulivat alas Juudeasta ja opettivat veljiä: ellei teitä ympärileikata Moseksen tavan jälkeen, niin ette taida autuaaksi tulla."],[15,2,"Koska siis kapina nousi, ja ei ollut vähin kamppaus Paavalilla ja Barnabaalla heitä vastaan, sääsivät he, että Paavali ja Barnabas ja muutamia muita heistä, piti menemän apostolien ja vanhimpain tykö ylös Jerusalemiin tämän kysymyksen tähden.","Koska siis kapina nousi, ja ei ollut vähin kamppaus Paavalilla ja Barnabaalla heitä vastaan, sääsivät he, että Paavali ja Barnabas ja muutamia muita heistä, piti menemän apostolien ja vanhimpain tykö ylös Jerusalemiin tämän kysymyksen tähden."],[15,3,"Ja he saatettiin seurakunnalta, ja vaelsivat Phenisian ja Samarian lävitse, julistain pakanain kääntymystä, ja saattivat suuren ilon kaikille veljille.","Ja he saatettiin seurakunnalta, ja vaelsivat Phenisian ja Samarian lävitse, julistain pakanain kääntymystä, ja saattivat suuren ilon kaikille veljille."],[15,4,"Kuin he tulivat Jerusalemiin, otettiin he vastaan seurakunnalta ja apostoleilta ja vanhimmilta, ja he ilmoittivat, kuinka suuria töitä Jumala heidän kanssansa tehnyt oli.","Kuin he tulivat Jerusalemiin, otettiin he vastaan seurakunnalta ja apostoleilta ja vanhimmilta, ja he ilmoittivat, kuinka suuria töitä Jumala heidän kanssansa tehnyt oli."],[15,5,"Niin nousivat muutaman Pharisealaisten lahkokunnassa, jotka uskoneet olivat, sanoen: he pitää ympärileikattaman ja käskettämän Moseksen lakia pitää.","Niin nousivat muutaman Pharisealaisten lahkokunnassa, jotka uskoneet olivat, sanoen: he pitää ympärileikattaman ja käskettämän Moseksen lakia pitää."],[15,6,"Niin apostolit ja vanhimmat tulivat kokoon, tätä puhetta tutkimaan.","Niin apostolit ja vanhimmat tulivat kokoon, tätä puhetta tutkimaan."],[15,7,"Mutta kuin suuri kamppaus ollut oli, nousi Pietari ja sanoi heille: miehet, rakkaat veljet! te tiedätte, että Jumala kauvan ennen tätä aikaa valitsi meidän seassamme, että pakanat piti minun suuni kautta evankeliumin sanan kuuleman ja uskoman.","Mutta kuin suuri kamppaus ollut oli, nousi Pietari ja sanoi heille: miehet, rakkaat veljet! te tiedätte, että Jumala kauvan ennen tätä aikaa valitsi meidän seassamme, että pakanat piti minun suuni kautta evankeliumin sanan kuuleman ja uskoman."],[15,8,"Ja Jumala sydänten tutkia todisti heille ja antoi heille Pyhän Hengen niinkuin meillekin,","Ja Jumala sydänten tutkia todisti heille ja antoi heille Pyhän Hengen niinkuin meillekin,"],[15,9,"Ja ei tehnyt yhtään eroitusta meidän ja heidän välillänsä, puhdistain uskolla heidän sydämensä.","Ja ei tehnyt yhtään eroitusta meidän ja heidän välillänsä, puhdistain uskolla heidän sydämensä."],[15,10,"Miksi te siis nyt kiusaatte Jumalaa, että te tahdotte opetuslasten kaulaan panna sen ikeen, jota ei meidän isämme emmekä me voineet kantaa?","Miksi te siis nyt kiusaatte Jumalaa, että te tahdotte opetuslasten kaulaan panna sen ikeen, jota ei meidän isämme emmekä me voineet kantaa?"],[15,11,"Vaan me uskomme Herran Jesuksen Kristuksen armon kautta autuaaksi tulevamme niinkuin hekin.","Vaan me uskomme Herran Jesuksen Kristuksen armon kautta autuaaksi tulevamme niinkuin hekin."],[15,12,"Ja kaikki joukko vaikeni ja kuulteli Barnabasta ja Paavalia, jotka juttelivat, kuinka suuret merkit ja ihmeet Jumala oli heidän kauttansa pakanoissa tehnyt.","Ja kaikki joukko vaikeni ja kuulteli Barnabasta ja Paavalia, jotka juttelivat, kuinka suuret merkit ja ihmeet Jumala oli heidän kauttansa pakanoissa tehnyt."],[15,13,"Vaan sitte kuin he vaikenivat, vastasi Jakob ja sanoi: miehet, rakkaat veljet, kuulkaat minua!","Vaan sitte kuin he vaikenivat, vastasi Jakob ja sanoi: miehet, rakkaat veljet, kuulkaat minua!"],[15,14,"Simon jutteli, kuinka Jumala ensin on etsinyt omistaaksensa kansaa nimellensä pakanoista.","Simon jutteli, kuinka Jumala ensin on etsinyt omistaaksensa kansaa nimellensä pakanoista."],[15,15,"Ja tämän kanssa prophetain sanat pitävät yhtä, niinkuin kirjoitettu on:","Ja tämän kanssa prophetain sanat pitävät yhtä, niinkuin kirjoitettu on:"],[15,16,"Senjälkeen tahdon minä palata, ja Davidin kaatuneen majan jälleen rakentaa, ja hänen reikänsä paikata, ja sen ojentaa:","Senjälkeen tahdon minä palata, ja Davidin kaatuneen majan jälleen rakentaa, ja hänen reikänsä paikata, ja sen ojentaa:"],[15,17,"Että ne, jotka ihmisistä jääneet ovat, pitää Herran perään kysymän, niin myös kaikki pakanat, joissa minun nimeni avuksihuudettu on, sanoo Herra, joka nämät tekee.","Että ne, jotka ihmisistä jääneet ovat, pitää Herran perään kysymän, niin myös kaikki pakanat, joissa minun nimeni avuksihuudettu on, sanoo Herra, joka nämät tekee."],[15,18,"Jumalalle ovat kaikki hänen työnsä tiettävät maailman alusta.","Jumalalle ovat kaikki hänen työnsä tiettävät maailman alusta."],[15,19,"Sentähden minä päätän, ettemme niitä häiritsisi, jotka pakanoista Jumalan tykö kääntyvät;","Sentähden minä päätän, ettemme niitä häiritsisi, jotka pakanoista Jumalan tykö kääntyvät;"],[15,20,"Vaan kirjoittaisimme heille, että he välttäisivät epäjumalain saastaisuutta, ja salavuoteutta, ja läkähtynyttä ja verta.","Vaan kirjoittaisimme heille, että he välttäisivät epäjumalain saastaisuutta, ja salavuoteutta, ja läkähtynyttä ja verta."],[15,21,"Sillä Moseksella on muinaiselta jokaisessa kaupungissa niitä, jotka häntä saarnaavat, koska se joka sabbatina synagogassa luetaan.","Sillä Moseksella on muinaiselta jokaisessa kaupungissa niitä, jotka häntä saarnaavat, koska se joka sabbatina synagogassa luetaan."],[15,22,"Silloin kelpasi apostoleille ja vanhimmille, koko seurakunnan kanssa, joukostansa valita miehiä ja lähettää Antiokiaan, Paavalin ja Barnabaan kanssa: nimittäin Juudaan, joka kutsuttiin Barsabas, ja Silaan, ylimmäiset miehet veljesten seassa.","Silloin kelpasi apostoleille ja vanhimmille, koko seurakunnan kanssa, joukostansa valita miehiä ja lähettää Antiokiaan, Paavalin ja Barnabaan kanssa: nimittäin Juudaan, joka kutsuttiin Barsabas, ja Silaan, ylimmäiset miehet veljesten seassa."],[15,23,"Ja kirjoittivat heidän kättensä kautta tällä tavalla: me apostolit ja vanhimmat veljet toivotamme veljille, jotka pakanoista Antiokiassa ja Syriassa ja Kilikiassa ovat, terveyttä!","Ja kirjoittivat heidän kättensä kautta tällä tavalla: me apostolit ja vanhimmat veljet toivotamme veljille, jotka pakanoista Antiokiassa ja Syriassa ja Kilikiassa ovat, terveyttä!"],[15,24,"Että me olemme kuulleet, kuinka muutamat meiltä lähteneet ovat teitä opillansa eksyttäneet ja teidän sielujanne vaivanneet, sanoen: teidän pitää itsenne antaman ympärileikata ja lain pitämän; joille emme ole käskeneet.","Että me olemme kuulleet, kuinka muutamat meiltä lähteneet ovat teitä opillansa eksyttäneet ja teidän sielujanne vaivanneet, sanoen: teidän pitää itsenne antaman ympärileikata ja lain pitämän; joille emme ole käskeneet."],[15,25,"Niin kelpasi meille yksimielisesti kokoontuneille valita miehiä ja teidän tykönne lähettää, meidän rakkaan Barnabaan ja Paavalin kanssa,","Niin kelpasi meille yksimielisesti kokoontuneille valita miehiä ja teidän tykönne lähettää, meidän rakkaan Barnabaan ja Paavalin kanssa,"],[15,26,"Jotka miehet ovat sielunsa meidän Herramme Jesuksen Kristuksen nimen tähden alttiiksi antaneet.","Jotka miehet ovat sielunsa meidän Herramme Jesuksen Kristuksen nimen tähden alttiiksi antaneet."],[15,27,"Niin me olemme lähettäneet Juudaan ja Silaan, jotka myös sen suusanalla teille ilmoittavat.","Niin me olemme lähettäneet Juudaan ja Silaan, jotka myös sen suusanalla teille ilmoittavat."],[15,28,"Sillä niin kelpasi Pyhälle Hengelle ja meille, ettei yhtään enempää raskautta pidä teidän päällenne pantaman kuin nämät tarpeelliset:","Sillä niin kelpasi Pyhälle Hengelle ja meille, ettei yhtään enempää raskautta pidä teidän päällenne pantaman kuin nämät tarpeelliset:"],[15,29,"Että te vältätte epäjumalain uhria, ja verta, ja läkähtynyttä, ja salavuoteutta. Jos te niitä vältätte, niin te teette hyvin. Olkaat hyvästi!","Että te vältätte epäjumalain uhria, ja verta, ja läkähtynyttä, ja salavuoteutta. Jos te niitä vältätte, niin te teette hyvin. Olkaat hyvästi!"],[15,30,"Kuin he siis olivat lähteneet, tulivat he Antiokiaan, ja kokosivat kansan paljouden, ja antoivat heille kirjan.","Kuin he siis olivat lähteneet, tulivat he Antiokiaan, ja kokosivat kansan paljouden, ja antoivat heille kirjan."],[15,31,"Kuin he sen olivat lukeneet, ihastuivat he siitä lohdutuksesta.","Kuin he sen olivat lukeneet, ihastuivat he siitä lohdutuksesta."],[15,32,"Mutta Juudas ja Silas, että hekin olivat prophetat, neuvoivat monilla sanoilla veljiä ja vahvistivat heitä.","Mutta Juudas ja Silas, että hekin olivat prophetat, neuvoivat monilla sanoilla veljiä ja vahvistivat heitä."],[15,33,"Ja kuin he siellä hetken aikaa viipyivät, lähetettiin he veljiltä jälleen rauhassa apostolien tykö.","Ja kuin he siellä hetken aikaa viipyivät, lähetettiin he veljiltä jälleen rauhassa apostolien tykö."],[15,34,"Niin Silaan kelpasi siellä olla.","Niin Silaan kelpasi siellä olla."],[15,35,"Mutta Paavali ja Barnabas viipyivät Antiokiassa opettamassa ja ilmoittamassa Herran sanaa monen muun kanssa.","Mutta Paavali ja Barnabas viipyivät Antiokiassa opettamassa ja ilmoittamassa Herran sanaa monen muun kanssa."],[15,36,"Mutta muutamain päiväin perästä sanoi Paavali Barnabaalle: palatkaamme taas takaperin veljiä katsomaan kaikkiin kaupunkeihin, joissa me Herran sanaa ilmoittaneet olemme, kuinka he itsensä pitävät.","Mutta muutamain päiväin perästä sanoi Paavali Barnabaalle: palatkaamme taas takaperin veljiä katsomaan kaikkiin kaupunkeihin, joissa me Herran sanaa ilmoittaneet olemme, kuinka he itsensä pitävät."],[15,37,"Mutta Barnabas neuvoi kanssansa ottamaan Johannesta, joka Markukseksi kutsuttiin.","Mutta Barnabas neuvoi kanssansa ottamaan Johannesta, joka Markukseksi kutsuttiin."],[15,38,"Mutta Paavali päätti sen kohtuulliseksi, ettei sitä pitänyt kanssa otettaman, joka oli luopunut heistä Pamphiliassa eikä tullut heidän kanssansa työhön.","Mutta Paavali päätti sen kohtuulliseksi, ettei sitä pitänyt kanssa otettaman, joka oli luopunut heistä Pamphiliassa eikä tullut heidän kanssansa työhön."],[15,39,"Ja he riitelivät niin kovin keskenänsä, että he toinen toisestansa erkanivat. Ja Barnabas otti Markuksen kanssansa ja purjehti Kypriin.","Ja he riitelivät niin kovin keskenänsä, että he toinen toisestansa erkanivat. Ja Barnabas otti Markuksen kanssansa ja purjehti Kypriin."],[15,40,"Mutta Paavali valitsi Silaan ja matkusti, Jumalan armon haltuun annettu veljiltä,","Mutta Paavali valitsi Silaan ja matkusti, Jumalan armon haltuun annettu veljiltä,"],[15,41,"Ja vaelsi Syrian ja Kilikian kautta, ja vahvisti seurakunnat.","Ja vaelsi Syrian ja Kilikian kautta, ja vahvisti seurakunnat."],[16,1,"Niin hän tuli Derbeen ja Lystraan. Ja katso, siellä oli yksi opetuslapsi, Timoteus nimeltä, uskovaisen Juudalaisvaimon poika, mutta isä oli Grekiläinen.","Niin hän tuli Derbeen ja Lystraan. Ja katso, siellä oli yksi opetuslapsi, Timoteus nimeltä, uskovaisen Juudalaisvaimon poika, mutta isä oli Grekiläinen."],[16,2,"Sillä oli hyvä todistus veljiltä, jotka Lystrassa ja Ikoniossa olivat.","Sillä oli hyvä todistus veljiltä, jotka Lystrassa ja Ikoniossa olivat."],[16,3,"Tätä tahtoi Paavali kanssansa vaeltamaan, otti ja ympärileikkasi hänen Juudalaisten tähden, jotka niissä paikoissa olivat; sillä he tiesivät kaikki, että hänen isänsä oli Grekiläinen.","Tätä tahtoi Paavali kanssansa vaeltamaan, otti ja ympärileikkasi hänen Juudalaisten tähden, jotka niissä paikoissa olivat; sillä he tiesivät kaikki, että hänen isänsä oli Grekiläinen."],[16,4,"Mutta kuin he kaupungeita lävitse vaelsivat, antoivat he heille pidettäväksi ne säädyt, jotka asetetut olivat apostoleilta ja vanhimmilta, jotka Jerusalemissa olivat.","Mutta kuin he kaupungeita lävitse vaelsivat, antoivat he heille pidettäväksi ne säädyt, jotka asetetut olivat apostoleilta ja vanhimmilta, jotka Jerusalemissa olivat."],[16,5,"Niin seurakunnat vahvistuivat uskossa ja heidän lukunsa eneni joka päivä.","Niin seurakunnat vahvistuivat uskossa ja heidän lukunsa eneni joka päivä."],[16,6,"Mutta kuin he Phrygian ja Galatian maakunnan lävitse vaelsivat, kiellettiin heitä Pyhältä Hengeltä puhumasta Jumalan sanaa Asiassa.","Mutta kuin he Phrygian ja Galatian maakunnan lävitse vaelsivat, kiellettiin heitä Pyhältä Hengeltä puhumasta Jumalan sanaa Asiassa."],[16,7,"Kuin he olivat tulleet Mysiaan, kiusasivat he vaeltaa Bitynian lävitse; mutta ei Henki sitä sallinut.","Kuin he olivat tulleet Mysiaan, kiusasivat he vaeltaa Bitynian lävitse; mutta ei Henki sitä sallinut."],[16,8,"Kuin he siis Mysian ohitse vaeltaneet olivat, menivät he alas Troadiin.","Kuin he siis Mysian ohitse vaeltaneet olivat, menivät he alas Troadiin."],[16,9,"Ja Paavali näki näyn yöllä: yksi Makedonian mies seisoi, rukoili häntä ja sanoi: tule Makedoniaan ja auta meitä.","Ja Paavali näki näyn yöllä: yksi Makedonian mies seisoi, rukoili häntä ja sanoi: tule Makedoniaan ja auta meitä."],[16,10,"Ja kuin hän näyn näki, hankitsimme me kohta Makedoniaan menemään, tietäen täydellisesti Herran meitä kutsuneen heille evankeliumia saarnaamaan.","Ja kuin hän näyn näki, hankitsimme me kohta Makedoniaan menemään, tietäen täydellisesti Herran meitä kutsuneen heille evankeliumia saarnaamaan."],[16,11,"Kuin me siis Troadista purjehdimme, niin me juoksimme kohdastansa Samotrakiaan, ja toisena päivänä Neapoliin,","Kuin me siis Troadista purjehdimme, niin me juoksimme kohdastansa Samotrakiaan, ja toisena päivänä Neapoliin,"],[16,12,"Ja sieltä Philippiin, joka on Makedonian maakunnan pääkaupunki ja vapaa kaupunki; ja siinä kaupungissa me muutamia päiviä oleskelimme.","Ja sieltä Philippiin, joka on Makedonian maakunnan pääkaupunki ja vapaa kaupunki; ja siinä kaupungissa me muutamia päiviä oleskelimme."],[16,13,"Ja me menimme lepopäivänä ulos kaupungista, virran tykö, kussa tapa oli rukoilla: jossa me istuimme ja puhuttelimme vaimoja, jotka sinne tulleet olivat.","Ja me menimme lepopäivänä ulos kaupungista, virran tykö, kussa tapa oli rukoilla: jossa me istuimme ja puhuttelimme vaimoja, jotka sinne tulleet olivat."],[16,14,"Ja vaimo, Lydia nimeltä, purpurain myyjä Tyatiron kaupungista, Jumalaa palvelevainen, kuulteli: jonka sydämen Herra avasi ottamaan vaaria niistä, mitä Paavalilta sanottiin.","Ja vaimo, Lydia nimeltä, purpurain myyjä Tyatiron kaupungista, Jumalaa palvelevainen, kuulteli: jonka sydämen Herra avasi ottamaan vaaria niistä, mitä Paavalilta sanottiin."],[16,15,"Ja kuin hän ja hänen huoneensa kastettu oli, rukoili hän meitä, sanoen: jos te minun Herralle uskollisena pidätte, niin tulkaat minun huoneeseeni ja olkaat siinä. Ja hän vaati heitä.","Ja kuin hän ja hänen huoneensa kastettu oli, rukoili hän meitä, sanoen: jos te minun Herralle uskollisena pidätte, niin tulkaat minun huoneeseeni ja olkaat siinä. Ja hän vaati heitä."],[16,16,"Ja tapahtui, kuin me rukoukseen menimme, kohtasi meitä piika, jolla noituuden henki oli, joka isännillensä saatti suuren saaliin noitumisellansa.","Ja tapahtui, kuin me rukoukseen menimme, kohtasi meitä piika, jolla noituuden henki oli, joka isännillensä saatti suuren saaliin noitumisellansa."],[16,17,"Tämä noudatti alati Paavalia ja meitä, ja huusi, sanoen: nämät miehet ovat korkeimman Jumalan palveliat, jotka meille autuuden tien ilmoittavat.","Tämä noudatti alati Paavalia ja meitä, ja huusi, sanoen: nämät miehet ovat korkeimman Jumalan palveliat, jotka meille autuuden tien ilmoittavat."],[16,18,"Ja sitä hän teki monta päivää. Mutta Paavali otti sen pahaksi, käänsi itsensä ja sanoi sille hengelle: minä käsken sinun Jesuksen Kristuksen nimeen hänestä mennä ulos; ja hän läksi ulos sillä hetkellä.","Ja sitä hän teki monta päivää. Mutta Paavali otti sen pahaksi, käänsi itsensä ja sanoi sille hengelle: minä käsken sinun Jesuksen Kristuksen nimeen hänestä mennä ulos; ja hän läksi ulos sillä hetkellä."],[16,19,"Mutta kuin hänen isäntänsä sen näkivät, että heidän saaliinsa tuli pois, ottivat he Paavalin ja Silaan kiinni ja veivät heidät turulle päämiesten tykö,","Mutta kuin hänen isäntänsä sen näkivät, että heidän saaliinsa tuli pois, ottivat he Paavalin ja Silaan kiinni ja veivät heidät turulle päämiesten tykö,"],[16,20,"Ja veivät heidän esivallan eteen, ja sanoivat: nämät miehet meidän kaupungin häiritsevät, jotka ovat Juudalaiset,","Ja veivät heidän esivallan eteen, ja sanoivat: nämät miehet meidän kaupungin häiritsevät, jotka ovat Juudalaiset,"],[16,21,"Ja opettavat niitä tapoja, joita ei meidän sovi ottaa vastaan eikä tehdä, sillä me olemme Roomalaiset.","Ja opettavat niitä tapoja, joita ei meidän sovi ottaa vastaan eikä tehdä, sillä me olemme Roomalaiset."],[16,22,"Ja kansa nousi ynnä heitä vastaan, ja esivalta antoi heidän vaatteensa repiä, ja käski heitä piestä.","Ja kansa nousi ynnä heitä vastaan, ja esivalta antoi heidän vaatteensa repiä, ja käski heitä piestä."],[16,23,"Kuin he olivat heidät juuri pahoin pieksäneet, heittivät he heidät torniin ja käskivät vartian visusti heitä vartioida,","Kuin he olivat heidät juuri pahoin pieksäneet, heittivät he heidät torniin ja käskivät vartian visusti heitä vartioida,"],[16,24,"Joka, kuin hän senkaltaisen käskyn sai, heitti heidät sisimmäiseen torniin ja pani heidät jalkapuuhun.","Joka, kuin hän senkaltaisen käskyn sai, heitti heidät sisimmäiseen torniin ja pani heidät jalkapuuhun."],[16,25,"Mutta puoliyön aikana oli Paavali ja Silas rukouksissa, ylistäin Jumalaa kiitosvirsillä, ja vangit, jotka siellä olivat, sen myös kuulivat.","Mutta puoliyön aikana oli Paavali ja Silas rukouksissa, ylistäin Jumalaa kiitosvirsillä, ja vangit, jotka siellä olivat, sen myös kuulivat."],[16,26,"Niin tapahtui äkisti suuri maan järistys, niin että tornin perustus vapisi; ja kohta kaikki ovet aukenivat, ja jokaisen siteet pääsivät.","Niin tapahtui äkisti suuri maan järistys, niin että tornin perustus vapisi; ja kohta kaikki ovet aukenivat, ja jokaisen siteet pääsivät."],[16,27,"Kuin vartia heräsi ja näki tornin ovet avoinna olevan, veti hän ulos miekkansa ja tahtoi surmata itsensä, ja luuli vangit paenneen pois.","Kuin vartia heräsi ja näki tornin ovet avoinna olevan, veti hän ulos miekkansa ja tahtoi surmata itsensä, ja luuli vangit paenneen pois."],[16,28,"Niin Paavali huusi suurella äänellä ja sanoi: älä itselles mitään pahaa tee; sillä me olemme kaikki täällä.","Niin Paavali huusi suurella äänellä ja sanoi: älä itselles mitään pahaa tee; sillä me olemme kaikki täällä."],[16,29,"Niin hän anoi kynttilää, meni sisälle ja lankesi peljästyksissä Paavalin ja Silaan jalkain juureen,","Niin hän anoi kynttilää, meni sisälle ja lankesi peljästyksissä Paavalin ja Silaan jalkain juureen,"],[16,30,"Ja toi heidät ulos ja sanoi: herrat, mitä minun pitää tekemän, että minä autuaaksi tulisin?","Ja toi heidät ulos ja sanoi: herrat, mitä minun pitää tekemän, että minä autuaaksi tulisin?"],[16,31,"Mutta he sanoivat: usko Herran Jesuksen Kristuksen päälle, niin sinä ja sinun huonees autuaaksi tulee.","Mutta he sanoivat: usko Herran Jesuksen Kristuksen päälle, niin sinä ja sinun huonees autuaaksi tulee."],[16,32,"Ja he puhuivat hänelle Herran sanaa ja kaikille, jotka hänen huoneessansa olivat.","Ja he puhuivat hänelle Herran sanaa ja kaikille, jotka hänen huoneessansa olivat."],[16,33,"Ja hän otti heidät sillä hetkellä yöstä tykönsä ja pesi heidän haavansa, ja hän kohta kastettiin ja kaikki hänen perheensä,","Ja hän otti heidät sillä hetkellä yöstä tykönsä ja pesi heidän haavansa, ja hän kohta kastettiin ja kaikki hänen perheensä,"],[16,34,"Ja vei heidät kotiansa, ja valmisti heille pöydän, ja iloitsi, että hän koko huoneensa kanssa tuli Jumalan päälle uskovaiseksi.","Ja vei heidät kotiansa, ja valmisti heille pöydän, ja iloitsi, että hän koko huoneensa kanssa tuli Jumalan päälle uskovaiseksi."],[16,35,"Ja kuin päivä tuli, niin esivalta lähetti kylänlapset sanomaan: päästä ne miehet.","Ja kuin päivä tuli, niin esivalta lähetti kylänlapset sanomaan: päästä ne miehet."],[16,36,"Niin tornin vartia ilmoitti nämät sanat Paavalille, sanoen: esivalta on käskenyt päästää teidät: menkäät siis nyt ulos rauhassa.","Niin tornin vartia ilmoitti nämät sanat Paavalille, sanoen: esivalta on käskenyt päästää teidät: menkäät siis nyt ulos rauhassa."],[16,37,"Mutta Paavali sanoi heille: he ovat julkisesti tuomitsematta pieksäneet meidät, jotka olemme Roomalaiset, ja heittäneet torniin, ja nyt salaa tahtoisivat sysätä meidät ulos. Ei niin, vaan tulkaan he itse meitä ottamaan täältä ulos.","Mutta Paavali sanoi heille: he ovat julkisesti tuomitsematta pieksäneet meidät, jotka olemme Roomalaiset, ja heittäneet torniin, ja nyt salaa tahtoisivat sysätä meidät ulos. Ei niin, vaan tulkaan he itse meitä ottamaan täältä ulos."],[16,38,"Niin kylänlapset ilmoittivat nämät sanat esivallalle jällensä; ja he pelkäsivät, että he heidät Roomalaisiksi kuulivat,","Niin kylänlapset ilmoittivat nämät sanat esivallalle jällensä; ja he pelkäsivät, että he heidät Roomalaisiksi kuulivat,"],[16,39,"Ja tulivat ja rukoilivat heitä, ja veivät heidät ulos, ja käskivät heidän mennä pois kaupungista.","Ja tulivat ja rukoilivat heitä, ja veivät heidät ulos, ja käskivät heidän mennä pois kaupungista."],[16,40,"Niin he läksivät tornista ja menivät Lydian tykö. Ja kuin he veljet nähneet olivat ja heitä lohduttaneet, vaelsivat he matkaansa.","Niin he läksivät tornista ja menivät Lydian tykö. Ja kuin he veljet nähneet olivat ja heitä lohduttaneet, vaelsivat he matkaansa."],[17,1,"Mutta kuin he Amphipolin ja Apollonian lävitse vaeltaneet olivat, tulivat he Tessalonikaan, jossa Juudalaisten synagoga oli.","Mutta kuin he Amphipolin ja Apollonian lävitse vaeltaneet olivat, tulivat he Tessalonikaan, jossa Juudalaisten synagoga oli."],[17,2,"Ja Paavali, tapansa jälkeen, meni sisälle heidän tykönsä ja jutteli heille kolme lepopäivää Raamatuista,","Ja Paavali, tapansa jälkeen, meni sisälle heidän tykönsä ja jutteli heille kolme lepopäivää Raamatuista,"],[17,3,"Selitti ne ja todisti, että Kristuksen tuli kärsiä ja nousta ylös kuolleista, ja että tämä Jesus, josta minä (sanoi hän,) teille ilmoitan, on Kristus.","Selitti ne ja todisti, että Kristuksen tuli kärsiä ja nousta ylös kuolleista, ja että tämä Jesus, josta minä (sanoi hän,) teille ilmoitan, on Kristus."],[17,4,"Ja muutamat suostuivat heihin, antain itsensä Paavalin ja Silaan seuraan, niin myös suuri joukko jumalisia Grekiläisiä ja ei vähä ylimmäisiä vaimoja.","Ja muutamat suostuivat heihin, antain itsensä Paavalin ja Silaan seuraan, niin myös suuri joukko jumalisia Grekiläisiä ja ei vähä ylimmäisiä vaimoja."],[17,5,"Mutta epäuskoiset Juudalaiset kadehtivat sitä ja saattivat tykönsä muutamia pahanilkisiä miehiä joutoväestä, ja kokoontuivat yhteen joukkoon, nostivat kapinan kaupungissa ja tunkeutuivat Jasonin huoneeseen, ja etsivät heitä viedäksensä kansan eteen.","Mutta epäuskoiset Juudalaiset kadehtivat sitä ja saattivat tykönsä muutamia pahanilkisiä miehiä joutoväestä, ja kokoontuivat yhteen joukkoon, nostivat kapinan kaupungissa ja tunkeutuivat Jasonin huoneeseen, ja etsivät heitä viedäksensä kansan eteen."],[17,6,"Ja ettei he heitä löytäneet, riepoittivat he Jasonin ja muutamia veljiä kaupungin päämiesten eteen ja huusivat: nämät koko maan piirin vietteliät ovat myös täällä,","Ja ettei he heitä löytäneet, riepoittivat he Jasonin ja muutamia veljiä kaupungin päämiesten eteen ja huusivat: nämät koko maan piirin vietteliät ovat myös täällä,"],[17,7,"Jotka Jason otti vastaan; ja nämät kaikki tekevät keisarin käskyä vastaan, sanoen toisen kuninkaan olevan, nimittäin Jesuksen.","Jotka Jason otti vastaan; ja nämät kaikki tekevät keisarin käskyä vastaan, sanoen toisen kuninkaan olevan, nimittäin Jesuksen."],[17,8,"Ja he kehoittivat kansan ja kaupungin päämiehet, jotka näitä kuultelivat.","Ja he kehoittivat kansan ja kaupungin päämiehet, jotka näitä kuultelivat."],[17,9,"Ja kuin he Jasonilta ja niiltä muilta olivat puhdistuksen ottaneet, päästivät he heidät.","Ja kuin he Jasonilta ja niiltä muilta olivat puhdistuksen ottaneet, päästivät he heidät."],[17,10,"Mutta veljet lähettivät kohta yöllä Paavalin ja Silaan Bereaan. Kuin he sinne tulivat, menivät he Juudalaisten synagogaan.","Mutta veljet lähettivät kohta yöllä Paavalin ja Silaan Bereaan. Kuin he sinne tulivat, menivät he Juudalaisten synagogaan."],[17,11,"Sillä he olivat jalompaa sukua kuin ne, jotka Tessalonikassa olivat, ja ottivat juuri mielellänsä sanan vastaan ja tutkivat joka päivä Raamatuita, jos ne niin olisivat.","Sillä he olivat jalompaa sukua kuin ne, jotka Tessalonikassa olivat, ja ottivat juuri mielellänsä sanan vastaan ja tutkivat joka päivä Raamatuita, jos ne niin olisivat."],[17,12,"Niin monta heistä uskoivat, niin myös kunniallisista Grekiläisvaimoista ja miehistä ei harvat.","Niin monta heistä uskoivat, niin myös kunniallisista Grekiläisvaimoista ja miehistä ei harvat."],[17,13,"Kuin Juudalaiset Tessalonikassa ymmärsivät, että Jumalan sana oli myös Bereassa Paavalilta ilmoitettu, tulivat he sinnekin ja kehoittivat kansan.","Kuin Juudalaiset Tessalonikassa ymmärsivät, että Jumalan sana oli myös Bereassa Paavalilta ilmoitettu, tulivat he sinnekin ja kehoittivat kansan."],[17,14,"Mutta veljet lähettivät kohta Paavalin ulos menemään hamaan mereen asti; vaan Silas ja Timoteus jäivät sinne.","Mutta veljet lähettivät kohta Paavalin ulos menemään hamaan mereen asti; vaan Silas ja Timoteus jäivät sinne."],[17,15,"Ja ne, jotka Paavalia saattivat, johdattivat hänen hamaan Ateniin. Ja kuin he saivat käskyn Silaan ja Timoteuksen tykö, että he rientäisivät hänen tykönsä, läksivät he matkaan.","Ja ne, jotka Paavalia saattivat, johdattivat hänen hamaan Ateniin. Ja kuin he saivat käskyn Silaan ja Timoteuksen tykö, että he rientäisivät hänen tykönsä, läksivät he matkaan."],[17,16,"Ja kuin Paavali odotti heitä Atenissa, syttyi hänen henkensä, että hän näki kaupungin aivan epäjumaliseksi.","Ja kuin Paavali odotti heitä Atenissa, syttyi hänen henkensä, että hän näki kaupungin aivan epäjumaliseksi."],[17,17,"Niin hän puheli Juudalaisten ja muiden jumalisten kanssa synagogassa, niin myös turulla joka päivä niiden kanssa, jotka tulivat hänen tykönsä.","Niin hän puheli Juudalaisten ja muiden jumalisten kanssa synagogassa, niin myös turulla joka päivä niiden kanssa, jotka tulivat hänen tykönsä."],[17,18,"Ja muutamat Epikurilaiset ja Stoalaiset philosophit riitelivät hänen kanssansa, ja muutamat sanoivat: mitä tämä lipilaari tahtoo sanoa? Mutta muut sanoivat: hän näkyy tahtovan outoja jumalia ilmoittaa: että hän saarnasi heille evankeliumia Jesuksesta ja ylösnousemisen kuolleista.","Ja muutamat Epikurilaiset ja Stoalaiset philosophit riitelivät hänen kanssansa, ja muutamat sanoivat: mitä tämä lipilaari tahtoo sanoa? Mutta muut sanoivat: hän näkyy tahtovan outoja jumalia ilmoittaa: että hän saarnasi heille evankeliumia Jesuksesta ja ylösnousemisen kuolleista."],[17,19,"Ja he ottivat hänen ja veivät oikeuden paikkaan ja sanoivat: emmekö me mahda tietää, mikä uusi opetus tämä on, josta sinä puhut?","Ja he ottivat hänen ja veivät oikeuden paikkaan ja sanoivat: emmekö me mahda tietää, mikä uusi opetus tämä on, josta sinä puhut?"],[17,20,"Sillä sinä tuotat jotakin outoa meidän korvillemme. Sentähden tahdomme me tietää, mitä ne ovat.","Sillä sinä tuotat jotakin outoa meidän korvillemme. Sentähden tahdomme me tietää, mitä ne ovat."],[17,21,"(Mutta kaikki Atenalaiset ja muukalaiset vieraat ei olleet mihinkään muuhun soveliaat kuin jotakin uutta sanomaan ja kuultelemaan.)","(Mutta kaikki Atenalaiset ja muukalaiset vieraat ei olleet mihinkään muuhun soveliaat kuin jotakin uutta sanomaan ja kuultelemaan.)"],[17,22,"Niin Paavali seisoi keskellä oikeuspaikkaa, ja sanoi: Atenan miehet! minä näen teidät kaikissa kappaleissa epäjumalisiksi;","Niin Paavali seisoi keskellä oikeuspaikkaa, ja sanoi: Atenan miehet! minä näen teidät kaikissa kappaleissa epäjumalisiksi;"],[17,23,"Sillä minä kävelin tässä ympäri ja katselin teidän jumalanpalvelustanne, ja löysin alttarin, jossa oli kirjoitettu: tuntemattomalle Jumalalle. Jota te siis tietämättä palvelette, sen minä teille ilmoitan.","Sillä minä kävelin tässä ympäri ja katselin teidän jumalanpalvelustanne, ja löysin alttarin, jossa oli kirjoitettu: tuntemattomalle Jumalalle. Jota te siis tietämättä palvelette, sen minä teille ilmoitan."],[17,24,"Jumala, joka maailman teki ja kaikki mitä siinä on, joka on taivaan ja maan Herra, ei hän asu käsillä rakennetuissa templeissä,","Jumala, joka maailman teki ja kaikki mitä siinä on, joka on taivaan ja maan Herra, ei hän asu käsillä rakennetuissa templeissä,"],[17,25,"Eikä häntä ihmisten käsillä palvella, niinkuin hän jotakin tarvitsis; sillä hän itse antaa jokaiselle elämän ja hengen sekä kaikki.","Eikä häntä ihmisten käsillä palvella, niinkuin hän jotakin tarvitsis; sillä hän itse antaa jokaiselle elämän ja hengen sekä kaikki."],[17,26,"Ja hän on tehnyt kaiken ihmisten sukukunnan yhdestä verestä kaiken maan piirin päälle asumaan, ja määräsi aivotut ajat ja heidän asumisensa rajat:","Ja hän on tehnyt kaiken ihmisten sukukunnan yhdestä verestä kaiken maan piirin päälle asumaan, ja määräsi aivotut ajat ja heidän asumisensa rajat:"],[17,27,"Että heidän piti Jumalaa etsimän, jos he hänen taitaisivat tuta ja löytää; vaikka ei hän tosin ole kaukana yhdestäkään meistä.","Että heidän piti Jumalaa etsimän, jos he hänen taitaisivat tuta ja löytää; vaikka ei hän tosin ole kaukana yhdestäkään meistä."],[17,28,"Sillä hänessä me elämme, ja liikumme, ja olemme: niinkuin muutamat teidän runosepistänne sanoneet ovat: sillä me olemme myös hänen sukunsa.","Sillä hänessä me elämme, ja liikumme, ja olemme: niinkuin muutamat teidän runosepistänne sanoneet ovat: sillä me olemme myös hänen sukunsa."],[17,29,"Koska me siis Jumalan sukua olemme, niin ei meidän pidä luuleman, että Jumala on kullan eli hopian eli kiven kaltaisen kuvan kaltainen, joka ihmisen taidon ja ajatuksen jälkeen on kaivettu.","Koska me siis Jumalan sukua olemme, niin ei meidän pidä luuleman, että Jumala on kullan eli hopian eli kiven kaltaisen kuvan kaltainen, joka ihmisen taidon ja ajatuksen jälkeen on kaivettu."],[17,30,"Nämät eksytyksen ajat on tosin Jumala sallinut, ja ilmoittaa nyt kaikille ihmisille joka paikassa, että he parannuksen tekisivät.","Nämät eksytyksen ajat on tosin Jumala sallinut, ja ilmoittaa nyt kaikille ihmisille joka paikassa, että he parannuksen tekisivät."],[17,31,"Sillä hän on päivän säätänyt, jona hän on maan piirin tuomitseva vanhurskaudessa, sen miehen kautta, jonka hän on säätänyt, ja jokaiselle ilmoittaa uskon, siinä että hän hänen kuolleista herätti.","Sillä hän on päivän säätänyt, jona hän on maan piirin tuomitseva vanhurskaudessa, sen miehen kautta, jonka hän on säätänyt, ja jokaiselle ilmoittaa uskon, siinä että hän hänen kuolleista herätti."],[17,32,"Kuin he kuulivat kuolleiden ylösnousemisen, niin muutamat nauroivat sitä, vaan toiset sanoivat: me tahdomme sinua siitä vielä kuunnella.","Kuin he kuulivat kuolleiden ylösnousemisen, niin muutamat nauroivat sitä, vaan toiset sanoivat: me tahdomme sinua siitä vielä kuunnella."],[17,33,"Ja niin Paavali läksi heidän keskeltänsä.","Ja niin Paavali läksi heidän keskeltänsä."],[17,34,"Ja muutamat miehet riippuivat hänessä ja uskoivat: joidenka seassa myös Dionysius oli, yksi raadista, ja vaimo, nimeltä Damaris, ja muita heidän kanssansa.","Ja muutamat miehet riippuivat hänessä ja uskoivat: joidenka seassa myös Dionysius oli, yksi raadista, ja vaimo, nimeltä Damaris, ja muita heidän kanssansa."],[18,1,"Senjälkeen läksi Paavali Atenasta ja tuli Korintoon,","Senjälkeen läksi Paavali Atenasta ja tuli Korintoon,"],[18,2,"Ja löysi siellä Juudalaisen, Akvila nimeltä, Pontosta sukuisin, joka äsken Italiasta tullut oli, ja Priskillan hänen emäntänsä, (että Klaudius oli käskenyt kaikki Juudalaiset Roomista mennä pois,) joiden tykö hän meni.","Ja löysi siellä Juudalaisen, Akvila nimeltä, Pontosta sukuisin, joka äsken Italiasta tullut oli, ja Priskillan hänen emäntänsä, (että Klaudius oli käskenyt kaikki Juudalaiset Roomista mennä pois,) joiden tykö hän meni."],[18,3,"Ja että hän oli yhdessä ammatissa, viipyi hän heidän tykönänsä, ja teki työtä; sillä heidän ammattinsa oli telttoja tehdä.","Ja että hän oli yhdessä ammatissa, viipyi hän heidän tykönänsä, ja teki työtä; sillä heidän ammattinsa oli telttoja tehdä."],[18,4,"Mutta hän opetti synagogassa joka lepopäivä ja sai uskomaan sekä Juudalaisia että Grekiläisiä.","Mutta hän opetti synagogassa joka lepopäivä ja sai uskomaan sekä Juudalaisia että Grekiläisiä."],[18,5,"Mutta kuin Silas ja Timoteus Makedoniasta tulivat, oli Paavali hengeltä vaadittu, ja todisti Juudalaisille, että Jesus on Kristus.","Mutta kuin Silas ja Timoteus Makedoniasta tulivat, oli Paavali hengeltä vaadittu, ja todisti Juudalaisille, että Jesus on Kristus."],[18,6,"Kuin he puhuivat vastaan ja pilkkasivat, pudisti hän vaattensa ja sanoi heille: teidän verenne olkoon teidän päänne päälle: tästedes minä menen viatoinna pakanain tykö.","Kuin he puhuivat vastaan ja pilkkasivat, pudisti hän vaattensa ja sanoi heille: teidän verenne olkoon teidän päänne päälle: tästedes minä menen viatoinna pakanain tykö."],[18,7,"Ja hän siirsi itsensä sieltä ja meni yhden huoneesen, jonka nimi oli Justus: se oli Jumalaa palvelevainen, jonka huone oli läsnä synagogaa.","Ja hän siirsi itsensä sieltä ja meni yhden huoneesen, jonka nimi oli Justus: se oli Jumalaa palvelevainen, jonka huone oli läsnä synagogaa."],[18,8,"Mutta Krispus, synagogan ylimmäinen, uskoi Herran päälle kaiken huoneensa kanssa. Ja monta Korintolaisista, jotka kuulivat, uskoivat ja kastettiin.","Mutta Krispus, synagogan ylimmäinen, uskoi Herran päälle kaiken huoneensa kanssa. Ja monta Korintolaisista, jotka kuulivat, uskoivat ja kastettiin."],[18,9,"Mutta Herra sanoi yöllä Paavalille näyn kautta: älä pelkää, vaan puhu, äläkä vaikene;","Mutta Herra sanoi yöllä Paavalille näyn kautta: älä pelkää, vaan puhu, äläkä vaikene;"],[18,10,"Sillä minä olen sinun kanssas, eikä yhdenkään pidä karkaaman sinun päälles vahingoittamaan sinua; sillä minulla on paljo kansaa tässä kaupungissa.","Sillä minä olen sinun kanssas, eikä yhdenkään pidä karkaaman sinun päälles vahingoittamaan sinua; sillä minulla on paljo kansaa tässä kaupungissa."],[18,11,"Niin hän istui siellä ajastajan ja kuusi kuukautta, ja opetti heille Jumalan sanaa.","Niin hän istui siellä ajastajan ja kuusi kuukautta, ja opetti heille Jumalan sanaa."],[18,12,"Mutta kuin Gallio oli maanvanhin Akajassa, karkasivat Juudalaiset yksimielisesti Paavalin päälle ja veivät hänen tuomioistuimen eteen,","Mutta kuin Gallio oli maanvanhin Akajassa, karkasivat Juudalaiset yksimielisesti Paavalin päälle ja veivät hänen tuomioistuimen eteen,"],[18,13,"Sanoen: tämä neuvoo kansaa palvelemaan Jumalaa vastoin lakia.","Sanoen: tämä neuvoo kansaa palvelemaan Jumalaa vastoin lakia."],[18,14,"Kuin Paavali rupesi suutansa avaamaan, sanoi Gallio Juudalaisille: jos olis jotakin vääryyttä eli jotakin hirmuista työtä tehty, oi Juudalaiset, niin olis kohtuullinen, että minä teitä kuulisin;","Kuin Paavali rupesi suutansa avaamaan, sanoi Gallio Juudalaisille: jos olis jotakin vääryyttä eli jotakin hirmuista työtä tehty, oi Juudalaiset, niin olis kohtuullinen, että minä teitä kuulisin;"],[18,15,"Mutta jos kysymys on opista ja sanoista ja teidän laistanne, niin katsokaat itse: en minä tahdo niiden tuomari olla.","Mutta jos kysymys on opista ja sanoista ja teidän laistanne, niin katsokaat itse: en minä tahdo niiden tuomari olla."],[18,16,"Ja ajoi pois heidät tuomioistuimen edestä.","Ja ajoi pois heidät tuomioistuimen edestä."],[18,17,"Niin kaikki Grekiläiset ottivat kiinni Sosteneen, synagogan päämiehen, ja pieksivät hänen tuomioistuimen edessä; ja ei Gallio niitä mitään totellut.","Niin kaikki Grekiläiset ottivat kiinni Sosteneen, synagogan päämiehen, ja pieksivät hänen tuomioistuimen edessä; ja ei Gallio niitä mitään totellut."],[18,18,"Mutta Paavali oli vielä siellä pitkän ajan, ja jätti veljet hyvästi, ja purjehti Syriaan, ja hänen kanssansa Priskilla ja Akvila, ja hän ajeli päänsä Kenkreissä; sillä hänellä oli lupaus.","Mutta Paavali oli vielä siellä pitkän ajan, ja jätti veljet hyvästi, ja purjehti Syriaan, ja hänen kanssansa Priskilla ja Akvila, ja hän ajeli päänsä Kenkreissä; sillä hänellä oli lupaus."],[18,19,"Ja tuli Ephesoon ja jätti ne sinne; mutta itse hän meni synagogaan ja puhui Juudalaisten kanssa.","Ja tuli Ephesoon ja jätti ne sinne; mutta itse hän meni synagogaan ja puhui Juudalaisten kanssa."],[18,20,"Ja he rukoilivat häntä, että hän enemmän aikaa viipyis heidän tykönänsä; vaan ei hän tahtonut;","Ja he rukoilivat häntä, että hän enemmän aikaa viipyis heidän tykönänsä; vaan ei hän tahtonut;"],[18,21,"Mutta jätti heidät hyvästi, sanoen: minun tulee kaiketi mennä Jerusalemiin tälle juhlalle, joka nyt lähestyy. Mutta sitte minä palajan, jos Jumala suo, teidän tykönne. Ja niin hän läksi matkaan Ephesosta,","Mutta jätti heidät hyvästi, sanoen: minun tulee kaiketi mennä Jerusalemiin tälle juhlalle, joka nyt lähestyy. Mutta sitte minä palajan, jos Jumala suo, teidän tykönne. Ja niin hän läksi matkaan Ephesosta,"],[18,22,"Ja tuli Kesareaan, meni ylös ja tervehti seurakuntaa, ja meni alas Antioikiaan,","Ja tuli Kesareaan, meni ylös ja tervehti seurakuntaa, ja meni alas Antioikiaan,"],[18,23,"Ja vietti siellä hetken aikaa, ja meni sitten matkaansa, ja vaelsi järjestänsä Galatian ja Phrygian maakunnan lävitse, vahvistain kaikkia opetuslapsia.","Ja vietti siellä hetken aikaa, ja meni sitten matkaansa, ja vaelsi järjestänsä Galatian ja Phrygian maakunnan lävitse, vahvistain kaikkia opetuslapsia."],[18,24,"Niin tuli Ephesoon Juudalainen, Apollos nimeltä, Aleksandriasta sukuisin, puhelias mies ja taitava Raamatuissa.","Niin tuli Ephesoon Juudalainen, Apollos nimeltä, Aleksandriasta sukuisin, puhelias mies ja taitava Raamatuissa."],[18,25,"Tämä oli opetettu Herran tielle ja oli palava hengessä, puhui ja opetti visusti Herrasta, ja tiesi ainoasti Johanneksen kasteen.","Tämä oli opetettu Herran tielle ja oli palava hengessä, puhui ja opetti visusti Herrasta, ja tiesi ainoasti Johanneksen kasteen."],[18,26,"Tämä rupesi rohkiasti synagogassa opettamaan. Kuin Akvila ja Priskilla hänen kuulivat, ottivat he hänen tykönsä ja selittivät tarkemmasti hänelle Jumalan tien.","Tämä rupesi rohkiasti synagogassa opettamaan. Kuin Akvila ja Priskilla hänen kuulivat, ottivat he hänen tykönsä ja selittivät tarkemmasti hänelle Jumalan tien."],[18,27,"Mutta kuin hän tahtoi mennä Akajaan, kirjoittivat veljet ja neuvoivat opetuslapsia häntä korjaamaan. Ja kuin hän sinne tuli, autti hän paljon niitä, jotka uskoivat armon kautta.","Mutta kuin hän tahtoi mennä Akajaan, kirjoittivat veljet ja neuvoivat opetuslapsia häntä korjaamaan. Ja kuin hän sinne tuli, autti hän paljon niitä, jotka uskoivat armon kautta."],[18,28,"Sillä hän voitti miehuullisesti Juudalaiset ja osoitti julkisesti Raamatuista, että Jesus on Kristus.","Sillä hän voitti miehuullisesti Juudalaiset ja osoitti julkisesti Raamatuista, että Jesus on Kristus."],[19,1,"Niin tapahtui, kuin Apollos oli Korintossa, että Paavali matkusti lävitse ylimaakuntain, ja tuli Ephesoon, ja löysi muutamia opetuslapsia,","Niin tapahtui, kuin Apollos oli Korintossa, että Paavali matkusti lävitse ylimaakuntain, ja tuli Ephesoon, ja löysi muutamia opetuslapsia,"],[19,2,"Ja sanoi heille: oletteko te saaneet Pyhän Hengen, sittenkuin te uskoitte? He sanoivat hänelle: emme ensinkään ole kuulleet, josko Pyhää Henkeä lieneekään.","Ja sanoi heille: oletteko te saaneet Pyhän Hengen, sittenkuin te uskoitte? He sanoivat hänelle: emme ensinkään ole kuulleet, josko Pyhää Henkeä lieneekään."],[19,3,"Ja hän sanoi heille: milläs te olette kastetut? He sanoivat: Johanneksen kasteella.","Ja hän sanoi heille: milläs te olette kastetut? He sanoivat: Johanneksen kasteella."],[19,4,"Niin sanoi Paavali: Johannes tosin kasti parannuksen kasteella, sanoen kansalle, että heidän piti uskoman sen päälle, joka hänen jälkeensä tuleva oli, se on, Kristuksen Jesuksen päälle.","Niin sanoi Paavali: Johannes tosin kasti parannuksen kasteella, sanoen kansalle, että heidän piti uskoman sen päälle, joka hänen jälkeensä tuleva oli, se on, Kristuksen Jesuksen päälle."],[19,5,"Niin ne, jotka sen kuulivat, kastettiin Herran Jesuksen nimeen.","Niin ne, jotka sen kuulivat, kastettiin Herran Jesuksen nimeen."],[19,6,"Ja kuin Paavali pani kätensä heidän päällensä, tuli Pyhä Henki heidän päällensä, ja he puhuivat kielillä ja ennustivat.","Ja kuin Paavali pani kätensä heidän päällensä, tuli Pyhä Henki heidän päällensä, ja he puhuivat kielillä ja ennustivat."],[19,7,"Ja kaikki ne miehet olivat lähes kaksitoistakymmentä.","Ja kaikki ne miehet olivat lähes kaksitoistakymmentä."],[19,8,"Niin hän meni synagogaan ja saarnasi rohkiasti kolme kuukautta, opetti ja neuvoi heitä Jumalan valtakunnasta.","Niin hän meni synagogaan ja saarnasi rohkiasti kolme kuukautta, opetti ja neuvoi heitä Jumalan valtakunnasta."],[19,9,"Mutta kuin muutamat heistä paatuivat ja ei uskoneet, vaan panettelivat Herran tietä yhteiselle kansalle, meni hän pois heidän tyköänsä, ja eroitti opetuslapset, ja puhui joka päivä yhden miehen koulussa, joka kutsuttiin Tyrannus.","Mutta kuin muutamat heistä paatuivat ja ei uskoneet, vaan panettelivat Herran tietä yhteiselle kansalle, meni hän pois heidän tyköänsä, ja eroitti opetuslapset, ja puhui joka päivä yhden miehen koulussa, joka kutsuttiin Tyrannus."],[19,10,"Ja sitä tehtiin kaksi ajastaikaa, niin että kaikki ne, jota Asiassa asuivat, saivat kuulla Herran Jesuksen sanan, sekä Juudalaiset että Grekiläiset.","Ja sitä tehtiin kaksi ajastaikaa, niin että kaikki ne, jota Asiassa asuivat, saivat kuulla Herran Jesuksen sanan, sekä Juudalaiset että Grekiläiset."],[19,11,"Ja Jumala teki Paavalin kätten kautta ei vähiä voimallisia töitä,","Ja Jumala teki Paavalin kätten kautta ei vähiä voimallisia töitä,"],[19,12,"Niin että hikiliinat ja esiliinat hänen iholtansa sairasten päälle tuotiin, ja taudit luopuivat heistä, ja pahat henget heistä läksivät ulos.","Niin että hikiliinat ja esiliinat hänen iholtansa sairasten päälle tuotiin, ja taudit luopuivat heistä, ja pahat henget heistä läksivät ulos."],[19,13,"Niin muutamat Juudalaiset, jotka olivat lumoojat, vaelsivat ympäri, ja kiusasivat mainita Herran Jesuksen nimeä niiden päälle, joilla pahat henget olivat, ja sanoivat: me vannotamme teitä Jesuksen puolesta, jota Paavali saarnaa.","Niin muutamat Juudalaiset, jotka olivat lumoojat, vaelsivat ympäri, ja kiusasivat mainita Herran Jesuksen nimeä niiden päälle, joilla pahat henget olivat, ja sanoivat: me vannotamme teitä Jesuksen puolesta, jota Paavali saarnaa."],[19,14,"Ja muutamat niiden seassa, jotka tätä tekivät, olivat Skevan, Juudalaisten ylimmäisen papin, seitsemän poikaa.","Ja muutamat niiden seassa, jotka tätä tekivät, olivat Skevan, Juudalaisten ylimmäisen papin, seitsemän poikaa."],[19,15,"Mutta paha henki vastasi ja sanoi: Jesuksen minä tunnen, ja Paavalin minä tiedän, mutta mitkä te olette?","Mutta paha henki vastasi ja sanoi: Jesuksen minä tunnen, ja Paavalin minä tiedän, mutta mitkä te olette?"],[19,16,"Ja ihminen, jossa paha henki oli, karkasi heidän päällensä, ja voitti heidät ja paiskasi heidät allensa, niin, että he alasti ja haavoitettuna pääsivät siitä huoneesta ulos pakenemaan.","Ja ihminen, jossa paha henki oli, karkasi heidän päällensä, ja voitti heidät ja paiskasi heidät allensa, niin, että he alasti ja haavoitettuna pääsivät siitä huoneesta ulos pakenemaan."],[19,17,"Ja tämä tuli tiettäväksi sekä kaikille Juudalaisille että Grekiläisille, jotka Ephesossa asuivat, ja pelko tuli kaikkein päälle ja Herran Jesuksen nimi suuresti ylistettiin.","Ja tämä tuli tiettäväksi sekä kaikille Juudalaisille että Grekiläisille, jotka Ephesossa asuivat, ja pelko tuli kaikkein päälle ja Herran Jesuksen nimi suuresti ylistettiin."],[19,18,"Ja tuli myös monta niistä, jotka uskoivat, tunnustivat ja ilmoittivat tekonsa.","Ja tuli myös monta niistä, jotka uskoivat, tunnustivat ja ilmoittivat tekonsa."],[19,19,"Ja monta niistä, jotka hempeitä juonia harjoitelleet olivat, toivat kirjat ja polttivat kaikkein nähden. Ja kuin niiden hinnat laskettu oli, niin löydettiin viisikymmentä tuhatta hopiapenninkiä.","Ja monta niistä, jotka hempeitä juonia harjoitelleet olivat, toivat kirjat ja polttivat kaikkein nähden. Ja kuin niiden hinnat laskettu oli, niin löydettiin viisikymmentä tuhatta hopiapenninkiä."],[19,20,"Niin voimallisesti kasvoi Herran sana ja vahvistui.","Niin voimallisesti kasvoi Herran sana ja vahvistui."],[19,21,"Kuin nämät toimitetut olivat, aikoi Paavali hengessä Makedonian ja Akajan lävitse vaeltaa Jerusalemiin, sanoen: sittekuin minä siellä ollut olen, täytyy minun myös Roomiin mennä.","Kuin nämät toimitetut olivat, aikoi Paavali hengessä Makedonian ja Akajan lävitse vaeltaa Jerusalemiin, sanoen: sittekuin minä siellä ollut olen, täytyy minun myös Roomiin mennä."],[19,22,"Niin hän lähetti Makedoniaan kaksi niistä, jotka häntä palvelivat, Timoteuksen ja Erastuksen, mutta itse hän jäi hetkeksi aikaa Asiaan.","Niin hän lähetti Makedoniaan kaksi niistä, jotka häntä palvelivat, Timoteuksen ja Erastuksen, mutta itse hän jäi hetkeksi aikaa Asiaan."],[19,23,"Mutta sillä ajalla nousi ei vähin kapina siitä tiestä.","Mutta sillä ajalla nousi ei vähin kapina siitä tiestä."],[19,24,"Sillä hopiaseppä, Demetrius nimeltä, teki hopiaisia Diana-templiä, josta niille, jotka sitä ammattia pitivät, oli ei vähin voitto.","Sillä hopiaseppä, Demetrius nimeltä, teki hopiaisia Diana-templiä, josta niille, jotka sitä ammattia pitivät, oli ei vähin voitto."],[19,25,"Ne hän kutsui kokoon, ja jotka senkaltaista työtä tekivät, ja sanoi: miehet, te tiedätte, että meillä on tästä työstä jalo voitto,","Ne hän kutsui kokoon, ja jotka senkaltaista työtä tekivät, ja sanoi: miehet, te tiedätte, että meillä on tästä työstä jalo voitto,"],[19,26,"Ja te näette ja kuulette, ettei ainoasti Ephesossa, mutta lähes kaikessa Asiassa on tämä Paavali uskottanut ja kääntänyt pois paljon kansaa, sanoen, ettei ne ole jumalat, joita ihmisten käsillä tehdään,","Ja te näette ja kuulette, ettei ainoasti Ephesossa, mutta lähes kaikessa Asiassa on tämä Paavali uskottanut ja kääntänyt pois paljon kansaa, sanoen, ettei ne ole jumalat, joita ihmisten käsillä tehdään,"],[19,27,"Niin ei ainoasti vaara ole, että tämä meidän elatuksemme häpiään joutuisi, vaan myös että suuren naisjumalan Dianan tepliä ei minäkään pidettäisi ja hänen korkia kunniansa hukkuisi, jota koko Asia ja kaikki maailma palvelee.","Niin ei ainoasti vaara ole, että tämä meidän elatuksemme häpiään joutuisi, vaan myös että suuren naisjumalan Dianan tepliä ei minäkään pidettäisi ja hänen korkia kunniansa hukkuisi, jota koko Asia ja kaikki maailma palvelee."],[19,28,"Mutta kuin he nämät kuulivat, tulivat he täyteen vihaa ja huusivat, sanoen: suuri on Ephesiläisten Diana!","Mutta kuin he nämät kuulivat, tulivat he täyteen vihaa ja huusivat, sanoen: suuri on Ephesiläisten Diana!"],[19,29,"Ja kaikki kaupunki tuli meteliä täyteen, ja he karkasivat yksimielisesti katseluspaikkaan, ja ottivat kiinni Gajuksen ja Aristarkuksen, jotka olivat Makedoniasta Paavalin matkakumppanit.","Ja kaikki kaupunki tuli meteliä täyteen, ja he karkasivat yksimielisesti katseluspaikkaan, ja ottivat kiinni Gajuksen ja Aristarkuksen, jotka olivat Makedoniasta Paavalin matkakumppanit."],[19,30,"Mutta kuin Paavali tahtoi kansan sekaan mennä, niin ei opetuslapset häntä laskeneet.","Mutta kuin Paavali tahtoi kansan sekaan mennä, niin ei opetuslapset häntä laskeneet."],[19,31,"Ja muutamat päämiehet Asiasta, jotka hänen ystävänsä olivat, lähettivät hänen tykönsä ja rukoilivat, ettei hänen pitänyt katseluspaikkaan itsiänsä antaman.","Ja muutamat päämiehet Asiasta, jotka hänen ystävänsä olivat, lähettivät hänen tykönsä ja rukoilivat, ettei hänen pitänyt katseluspaikkaan itsiänsä antaman."],[19,32,"Ja muutamat muuta huusivat, niin että joukko oli peräti sekaseuraisin, ja enin osa ei tietänyt, minkätähden he olivat tulleet kokoon.","Ja muutamat muuta huusivat, niin että joukko oli peräti sekaseuraisin, ja enin osa ei tietänyt, minkätähden he olivat tulleet kokoon."],[19,33,"Niin väkijoukosta vedettiin edes Aleksanteri, jonka Juudalaiset eteen syöksivät. Ja Aleksanteri viittasi kädellänsä, ja tahtoi edestänsä vastata kansan edessä.","Niin väkijoukosta vedettiin edes Aleksanteri, jonka Juudalaiset eteen syöksivät. Ja Aleksanteri viittasi kädellänsä, ja tahtoi edestänsä vastata kansan edessä."],[19,34,"Kuin he siis ymmärsivät, että hän Juudalainen oli, huusivat he kaikki yhteen suuhun, lähes kaksi hetkeä, ja sanoivat: suuri on Ephesiläisten Diana!","Kuin he siis ymmärsivät, että hän Juudalainen oli, huusivat he kaikki yhteen suuhun, lähes kaksi hetkeä, ja sanoivat: suuri on Ephesiläisten Diana!"],[19,35,"Mutta kuin kansleri oli hillinnyt kansan, sanoi hän: Epheson miehet! kuka on se ihminen, joka ei tiedä, että Epheson kaupunki palvelee suurta Dianaa ja taivaista pudonnutta kuvaa?","Mutta kuin kansleri oli hillinnyt kansan, sanoi hän: Epheson miehet! kuka on se ihminen, joka ei tiedä, että Epheson kaupunki palvelee suurta Dianaa ja taivaista pudonnutta kuvaa?"],[19,36,"Koska ei siis taideta sanoa sitä vastaan, niin asettakaat teitänne ja älkäät mitään tyhmiä tehkö.","Koska ei siis taideta sanoa sitä vastaan, niin asettakaat teitänne ja älkäät mitään tyhmiä tehkö."],[19,37,"Sillä te olette nämät miehet vetäneet edes, jotka ei ole kirkon varkaita eikä teidän jumalanne pilkkaajia.","Sillä te olette nämät miehet vetäneet edes, jotka ei ole kirkon varkaita eikä teidän jumalanne pilkkaajia."],[19,38,"Jos siis Demetriuksella ja niillä, jotka hänen kanssansa työkumppanit ovat, on jonkun kanssa asiaa, niin pidetään laki ja oikeus; ovat myös maanvanhimmat: kantakaan toinen toisensa päälle.","Jos siis Demetriuksella ja niillä, jotka hänen kanssansa työkumppanit ovat, on jonkun kanssa asiaa, niin pidetään laki ja oikeus; ovat myös maanvanhimmat: kantakaan toinen toisensa päälle."],[19,39,"Mutta jos teillä on riita muista asioista, niin ratkaistakoon asia laillisessa kokouksessa.","Mutta jos teillä on riita muista asioista, niin ratkaistakoon asia laillisessa kokouksessa."],[19,40,"Sillä vaara on, että me nuhteesen tulemme tämänpäiväisen kapinan tähden, koska ei yhtään syytä ole, josta me taitaisimme tämän metelin tähden tilin tehdä.","Sillä vaara on, että me nuhteesen tulemme tämänpäiväisen kapinan tähden, koska ei yhtään syytä ole, josta me taitaisimme tämän metelin tähden tilin tehdä."],[19,41,"Ja kuin hän nämät sanonut oli, laski hän kansan menemään.","Ja kuin hän nämät sanonut oli, laski hän kansan menemään."],[20,1,"Sittekuin kapina lakkasi, kutsui Paavali opetuslapset tykönsä ja tervehti heitä, ja läksi matkaansa Makedoniaan.","Sittekuin kapina lakkasi, kutsui Paavali opetuslapset tykönsä ja tervehti heitä, ja läksi matkaansa Makedoniaan."],[20,2,"Ja kuin hän ne maakunnat vaelsi, ja oli heitä monilla sanoilla neuvonut, tuli hän Grekan maalle,","Ja kuin hän ne maakunnat vaelsi, ja oli heitä monilla sanoilla neuvonut, tuli hän Grekan maalle,"],[20,3,"Ja viipyi siellä kolme kuukautta, ja että Juudalaiset väijyivät häntä, kuin hänen piti Syriaan menemään, aikoi hän palata Makedonian kautta.","Ja viipyi siellä kolme kuukautta, ja että Juudalaiset väijyivät häntä, kuin hänen piti Syriaan menemään, aikoi hän palata Makedonian kautta."],[20,4,"Mutta Sopater Bereasta seurasi häntä Asiaan asti, ja Tessalonikasta Aristarkus ja Sekundus, ja Gajus Derbestä, ja Timoteus; mutta Asiasta Tykikus ja Trophimus.","Mutta Sopater Bereasta seurasi häntä Asiaan asti, ja Tessalonikasta Aristarkus ja Sekundus, ja Gajus Derbestä, ja Timoteus; mutta Asiasta Tykikus ja Trophimus."],[20,5,"Nämät läksivät edellä ja odottivat meitä Troadassa.","Nämät läksivät edellä ja odottivat meitä Troadassa."],[20,6,"Mutta me purjehdimme jälkeen pääsiäisen Philipistä ja tulimme heidän tykönsä Troadaan viitenä päivänä, ja viivyimme siellä seitsemän päivää.","Mutta me purjehdimme jälkeen pääsiäisen Philipistä ja tulimme heidän tykönsä Troadaan viitenä päivänä, ja viivyimme siellä seitsemän päivää."],[20,7,"Mutta ensimmäisenä viikonpäivänä, kuin opetuslapset kokoontuivat leipää taittamaan, saarnasi heille Paavali, ja aikoen toisena päivänä matkustaa, pitensi saarnan puoli-yöhön asti.","Mutta ensimmäisenä viikonpäivänä, kuin opetuslapset kokoontuivat leipää taittamaan, saarnasi heille Paavali, ja aikoen toisena päivänä matkustaa, pitensi saarnan puoli-yöhön asti."],[20,8,"Ja monta kynttilää oli sytytetty salissa, jossa me olimme koossa.","Ja monta kynttilää oli sytytetty salissa, jossa me olimme koossa."],[20,9,"Niin nuorukainen, nimeltä Eutykus, istui akkunalla, ja raukesi syvään uneen, ja Paavalin kauvan puhuessa, tuli hän unelta voitetuksi ja putosi alas kolmannesta ullakosta, ja otettiin kuolleena ylös.","Niin nuorukainen, nimeltä Eutykus, istui akkunalla, ja raukesi syvään uneen, ja Paavalin kauvan puhuessa, tuli hän unelta voitetuksi ja putosi alas kolmannesta ullakosta, ja otettiin kuolleena ylös."],[20,10,"Niin Paavali astui alas, ja laski itsensä hänen päällensä, ja otti syliinsä, ja sanoi: älkäät kapinoitko; sillä hänen sielunsa on vielä hänessä.","Niin Paavali astui alas, ja laski itsensä hänen päällensä, ja otti syliinsä, ja sanoi: älkäät kapinoitko; sillä hänen sielunsa on vielä hänessä."],[20,11,"Niin hän nousi, ja taitti leipää, ja söi, ja puheli kauvan heidän kanssansa, päivän koittamaan asti, niin hän läksi matkaansa.","Niin hän nousi, ja taitti leipää, ja söi, ja puheli kauvan heidän kanssansa, päivän koittamaan asti, niin hän läksi matkaansa."],[20,12,"Niin he toivat nuorukaisen elävänä ja tulivat siitä lohdutetuksi.","Niin he toivat nuorukaisen elävänä ja tulivat siitä lohdutetuksi."],[20,13,"Mutta me astuimme edellä haahteen ja purhjehdimme Assoon, aikoen siellä ottaa Paavalin sisälle; sillä hän oli niin käskenyt, ja tahtoi itse maata myöten mennä.","Mutta me astuimme edellä haahteen ja purhjehdimme Assoon, aikoen siellä ottaa Paavalin sisälle; sillä hän oli niin käskenyt, ja tahtoi itse maata myöten mennä."],[20,14,"Kuin hän Assossa meidän kanssamme yhteen tuli, otimme me hänen sisälle ja tulimme Mityleneen.","Kuin hän Assossa meidän kanssamme yhteen tuli, otimme me hänen sisälle ja tulimme Mityleneen."],[20,15,"Sieltä me purhjehdimme ja tulimme toisena päivänä Kion kohdalle. Ja taas pävää jälkeen tulimme me Samoon, ja viivyimme Trogylliossa. Ja päivää jälkeen tulimme me Miletoon.","Sieltä me purhjehdimme ja tulimme toisena päivänä Kion kohdalle. Ja taas pävää jälkeen tulimme me Samoon, ja viivyimme Trogylliossa. Ja päivää jälkeen tulimme me Miletoon."],[20,16,"Sillä Paavali oli päättänyt purjehtia Epheson ohitse, ettei hän Asiassa aikaa kuluttaisi; sillä hän kiiruhti, jos hänelle olis mahdollinen ollut, helluntaiksi Jerusalemiin.","Sillä Paavali oli päättänyt purjehtia Epheson ohitse, ettei hän Asiassa aikaa kuluttaisi; sillä hän kiiruhti, jos hänelle olis mahdollinen ollut, helluntaiksi Jerusalemiin."],[20,17,"Mutta hän lähetti Miletosta sanan Ephesoon ja kutsutti seurakunnan vanhimmat.","Mutta hän lähetti Miletosta sanan Ephesoon ja kutsutti seurakunnan vanhimmat."],[20,18,"Kuin he tulivat hänen tykönsä, sanoi hän heille: te tiedätte, kuinka minä olen ollut kaiken ajan teidän tykönänne ensimmäisestä päivästä, jona minä Asiaan tulin,","Kuin he tulivat hänen tykönsä, sanoi hän heille: te tiedätte, kuinka minä olen ollut kaiken ajan teidän tykönänne ensimmäisestä päivästä, jona minä Asiaan tulin,"],[20,19,"Palvellen Herraa kaikella sydämen nöyryydellä, ja monilla kyyneleillä, ja kiusauksilla, jotka minulle Juudalaisten väijymisistä tapahtuivat:","Palvellen Herraa kaikella sydämen nöyryydellä, ja monilla kyyneleillä, ja kiusauksilla, jotka minulle Juudalaisten väijymisistä tapahtuivat:"],[20,20,"Etten minä ole mitään tarpeellista teiltä salannut, jota en minä ole teille ilmoittanut, ja olen teille opettanut julkisesti ja huone huoneelta,","Etten minä ole mitään tarpeellista teiltä salannut, jota en minä ole teille ilmoittanut, ja olen teille opettanut julkisesti ja huone huoneelta,"],[20,21,"Todistain sekä Juudalaisille että Grekiläisille sitä kääntymystä, joka Jumalan tykö on, ja sitä uskoa, joka meidän Herran Jesuksen Kristuksen päälle on.","Todistain sekä Juudalaisille että Grekiläisille sitä kääntymystä, joka Jumalan tykö on, ja sitä uskoa, joka meidän Herran Jesuksen Kristuksen päälle on."],[20,22,"Ja nyt katso, minä sidottuna hengessä matkustan Jerusalemiin, enkä tiedä, mitä minulle siellä tapahtuman pitää:","Ja nyt katso, minä sidottuna hengessä matkustan Jerusalemiin, enkä tiedä, mitä minulle siellä tapahtuman pitää:"],[20,23,"Vaan että Pyhä Henki jokaisessa kaupungissa tunnustaa ja sanoo siteet ja murheet minun edessäni olevan.","Vaan että Pyhä Henki jokaisessa kaupungissa tunnustaa ja sanoo siteet ja murheet minun edessäni olevan."],[20,24,"Mutta en minä siitä lukua pidä, enkä tottele paljon hengestäni: että minä juoksuni päättäisin ilolla ja sen viran, jonka minä olen Herralta Jesukselta saanut, todistaakseni evankeliumia Jumalan armosta.","Mutta en minä siitä lukua pidä, enkä tottele paljon hengestäni: että minä juoksuni päättäisin ilolla ja sen viran, jonka minä olen Herralta Jesukselta saanut, todistaakseni evankeliumia Jumalan armosta."],[20,25,"Ja nyt katso, minä tiedän, ettette silleen saa nähdä minun kasvojani, kaikki te, joiden kautta minä olen vaeltanut ja Jumalan valtakuntaa saarnannut.","Ja nyt katso, minä tiedän, ettette silleen saa nähdä minun kasvojani, kaikki te, joiden kautta minä olen vaeltanut ja Jumalan valtakuntaa saarnannut."],[20,26,"Sentähden minä todistan teille tänäpänä, että minä olen viatoin kaikkein verestä.","Sentähden minä todistan teille tänäpänä, että minä olen viatoin kaikkein verestä."],[20,27,"Sillä en minä ole estänyt itsiäni ilmoittamasta teille kaikkea Jumalan neuvoa.","Sillä en minä ole estänyt itsiäni ilmoittamasta teille kaikkea Jumalan neuvoa."],[20,28,"Niin ottakaat siis itsestänne vaari ja kaikesta laumasta, johon Pyhä Henki on teidät piispoiksi pannut, kaitsemaan Jumalan seurakuntaa, jonka hän omalla verellänsä ansainnut on.","Niin ottakaat siis itsestänne vaari ja kaikesta laumasta, johon Pyhä Henki on teidät piispoiksi pannut, kaitsemaan Jumalan seurakuntaa, jonka hän omalla verellänsä ansainnut on."],[20,29,"Sillä minä tiedän minun lähtemiseni jälkeen tulevan teidän sekaanne hirmuiset sudet, jotka ei laumaa säästä.","Sillä minä tiedän minun lähtemiseni jälkeen tulevan teidän sekaanne hirmuiset sudet, jotka ei laumaa säästä."],[20,30,"Ja itse teistänne nousevat miehet, jotka vääryyttä puhuvat, vetääksensä pois opetuslapsia peräänsä.","Ja itse teistänne nousevat miehet, jotka vääryyttä puhuvat, vetääksensä pois opetuslapsia peräänsä."],[20,31,"Sentähden valvokaat, muistain etten minä kolmena ajastaikana ole lakannut yöllä ja päivällä teitä kyyneleillä neuvomasta itsekutakin.","Sentähden valvokaat, muistain etten minä kolmena ajastaikana ole lakannut yöllä ja päivällä teitä kyyneleillä neuvomasta itsekutakin."],[20,32,"Ja nyt, rakkaat veljet, minä annan teidät Jumalan ja hänen armonsa sanan haltuun, joka väkevä on teitä rakentamaan ja antamaan teille perinnön kaikkein pyhitettyin seassa.","Ja nyt, rakkaat veljet, minä annan teidät Jumalan ja hänen armonsa sanan haltuun, joka väkevä on teitä rakentamaan ja antamaan teille perinnön kaikkein pyhitettyin seassa."],[20,33,"En minä ole yhdenkään hopiaa eikä kultaa eikä vaatteita pyytänyt.","En minä ole yhdenkään hopiaa eikä kultaa eikä vaatteita pyytänyt."],[20,34,"Vaan te itse tiedätte, että nämät kädet ovat minua tarpeissani ja niitä, jotka minun kanssani olivat, palvelleet.","Vaan te itse tiedätte, että nämät kädet ovat minua tarpeissani ja niitä, jotka minun kanssani olivat, palvelleet."],[20,35,"Kaikki olen minä teille osoittanut, että niin pitää työtä tehtämän: heikkoja korjattaman ja muistettaman Herran Jesuksen sanoja, jotka hän sanoi: autuaampi on antaa kuin ottaa.","Kaikki olen minä teille osoittanut, että niin pitää työtä tehtämän: heikkoja korjattaman ja muistettaman Herran Jesuksen sanoja, jotka hän sanoi: autuaampi on antaa kuin ottaa."],[20,36,"Ja kuin hän nämät sanonut oli, lankesi hän polvillensa ja rukoili kaikkein heidän kanssansa.","Ja kuin hän nämät sanonut oli, lankesi hän polvillensa ja rukoili kaikkein heidän kanssansa."],[20,37,"Ja suuri itku tuli heille kaikille ja lankesivat Paavalin kaulaan ja suuta antoivat hänen,","Ja suuri itku tuli heille kaikille ja lankesivat Paavalin kaulaan ja suuta antoivat hänen,"],[20,38,"Murehtien suuresti sen sanan tähden, jonka hän oli sanonut, ettei heidän pitänyt enempi hänen kasvojansa näkemän. Ja he saattivat häntä haahteen.","Murehtien suuresti sen sanan tähden, jonka hän oli sanonut, ettei heidän pitänyt enempi hänen kasvojansa näkemän. Ja he saattivat häntä haahteen."],[21,1,"Kuin siis tapahtui, että me laskimme ulos ja heistä luovuimme, menimme me kohdastansa Koon saareen, ja toisena päivänä Rodoon, ja sieltä Pataraan.","Kuin siis tapahtui, että me laskimme ulos ja heistä luovuimme, menimme me kohdastansa Koon saareen, ja toisena päivänä Rodoon, ja sieltä Pataraan."],[21,2,"Ja kuin me sieltä haahden löysimme, joka Phenikiaan hankitsi, siihen me astuimme, ja läksimme matkaan.","Ja kuin me sieltä haahden löysimme, joka Phenikiaan hankitsi, siihen me astuimme, ja läksimme matkaan."],[21,3,"Ja kuin Kypros rupesi näkymään ja me sen vasemmalle puolelle jättäneet olimme, purjehdimme me Syriaan ja tulimme Tyroon; sillä siellä piti se haaksi tyhjennettämän.","Ja kuin Kypros rupesi näkymään ja me sen vasemmalle puolelle jättäneet olimme, purjehdimme me Syriaan ja tulimme Tyroon; sillä siellä piti se haaksi tyhjennettämän."],[21,4,"Ja kuin me löysimme opetuslapsia, niin me olimme siellä seitsemän päivää. Ja ne sanoivat Paavalille hengen kautta, ettei hänen pitänyt Jerusalemiin menemän.","Ja kuin me löysimme opetuslapsia, niin me olimme siellä seitsemän päivää. Ja ne sanoivat Paavalille hengen kautta, ettei hänen pitänyt Jerusalemiin menemän."],[21,5,"Ja tapahtui, kuin me ne päivät olimme viettäneet, niin me läksimme matkaan, ja he saattivat kaikki meitä vaimoin ja lasten kanssa ulos kaupungista, ja me lankesimme rannassa polvillemme ja rukoilimme.","Ja tapahtui, kuin me ne päivät olimme viettäneet, niin me läksimme matkaan, ja he saattivat kaikki meitä vaimoin ja lasten kanssa ulos kaupungista, ja me lankesimme rannassa polvillemme ja rukoilimme."],[21,6,"Ja sittekuin me toinen toistamme tervehdimme, niin me astuimme haahteen; vaan he palasivat kotiansa.","Ja sittekuin me toinen toistamme tervehdimme, niin me astuimme haahteen; vaan he palasivat kotiansa."],[21,7,"Mutta me päätimme meidän purjehdusretkemme, tulimme Tyrosta Ptolemaidaan, tervehdimme veljiä ja olimme päivän heidän tykönänsä.","Mutta me päätimme meidän purjehdusretkemme, tulimme Tyrosta Ptolemaidaan, tervehdimme veljiä ja olimme päivän heidän tykönänsä."],[21,8,"Toisena päivänä läksimme me matkaan, jotka Paavalin kanssa olimme, ja tulimme Kesareaan, ja menimme Philippus evankelistan huoneeseen, (joka oli yksi niistä seitsemästä,) ja jäimme hänen tykönsä.","Toisena päivänä läksimme me matkaan, jotka Paavalin kanssa olimme, ja tulimme Kesareaan, ja menimme Philippus evankelistan huoneeseen, (joka oli yksi niistä seitsemästä,) ja jäimme hänen tykönsä."],[21,9,"Ja hänellä oli neljä tytärtä, neitsyttä, jotka ennustivat.","Ja hänellä oli neljä tytärtä, neitsyttä, jotka ennustivat."],[21,10,"Ja että me olimme siellä monta päivää, tuli alas Juudeasta propheta, Agabus nimeltä.","Ja että me olimme siellä monta päivää, tuli alas Juudeasta propheta, Agabus nimeltä."],[21,11,"Kuin hän tuli meidän tykömme, otti hän Paavalin vyön, sitoi jalkansa ja kätensä, ja sanoi: näin sanoo Pyhä Henki: sen miehen, jonka tämä vyö on, pitää Juudalaiset niin Jerusalemissa sitoman ja antaman ylön pakanain käsiin.","Kuin hän tuli meidän tykömme, otti hän Paavalin vyön, sitoi jalkansa ja kätensä, ja sanoi: näin sanoo Pyhä Henki: sen miehen, jonka tämä vyö on, pitää Juudalaiset niin Jerusalemissa sitoman ja antaman ylön pakanain käsiin."],[21,12,"Mutta kuin me sen kuulimme, rukoilimme sekä me että muut, jotka siinä olivat, ettei hänen pitänyt Jerusalemiin menemän.","Mutta kuin me sen kuulimme, rukoilimme sekä me että muut, jotka siinä olivat, ettei hänen pitänyt Jerusalemiin menemän."],[21,13,"Niin Paavali vastasi: mitä te teette, että te itkette ja raskautatte minun sydäntäni? Sillä minä olen valmis, en ainoasti sidottaa, mutta myös kuolemaan Jerusalemissa, Herran Jesuksen nimen tähden.","Niin Paavali vastasi: mitä te teette, että te itkette ja raskautatte minun sydäntäni? Sillä minä olen valmis, en ainoasti sidottaa, mutta myös kuolemaan Jerusalemissa, Herran Jesuksen nimen tähden."],[21,14,"Ja ettei hän antanut itsiänsä puhuttaa ylitse, niin me siihen tyydyimme, sanoen: tapahtukoon Herran tahto!","Ja ettei hän antanut itsiänsä puhuttaa ylitse, niin me siihen tyydyimme, sanoen: tapahtukoon Herran tahto!"],[21,15,"Ja niiden päiväin jälkeen tulimme me valmiiksi ja menimme ylös Jerusalemiin.","Ja niiden päiväin jälkeen tulimme me valmiiksi ja menimme ylös Jerusalemiin."],[21,16,"Ja tulivat muutamat opetuslapset Kesareasta meidän kanssamme ja toivat vanhan opetuslapsen Kypristä, nimeltä Mnason, joka meitä piti huoneesensa ottaman.","Ja tulivat muutamat opetuslapset Kesareasta meidän kanssamme ja toivat vanhan opetuslapsen Kypristä, nimeltä Mnason, joka meitä piti huoneesensa ottaman."],[21,17,"Vaan kuin me tulimme Jerusalemiin, niin veljet mielellänsä meidät ottivat vastaan.","Vaan kuin me tulimme Jerusalemiin, niin veljet mielellänsä meidät ottivat vastaan."],[21,18,"Toisena päivänä meni Paavali meidän kanssamme Jakobin tykö, ja kaikki vanhimmat olivat läsnä.","Toisena päivänä meni Paavali meidän kanssamme Jakobin tykö, ja kaikki vanhimmat olivat läsnä."],[21,19,"Kuin hän heitä oli tervehtinyt, jutteli hän järjestänsä, mitä Jumala oli hänen virkansa kutta pakanain seassa tehnyt.","Kuin hän heitä oli tervehtinyt, jutteli hän järjestänsä, mitä Jumala oli hänen virkansa kutta pakanain seassa tehnyt."],[21,20,"Mutta kuin he nämät kuulivat, kunnioittivat he Herraa ja sanoivat hänelle: sinä näet, rakas veli, kuinka monta tuhatta Juudalaista ovat uskoneet, ja ne kaikki lain puolesta kiivaat ovat.","Mutta kuin he nämät kuulivat, kunnioittivat he Herraa ja sanoivat hänelle: sinä näet, rakas veli, kuinka monta tuhatta Juudalaista ovat uskoneet, ja ne kaikki lain puolesta kiivaat ovat."],[21,21,"Mutta he ovat sinusta kuulleet, että sinä opetat luopumista Moseksesta kaikille Juudalaisille, jotka pakanain seassa asuvat, sanoen ettei heidän pidä ympärileikkaaman lapsiansa eikä säätyin jälkeen vaeltaman.","Mutta he ovat sinusta kuulleet, että sinä opetat luopumista Moseksesta kaikille Juudalaisille, jotka pakanain seassa asuvat, sanoen ettei heidän pidä ympärileikkaaman lapsiansa eikä säätyin jälkeen vaeltaman."],[21,22,"Mikä siis on? Kaiketi pitää kansan tuleman kokoon; sillä heidän pitää saaman tietää sinun tulleeksi.","Mikä siis on? Kaiketi pitää kansan tuleman kokoon; sillä heidän pitää saaman tietää sinun tulleeksi."],[21,23,"Niin tee siis se, mitä me sinulle sanomme. Meillä on tässä neljä miestä, joilla on lupaus päällänsä.","Niin tee siis se, mitä me sinulle sanomme. Meillä on tässä neljä miestä, joilla on lupaus päällänsä."],[21,24,"Ota ne tykös, ja puhdista itses heidän kanssansa, ja kuluta jotakin heidän tähtensä, että he ajelisivat päänsä, ja siitä he kaikki ymmärtäisivät, ettei se mitään ole, mitä he sinusta kuulleet ovat, mutta että sinäkin vaellat, niinkuin sinä olisit lain pitävä.","Ota ne tykös, ja puhdista itses heidän kanssansa, ja kuluta jotakin heidän tähtensä, että he ajelisivat päänsä, ja siitä he kaikki ymmärtäisivät, ettei se mitään ole, mitä he sinusta kuulleet ovat, mutta että sinäkin vaellat, niinkuin sinä olisit lain pitävä."],[21,25,"Mutta niistä, jotka uskoivat pakanoista, olemme me kirjoittaneet ja päättäneet, ettei heidän tarvitse näistä mitään pitää, vaan että he niitä välttäisivät, jotka epäjumalille ovat uhratut, ja verta, läkähtynyttä ja salavuoteutta.","Mutta niistä, jotka uskoivat pakanoista, olemme me kirjoittaneet ja päättäneet, ettei heidän tarvitse näistä mitään pitää, vaan että he niitä välttäisivät, jotka epäjumalille ovat uhratut, ja verta, läkähtynyttä ja salavuoteutta."],[21,26,"Silloin Paavali otti ne miehet tykönsä ja puhdisti itsensä toisena päivänä heidän kanssansa, ja meni templiin, ja ilmoitti, että puhdistuksen päivät olivat täytetyt, siihenasti kuin jokaisen edestä heidän seassansa uhri oli uhrattu.","Silloin Paavali otti ne miehet tykönsä ja puhdisti itsensä toisena päivänä heidän kanssansa, ja meni templiin, ja ilmoitti, että puhdistuksen päivät olivat täytetyt, siihenasti kuin jokaisen edestä heidän seassansa uhri oli uhrattu."],[21,27,"Mutta kuin jo lähes seitsemän päivää kulunut oli, näkivät hänen Juudalaiset, jotka Asiasta olivat, templissä ja kehoittivat kaiken kansan, paiskasivat kätensä hänen päällensä,","Mutta kuin jo lähes seitsemän päivää kulunut oli, näkivät hänen Juudalaiset, jotka Asiasta olivat, templissä ja kehoittivat kaiken kansan, paiskasivat kätensä hänen päällensä,"],[21,28,"Huutain: Israelin miehet, auttakaat! Tämä on se mies, joka kaikkia kaikissa paikoissa opettaa vastoin tätä kansaa ja lakia ja tätä siaa. Ja vieläkin hän on vienyt Grekiläisiäkin templiin, ja riivasi tämän pyhän sian.","Huutain: Israelin miehet, auttakaat! Tämä on se mies, joka kaikkia kaikissa paikoissa opettaa vastoin tätä kansaa ja lakia ja tätä siaa. Ja vieläkin hän on vienyt Grekiläisiäkin templiin, ja riivasi tämän pyhän sian."],[21,29,"(Sillä he olivat ennen nähneet Trophimon Ephesosta hänen kanssansa kaupungissa, ja he luulivat, että Paavali oli hänen templiin vienyt.)","(Sillä he olivat ennen nähneet Trophimon Ephesosta hänen kanssansa kaupungissa, ja he luulivat, että Paavali oli hänen templiin vienyt.)"],[21,30,"Niin koko kaupunki nosti metelin, ja väki juoksi kokoon; ja he ottivat Paavalin kiinni ja riepoittivat hänen ulos templistä, ja kohta ovet suljettiin.","Niin koko kaupunki nosti metelin, ja väki juoksi kokoon; ja he ottivat Paavalin kiinni ja riepoittivat hänen ulos templistä, ja kohta ovet suljettiin."],[21,31,"Ja kuin he tahtoivat hänen tappaa, niin ylimmäinen sotajoukon päämies sai sanan, että koko Jerusalem oli kehoitettu.","Ja kuin he tahtoivat hänen tappaa, niin ylimmäinen sotajoukon päämies sai sanan, että koko Jerusalem oli kehoitettu."],[21,32,"Se otti kohta sotaväkeä ja sadanpäämiehiä, ja tuli juosten heidän tykönsä. Mutta kuin he näkivät sodanpäämiehen ja sotaväen, lakkasivat he Paavalia hosumasta.","Se otti kohta sotaväkeä ja sadanpäämiehiä, ja tuli juosten heidän tykönsä. Mutta kuin he näkivät sodanpäämiehen ja sotaväen, lakkasivat he Paavalia hosumasta."],[21,33,"Kuin päämies lähestyi, otti hän hänen kiinni ja käski sitoa kaksilla kahleilla, ja kysyi, kuka hän oli, eli mitä hän oli tehnyt?","Kuin päämies lähestyi, otti hän hänen kiinni ja käski sitoa kaksilla kahleilla, ja kysyi, kuka hän oli, eli mitä hän oli tehnyt?"],[21,34,"Mutta kansasta huusi yksi sitä, toinen tätä. Koska ei hän oikein taitanut ymmärtää huminan tähden, käski hän hänen vietää leiriin.","Mutta kansasta huusi yksi sitä, toinen tätä. Koska ei hän oikein taitanut ymmärtää huminan tähden, käski hän hänen vietää leiriin."],[21,35,"Ja kuin hän astumien eteen tuli, kannettiin hän sotamiehiltä kansan väkivallan tähden;","Ja kuin hän astumien eteen tuli, kannettiin hän sotamiehiltä kansan väkivallan tähden;"],[21,36,"Sillä paljo kansaa noudatti häntä, huutain: ota pois häntä!","Sillä paljo kansaa noudatti häntä, huutain: ota pois häntä!"],[21,37,"Ja kuin Paavali oli leiriin tulemallansa, sanoi hän sodanpäämiehelle: onko minulla lupa sinulle jotakin sanoa? Hän sanoi: taidatkos Grekan kielen?","Ja kuin Paavali oli leiriin tulemallansa, sanoi hän sodanpäämiehelle: onko minulla lupa sinulle jotakin sanoa? Hän sanoi: taidatkos Grekan kielen?"],[21,38,"Etkös sinä siis ole Egyptin mies, joka ennen näitä päiviä kapinan nostit ja veit korpeen neljätuhatta murhamiestä?","Etkös sinä siis ole Egyptin mies, joka ennen näitä päiviä kapinan nostit ja veit korpeen neljätuhatta murhamiestä?"],[21,39,"Niin Paavali sanoi: minä olen Juudalainen Tarsin, kuuluisan kaupungin asuvainen Kilikiasta. Minä rukoilen sinua, salli minun puhua kansalle.","Niin Paavali sanoi: minä olen Juudalainen Tarsin, kuuluisan kaupungin asuvainen Kilikiasta. Minä rukoilen sinua, salli minun puhua kansalle."],[21,40,"Ja kuin hän salli, niin Paavali seisoi astuttavilla ja viittasi kädellänsä kansalle. Kuin suuri vaikeneminen tuli, puhutteli hän heitä Hebrean kielellä ja sanoi:","Ja kuin hän salli, niin Paavali seisoi astuttavilla ja viittasi kädellänsä kansalle. Kuin suuri vaikeneminen tuli, puhutteli hän heitä Hebrean kielellä ja sanoi:"],[22,1,"Miehet, rakkat veljet ja isät! kuulkaat minun edesvastaustani, jonka minä teille sanon.","Miehet, rakkat veljet ja isät! kuulkaat minun edesvastaustani, jonka minä teille sanon."],[22,2,"(Kuin he kuulivat hänen Hebrean kielellä heille puhuvan, vaikenivat he enemmin. Ja hän sanoi:)","(Kuin he kuulivat hänen Hebrean kielellä heille puhuvan, vaikenivat he enemmin. Ja hän sanoi:)"],[22,3,"Minä olen Juudalainen, Tarsossa Kilikiassa syntynyt ja tässä kaupungissa kasvatettu Gamalielin jalkain juuressa, opetettu visusti vanhimpain laissa, ja olin Jumalan puolesta kiivas, niinkuin tekin kaikki olette tänäpänä,","Minä olen Juudalainen, Tarsossa Kilikiassa syntynyt ja tässä kaupungissa kasvatettu Gamalielin jalkain juuressa, opetettu visusti vanhimpain laissa, ja olin Jumalan puolesta kiivas, niinkuin tekin kaikki olette tänäpänä,"],[22,4,"Ja olen tätä tietä vainonnut kuolemaan asti, sitoin ja antain ylön vankiuteen sekä miehiä että vaimoja,","Ja olen tätä tietä vainonnut kuolemaan asti, sitoin ja antain ylön vankiuteen sekä miehiä että vaimoja,"],[22,5,"Niinkuin myös ylimmäinen pappi ja koko vanhimpain joukko minun todistajani ovat, joilta minä otin lähetyskirjat veljein tykö, ja vaelsin Damaskuun, että minä ne, jotka siellä olivat, olisin sidottuna tuonut Jerusalemiin rangaistaa.","Niinkuin myös ylimmäinen pappi ja koko vanhimpain joukko minun todistajani ovat, joilta minä otin lähetyskirjat veljein tykö, ja vaelsin Damaskuun, että minä ne, jotka siellä olivat, olisin sidottuna tuonut Jerusalemiin rangaistaa."],[22,6,"Niin tapahtui minun matkassa ollessani ja lähestyissäni Damaskua puolipäivän aikaan, että suuri kirkkaus valaisi äkisti taivaasta minua ympäri.","Niin tapahtui minun matkassa ollessani ja lähestyissäni Damaskua puolipäivän aikaan, että suuri kirkkaus valaisi äkisti taivaasta minua ympäri."],[22,7,"Ja minä lankesin maahan ja kuulin äänen minulle sanovan: Saul, Saul, miksis minua vainoot?","Ja minä lankesin maahan ja kuulin äänen minulle sanovan: Saul, Saul, miksis minua vainoot?"],[22,8,"Niin minä vastasin: kuka sinä olet, Herra? Hän sanoi minulle: minä olen Jesus Natsaretista, jota sinä vainoot.","Niin minä vastasin: kuka sinä olet, Herra? Hän sanoi minulle: minä olen Jesus Natsaretista, jota sinä vainoot."],[22,9,"Mutta ne, jotka minun kanssani olivat, näkivät kyllä kirkkauden ja peljästyivät, vaan ei he hänen ääntänsä kuulleet, joka minua puhutteli.","Mutta ne, jotka minun kanssani olivat, näkivät kyllä kirkkauden ja peljästyivät, vaan ei he hänen ääntänsä kuulleet, joka minua puhutteli."],[22,10,"Niin minä sanoin: Herra, mitä minun pitää tekemän? Mutta Herra sanoi minulle: nouse ja mene Damaskuun, ja siellä sinulle sanotaan kaikki, mitä sinun on säätty tehdäkses.","Niin minä sanoin: Herra, mitä minun pitää tekemän? Mutta Herra sanoi minulle: nouse ja mene Damaskuun, ja siellä sinulle sanotaan kaikki, mitä sinun on säätty tehdäkses."],[22,11,"Ja koska en minä nähnyt sen valkeuden kirkkauden tähden, talutettiin minä käsistä niiltä, jotka minun kanssani olivat, ja tulin Damaskuun.","Ja koska en minä nähnyt sen valkeuden kirkkauden tähden, talutettiin minä käsistä niiltä, jotka minun kanssani olivat, ja tulin Damaskuun."],[22,12,"Ja siellä oli jumalinen mies lain jälkeen, Ananias niemeltä; hänellä oli hyvä todistus kaikilta Juudalaisilta, jotka siellä asuivat.","Ja siellä oli jumalinen mies lain jälkeen, Ananias niemeltä; hänellä oli hyvä todistus kaikilta Juudalaisilta, jotka siellä asuivat."],[22,13,"Hän tuli minun tyköni, seisoi ja sanoi minulle: rakas veljeni Saul, saa sinun näkös jälleen. Ja minä katsoin sillä hetkellä hänen päällensä.","Hän tuli minun tyköni, seisoi ja sanoi minulle: rakas veljeni Saul, saa sinun näkös jälleen. Ja minä katsoin sillä hetkellä hänen päällensä."],[22,14,"Niin hän sanoi: meidän isäimme Jumala on sinun valmistanut, että sinun pitää tunteman hänen tahtonsa, ja näkemän vanhurskaan, ja kuuleman ääntä hänen suustansa.","Niin hän sanoi: meidän isäimme Jumala on sinun valmistanut, että sinun pitää tunteman hänen tahtonsa, ja näkemän vanhurskaan, ja kuuleman ääntä hänen suustansa."],[22,15,"Sillä sinun pitää oleman hänen todistajansa kaikkein ihmisten edessä niistä, joita sinä nähnyt ja kuullut olet.","Sillä sinun pitää oleman hänen todistajansa kaikkein ihmisten edessä niistä, joita sinä nähnyt ja kuullut olet."],[22,16,"Ja mitäs nyt viivyttelet? Nouse ja anna sinus kastettaa ja pestä pois sinun syntis, ja huuda avuksi Herran nimeä.","Ja mitäs nyt viivyttelet? Nouse ja anna sinus kastettaa ja pestä pois sinun syntis, ja huuda avuksi Herran nimeä."],[22,17,"Niin tapahtui, kuin minä Jerusalemiin palasin ja rukoilin templissä, että minä tulin horroksiin,","Niin tapahtui, kuin minä Jerusalemiin palasin ja rukoilin templissä, että minä tulin horroksiin,"],[22,18,"Ja näin hänen minulle sanovan: riennä ja lähde kiiruusti Jerusalemista; sillä ei he ota vastaan sinun todistustas minusta.","Ja näin hänen minulle sanovan: riennä ja lähde kiiruusti Jerusalemista; sillä ei he ota vastaan sinun todistustas minusta."],[22,19,"Ja minä sanoin: Herra, itse he tietävät, että minä panin torniin ja pieksin jokaisessa synagogassa niitä, jotka sinun päälles uskoivat.","Ja minä sanoin: Herra, itse he tietävät, että minä panin torniin ja pieksin jokaisessa synagogassa niitä, jotka sinun päälles uskoivat."],[22,20,"Ja kuin Stephanin sinun palvelias veri vuodatettiin, olin minä myös siinä läsnä, ja mielistyin hänen kuolemaansa, ja vartioitsin niiden vaatteita, jotka hänen tappoivat.","Ja kuin Stephanin sinun palvelias veri vuodatettiin, olin minä myös siinä läsnä, ja mielistyin hänen kuolemaansa, ja vartioitsin niiden vaatteita, jotka hänen tappoivat."],[22,21,"Ja hän sanoi minulle: mene, sillä minä lähetän sinun kauvas pakanain tykö.","Ja hän sanoi minulle: mene, sillä minä lähetän sinun kauvas pakanain tykö."],[22,22,"Ja he kuulivat häntä tähän sanaan asti, niin he korottivat äänensä ja sanoivat: ota pois senkaltainen ihminen maan päältä; sillä ei hänen ole luvallinen elää.","Ja he kuulivat häntä tähän sanaan asti, niin he korottivat äänensä ja sanoivat: ota pois senkaltainen ihminen maan päältä; sillä ei hänen ole luvallinen elää."],[22,23,"Ja kuin he niin huusivat, heittelivät vaatteitansa ja paiskasivat tomua tuuleen,","Ja kuin he niin huusivat, heittelivät vaatteitansa ja paiskasivat tomua tuuleen,"],[22,24,"Antoi sodanpäämies hänen viedä leiriin, ja käski piestä ja tutkittaa, että hän olis saanut tietää, minkätähden hänen päällensä niin huudettiin.","Antoi sodanpäämies hänen viedä leiriin, ja käski piestä ja tutkittaa, että hän olis saanut tietää, minkätähden hänen päällensä niin huudettiin."],[22,25,"Kuin hän häntä nuorilla sitoi, sanoi Paavali sadanpäämiehelle, joka läsnä seisoi: onkos teidän kohtuullinen Roomalaista hosua ilman tuomitsematta?","Kuin hän häntä nuorilla sitoi, sanoi Paavali sadanpäämiehelle, joka läsnä seisoi: onkos teidän kohtuullinen Roomalaista hosua ilman tuomitsematta?"],[22,26,"Kuin sadanpäämies sen kuuli, meni hän sodanpäämiehen tykö, ilmoitti hänelle ja sanoi: mitäs tahdot tehdä? sillä tämä mies on Roomalainen.","Kuin sadanpäämies sen kuuli, meni hän sodanpäämiehen tykö, ilmoitti hänelle ja sanoi: mitäs tahdot tehdä? sillä tämä mies on Roomalainen."],[22,27,"Niin sodanpäämies meni hänen tykönsä ja sanoi hänelle: sanos minulle, oletko sinä Roomalainen? Hän sanoi: olen niinkin.","Niin sodanpäämies meni hänen tykönsä ja sanoi hänelle: sanos minulle, oletko sinä Roomalainen? Hän sanoi: olen niinkin."],[22,28,"Ja sodanpäämies vastasi: minä olen suurella rahalla tämän kaupungin oikeuden voittanut. Mutta Paavali sanoi: minä olen myös syntynyt (Roomalainen.)","Ja sodanpäämies vastasi: minä olen suurella rahalla tämän kaupungin oikeuden voittanut. Mutta Paavali sanoi: minä olen myös syntynyt (Roomalainen.)"],[22,29,"Ja he läksivät kohta hänen tyköänsä tutkimasta. Ja sodanpäämies rupesi pelkäämään, sittekuin hän sai tietää, hänen Roomalaisen olevan, että hän hänen sitonut oli.","Ja he läksivät kohta hänen tyköänsä tutkimasta. Ja sodanpäämies rupesi pelkäämään, sittekuin hän sai tietää, hänen Roomalaisen olevan, että hän hänen sitonut oli."],[22,30,"Mutta toisena päivänä tahtoi hän visummasti tietää, minkätähden hänen päällensä Juudalaisilta kannettiin, ja päästi hänen siteistä, ja käski ylimmäiset papit ja kaiken heidän raatinsa tulla kokoon, ja antoi Paavalin tulla heidän eteensä.","Mutta toisena päivänä tahtoi hän visummasti tietää, minkätähden hänen päällensä Juudalaisilta kannettiin, ja päästi hänen siteistä, ja käski ylimmäiset papit ja kaiken heidän raatinsa tulla kokoon, ja antoi Paavalin tulla heidän eteensä."],[23,1,"Niin Paavali katsahti raadin päälle ja sanoi: miehet, rakkaat veljet! minä olen kaikella hyvällä tunnolla vaeltanut Jumalan edessä tähän päivään asti.","Niin Paavali katsahti raadin päälle ja sanoi: miehet, rakkaat veljet! minä olen kaikella hyvällä tunnolla vaeltanut Jumalan edessä tähän päivään asti."],[23,2,"Niin ylimmäinen pappi Ananias käski niitä, jotka läsnä seisoivat, lyödä häntä vasten suuta.","Niin ylimmäinen pappi Ananias käski niitä, jotka läsnä seisoivat, lyödä häntä vasten suuta."],[23,3,"Paavali sanoi hänelle: lyököön sinua Jumala, sinä valkeaksi tehty seinä! istutko sinä ja tuomitset minua lain jälkeen, ja käsket minua lyödä vastoin lakia?","Paavali sanoi hänelle: lyököön sinua Jumala, sinä valkeaksi tehty seinä! istutko sinä ja tuomitset minua lain jälkeen, ja käsket minua lyödä vastoin lakia?"],[23,4,"Mutta ne, jotka läsnä seisoivat, sanoivat: kiroiletko sinä ylimmäistä Jumalan pappia?","Mutta ne, jotka läsnä seisoivat, sanoivat: kiroiletko sinä ylimmäistä Jumalan pappia?"],[23,5,"Paavali sanoi: en minä tietänyt, rakkaat veljet, häntä ylimmäiseksi papiksi; sillä kirjoitettu on: sinun kansas ylimmäistä ei sinun pidä kiroileman.","Paavali sanoi: en minä tietänyt, rakkaat veljet, häntä ylimmäiseksi papiksi; sillä kirjoitettu on: sinun kansas ylimmäistä ei sinun pidä kiroileman."],[23,6,"Kuin Paavali tiesi, että heitä oli yksi osa Saddukealaisia ja toinen osa Pharisealaisia, huusi hän raadin edessä: miehet, rakkaat veljet! minä olen Pharisealainen ja Pharisealaisen poika. Minun päälleni kannetaan toivon ja kuolleiden ylösnousemisen tähden.","Kuin Paavali tiesi, että heitä oli yksi osa Saddukealaisia ja toinen osa Pharisealaisia, huusi hän raadin edessä: miehet, rakkaat veljet! minä olen Pharisealainen ja Pharisealaisen poika. Minun päälleni kannetaan toivon ja kuolleiden ylösnousemisen tähden."],[23,7,"Ja kuin hän sen sanonut oli, tuli riita Pharisealaisten ja Saddukealaisten välille, ja joukko erkani.","Ja kuin hän sen sanonut oli, tuli riita Pharisealaisten ja Saddukealaisten välille, ja joukko erkani."],[23,8,"Sillä Saddukealaiset sanovat: ettei kuolleiden ylösnousemista, eikä enkeleitä, eikä henkeä ole; mutta Pharisealaiset tunnustavat molemmat olevan.","Sillä Saddukealaiset sanovat: ettei kuolleiden ylösnousemista, eikä enkeleitä, eikä henkeä ole; mutta Pharisealaiset tunnustavat molemmat olevan."],[23,9,"Niin tuli suuri huuto, ja kirjanoppineet Pharisealaisten lahkosta nousivat, kilvoittelivat ja sanoivat: emme mitään pahaa löydä tässä miehessä: jos henki taikka enkeli on hänelle puhunut, niin emme mahda Jumalaa vastaan sotia.","Niin tuli suuri huuto, ja kirjanoppineet Pharisealaisten lahkosta nousivat, kilvoittelivat ja sanoivat: emme mitään pahaa löydä tässä miehessä: jos henki taikka enkeli on hänelle puhunut, niin emme mahda Jumalaa vastaan sotia."],[23,10,"Ja että suuri kapina nousi, pelkäsi sodanpäämies, ettei he Paavalia rikki repäisisi, ja käski sotaväen mennä alas, ja temmata pois häntä heidän seastansa, ja leiriin viedä.","Ja että suuri kapina nousi, pelkäsi sodanpäämies, ettei he Paavalia rikki repäisisi, ja käski sotaväen mennä alas, ja temmata pois häntä heidän seastansa, ja leiriin viedä."],[23,11,"Mutta yöllä sen jälkeen seisoi Herra hänen tykönänsä ja sanoi: ole vahvassa turvassa, Paavali! sillä niinkuin sinä olet minusta Jerusalemissa todistanut, niin sinun pitää Roomissakin todistaman.","Mutta yöllä sen jälkeen seisoi Herra hänen tykönänsä ja sanoi: ole vahvassa turvassa, Paavali! sillä niinkuin sinä olet minusta Jerusalemissa todistanut, niin sinun pitää Roomissakin todistaman."],[23,12,"Ja kuin päivä tuli, kokoontuivat muutamat Juudalaisista ja sadattelivat itsiänsä, sanoen, ettei heidän pitänyt ennen syömän eikä juoman, kuin he Paavalin olisivat tappaneet.","Ja kuin päivä tuli, kokoontuivat muutamat Juudalaisista ja sadattelivat itsiänsä, sanoen, ettei heidän pitänyt ennen syömän eikä juoman, kuin he Paavalin olisivat tappaneet."],[23,13,"Ja niitä oli enempi kuin neljäkymmentä miestä, jotka tämän valan tehneet olivat.","Ja niitä oli enempi kuin neljäkymmentä miestä, jotka tämän valan tehneet olivat."],[23,14,"Ne menivät ylimmäisten pappein ja vanhimpain tykö, ja sanoivat: me olemme sadatuksilla meitämme kironneet, ei ennen einettä maistavamme kuin me Paavalin tapamme.","Ne menivät ylimmäisten pappein ja vanhimpain tykö, ja sanoivat: me olemme sadatuksilla meitämme kironneet, ei ennen einettä maistavamme kuin me Paavalin tapamme."],[23,15,"Nyt siis ilmoittakaat sodanpäämiehelle ja raadille, että hän huomenna tois hänen teidän eteenne, niinkuin te tahtoisitte jotakin todempaa häneltä tiedustaa; mutta ennenkuin hän lähestyy, olemme me valmiit häntä tappamaan.","Nyt siis ilmoittakaat sodanpäämiehelle ja raadille, että hän huomenna tois hänen teidän eteenne, niinkuin te tahtoisitte jotakin todempaa häneltä tiedustaa; mutta ennenkuin hän lähestyy, olemme me valmiit häntä tappamaan."],[23,16,"Kuin Paavalin sisaren poika heidän väijymisensä kuuli, meni hän leiriin ja ilmoitti nämät Paavalille.","Kuin Paavalin sisaren poika heidän väijymisensä kuuli, meni hän leiriin ja ilmoitti nämät Paavalille."],[23,17,"Niin Paavali kutsui yhden sadanpäämiehistä tykönsä ja sanoi: vie tämä nuorukainen sodanpäämiehen tykö; sillä hänellä on jotakin hänelle sanomista.","Niin Paavali kutsui yhden sadanpäämiehistä tykönsä ja sanoi: vie tämä nuorukainen sodanpäämiehen tykö; sillä hänellä on jotakin hänelle sanomista."],[23,18,"Niin hän otti sen ja saatti hänen sodanpäämiehen tykö, ja sanoi: sidottu Paavali kutsui minun tykönsä ja rukoili minua tätä nuorukaista sinun tykös saattaa, jolla on sinulle jotakin sanomista.","Niin hän otti sen ja saatti hänen sodanpäämiehen tykö, ja sanoi: sidottu Paavali kutsui minun tykönsä ja rukoili minua tätä nuorukaista sinun tykös saattaa, jolla on sinulle jotakin sanomista."],[23,19,"Niin sodanpäämies rupesi hänen käteensä, ja vei hänen erinänsä, ja kyseli häneltä: mitä se on, mitä sinulla on minulle ilmoittamista?","Niin sodanpäämies rupesi hänen käteensä, ja vei hänen erinänsä, ja kyseli häneltä: mitä se on, mitä sinulla on minulle ilmoittamista?"],[23,20,"Niin hän sanoi: Juudalaiset ovat päättäneet sinua rukoilla, ettäs huomenna tuottaisit Paavalin raadin eteen, niinkuin he jotakin todempaa häneltä kuuntelisivat.","Niin hän sanoi: Juudalaiset ovat päättäneet sinua rukoilla, ettäs huomenna tuottaisit Paavalin raadin eteen, niinkuin he jotakin todempaa häneltä kuuntelisivat."],[23,21,"Mutta älä heitä tottele; sillä enempi kuin neljäkymmentä miestä väijyy häntä, jotka ovat heitänsä sadattaneet, ei ennen syövänsä eikä juovansa, kuin he hänen tappaisivat: ja he ovat nyt valmiit odottamassa sinun lupaamistas.","Mutta älä heitä tottele; sillä enempi kuin neljäkymmentä miestä väijyy häntä, jotka ovat heitänsä sadattaneet, ei ennen syövänsä eikä juovansa, kuin he hänen tappaisivat: ja he ovat nyt valmiit odottamassa sinun lupaamistas."],[23,22,"Niin sodanpäämies laski nuorukaisen matkaansa ja haasti häntä kellenkään sanomasta, että hän nämät hänelle ilmoittanut oli.","Niin sodanpäämies laski nuorukaisen matkaansa ja haasti häntä kellenkään sanomasta, että hän nämät hänelle ilmoittanut oli."],[23,23,"Ja hän kutsui tykönsä kaksi sadanpäämiestä ja sanoi: valmistakaat kaksisataa sotamiestä menemään Kesareaan, ja seitsemänkymmentä ratsasmiestä, ja kaksisataa keihäsmiestä kolmannella hetkellä yöstä.","Ja hän kutsui tykönsä kaksi sadanpäämiestä ja sanoi: valmistakaat kaksisataa sotamiestä menemään Kesareaan, ja seitsemänkymmentä ratsasmiestä, ja kaksisataa keihäsmiestä kolmannella hetkellä yöstä."],[23,24,"Ja valmistakaat muutamia juhtia, että he Paavalin niiden päälle istuttavat ja vievät terveenä maanvanhimman Feliksen tykö.","Ja valmistakaat muutamia juhtia, että he Paavalin niiden päälle istuttavat ja vievät terveenä maanvanhimman Feliksen tykö."],[23,25,"Ja kirjoitti kirjan tällä tavalla:","Ja kirjoitti kirjan tällä tavalla:"],[23,26,"Klaudius Lysias sille jalolle maanvanhimmalle Felikselle terveyttä!","Klaudius Lysias sille jalolle maanvanhimmalle Felikselle terveyttä!"],[23,27,"Tämän miehen olivat Juudalaiset ottaneet kiinni ja tahtoivat hänen tappaa. Niin tulin minä parhaallansa sotaväellä sekaan ja tempasin hänen pois, että minä ymmärsin hänen Roomalaisen olevan.","Tämän miehen olivat Juudalaiset ottaneet kiinni ja tahtoivat hänen tappaa. Niin tulin minä parhaallansa sotaväellä sekaan ja tempasin hänen pois, että minä ymmärsin hänen Roomalaisen olevan."],[23,28,"Ja kuin minä pyysin syytä tietää, mistä he häntä nuhtelivat, niin minä vein hänen heidän raatinsa eteen,","Ja kuin minä pyysin syytä tietää, mistä he häntä nuhtelivat, niin minä vein hänen heidän raatinsa eteen,"],[23,29,"Ja löysin kannettavan hänen päällensä heidän lakinsa kysymyksistä. Ja ei kuitenkaan heillä ollut yhtään kuoleman eli sidetten syytä.","Ja löysin kannettavan hänen päällensä heidän lakinsa kysymyksistä. Ja ei kuitenkaan heillä ollut yhtään kuoleman eli sidetten syytä."],[23,30,"Ja kuin minulle siitä väijymisestä ilmoitettiin, jota Juudalaiset hänelle valmistivat, lähetin minä kohta hänen sinun tykös, ja sanoin hänen päällekantajillensa: mitä teillä on häntä vastaan, niin sanokaat maanvanhimman edessä. Ole hyvästi!","Ja kuin minulle siitä väijymisestä ilmoitettiin, jota Juudalaiset hänelle valmistivat, lähetin minä kohta hänen sinun tykös, ja sanoin hänen päällekantajillensa: mitä teillä on häntä vastaan, niin sanokaat maanvanhimman edessä. Ole hyvästi!"],[23,31,"Ja sotamiehet ottivat Paavalin, niinkuin heille käsketty oli, ja veivät hänen yöllä Antipatrideen.","Ja sotamiehet ottivat Paavalin, niinkuin heille käsketty oli, ja veivät hänen yöllä Antipatrideen."],[23,32,"Ja toisena päivän antoivat he ratsasmiesten häntä seurata ja palasivat leiriin.","Ja toisena päivän antoivat he ratsasmiesten häntä seurata ja palasivat leiriin."],[23,33,"Kuin he tulivat Kesareaan ja antoivat kirjan maanvanhimmalle, niin he asettivat myös Paavalin hänen eteensä.","Kuin he tulivat Kesareaan ja antoivat kirjan maanvanhimmalle, niin he asettivat myös Paavalin hänen eteensä."],[23,34,"Kuin maanvanhin oli kirjan lukenut ja kysynyt, kusta maakunnasta hänen piti oleman; ja että hän ymmärsi hänen Kilikiasta olevan,","Kuin maanvanhin oli kirjan lukenut ja kysynyt, kusta maakunnasta hänen piti oleman; ja että hän ymmärsi hänen Kilikiasta olevan,"],[23,35,"Minä tahdon sinua kuulla, sanoi hän, kuin myös sinun päällekantajas tulevat edes. Ja käski kätkeä hänen Herodeksen raatihuoneeseen.","Minä tahdon sinua kuulla, sanoi hän, kuin myös sinun päällekantajas tulevat edes. Ja käski kätkeä hänen Herodeksen raatihuoneeseen."],[24,1,"Viiden päivän perästä meni Ananias, ylimmäinen pappi, vanhimpain ja selväkielisen Tertulluksen kanssa maanvanhimman tykö Paavalia vastaan.","Viiden päivän perästä meni Ananias, ylimmäinen pappi, vanhimpain ja selväkielisen Tertulluksen kanssa maanvanhimman tykö Paavalia vastaan."],[24,2,"Ja kuin hän oli eteen kutsuttu, rupesi Tertullus kantamaan, sanoen:","Ja kuin hän oli eteen kutsuttu, rupesi Tertullus kantamaan, sanoen:"],[24,3,"Me elämme hyvässä rauhassa sinun kauttas, ja ne asiat, jotka tässä kansassa oikein ja hyvin tehnyt ovat sinun toimellas, voimallinen Feliks, me aina ja joka paikassa hyväksi otamme kaikella kiitoksella.","Me elämme hyvässä rauhassa sinun kauttas, ja ne asiat, jotka tässä kansassa oikein ja hyvin tehnyt ovat sinun toimellas, voimallinen Feliks, me aina ja joka paikassa hyväksi otamme kaikella kiitoksella."],[24,4,"Vaan etten minä sinua kauvan viivyttäisi, rukoilen minä sinua, ettäs pikimiltäs meitä kuulisit, sinun vakuutes tähden.","Vaan etten minä sinua kauvan viivyttäisi, rukoilen minä sinua, ettäs pikimiltäs meitä kuulisit, sinun vakuutes tähden."],[24,5,"Sillä me olemme löytäneet tämän miehen vahingolliseksi, joka nostaa kapinan kaikille Juudalaisille ympäri koko maanpiirin, ja on Natsarealaisten eriseuran päämies.","Sillä me olemme löytäneet tämän miehen vahingolliseksi, joka nostaa kapinan kaikille Juudalaisille ympäri koko maanpiirin, ja on Natsarealaisten eriseuran päämies."],[24,6,"Hän on kiusannut templiäkin riivata; jonka tähden me otimme hänen kiinni ja tahdoimme tuomita hänen meidän lakimme jälkeen.","Hän on kiusannut templiäkin riivata; jonka tähden me otimme hänen kiinni ja tahdoimme tuomita hänen meidän lakimme jälkeen."],[24,7,"Mutta sodanpäämies Lysias tuli suurella väellä siihen sekaan ja päästi hänen meidän käsistämme,","Mutta sodanpäämies Lysias tuli suurella väellä siihen sekaan ja päästi hänen meidän käsistämme,"],[24,8,"Ja käski hänen päällekantajansa tulla sinun tykös; josta sinä taidat itse tutkien ymmärtää kaikista niistä, joita me hänen päällensä kannamme.","Ja käski hänen päällekantajansa tulla sinun tykös; josta sinä taidat itse tutkien ymmärtää kaikista niistä, joita me hänen päällensä kannamme."],[24,9,"Ja Juudalaiset tähän myös mielistyivät, sanoen niin olevan.","Ja Juudalaiset tähän myös mielistyivät, sanoen niin olevan."],[24,10,"Niin Paavali vastasi, kuin maanvanhin häntä viittasi puhumaan: että minä tiedän sinun monta ajastaikaa olleen tämän kansan tuomarina, tahdon minä pelkäämättä edestäni vastata.","Niin Paavali vastasi, kuin maanvanhin häntä viittasi puhumaan: että minä tiedän sinun monta ajastaikaa olleen tämän kansan tuomarina, tahdon minä pelkäämättä edestäni vastata."],[24,11,"Sillä sinä taidat ymmärtää, ettei enempi ole kuin kaksitoistakymmentä päivää, sittekuin minä menin ylös Jerusalemiin rukoilemaan.","Sillä sinä taidat ymmärtää, ettei enempi ole kuin kaksitoistakymmentä päivää, sittekuin minä menin ylös Jerusalemiin rukoilemaan."],[24,12,"Ja ei he ole minua templissäkään löytäneet kamppailemasta yhdenkään kanssa, ei kapinaa nostamasta kansan seassa, ei synagogissa, eikä kaupungissa.","Ja ei he ole minua templissäkään löytäneet kamppailemasta yhdenkään kanssa, ei kapinaa nostamasta kansan seassa, ei synagogissa, eikä kaupungissa."],[24,13,"Ei he myös taida niitä vahvistaa, mitä he nyt minun päälleni kantavat.","Ei he myös taida niitä vahvistaa, mitä he nyt minun päälleni kantavat."],[24,14,"Mutta sen minä sinulle tunnustan, että minä tämän tien kautta, jonka he eriseuraksi kutsuvat, niin palvelen minun isäini Jumalaa, että minä uskon kaikki, mitkä laissa ja prophetaissa kirjoitetut ovat,","Mutta sen minä sinulle tunnustan, että minä tämän tien kautta, jonka he eriseuraksi kutsuvat, niin palvelen minun isäini Jumalaa, että minä uskon kaikki, mitkä laissa ja prophetaissa kirjoitetut ovat,"],[24,15,"Ja pidän sen toivon Jumalan puoleen, jota hekin itse odottavat, että kuolleiden ylösnousemus pitää oleman, sekä vanhurskasten että vääräin.","Ja pidän sen toivon Jumalan puoleen, jota hekin itse odottavat, että kuolleiden ylösnousemus pitää oleman, sekä vanhurskasten että vääräin."],[24,16,"Ja sentähden minä harjoitan itsiäni aina pitämään pahentamattoman omantunnon Jumalan ja ihmisten edessä.","Ja sentähden minä harjoitan itsiäni aina pitämään pahentamattoman omantunnon Jumalan ja ihmisten edessä."],[24,17,"Mutta kuin minä monen ajastajan perästä tulin almua ja uhria kansalleni tekemään:","Mutta kuin minä monen ajastajan perästä tulin almua ja uhria kansalleni tekemään:"],[24,18,"Joissa muutamat Juudalaiset Asiasta löysivät minun puhdistettuna templissä, ilman yhtäkään kapinaa ja meteliä,","Joissa muutamat Juudalaiset Asiasta löysivät minun puhdistettuna templissä, ilman yhtäkään kapinaa ja meteliä,"],[24,19,"Joidenka tulis sinun tykönäs läsnä olla ja kantaa, jos heillä jotakin on minua vastaan.","Joidenka tulis sinun tykönäs läsnä olla ja kantaa, jos heillä jotakin on minua vastaan."],[24,20,"Eli sanokaan nämät itse, jos he jotakin vääryyttä ovat minussa löytäneet, koska minä seisoin raadin edessä.","Eli sanokaan nämät itse, jos he jotakin vääryyttä ovat minussa löytäneet, koska minä seisoin raadin edessä."],[24,21,"Mutta tämän yhden sanan tähden, jonka minä heidän seassansa seisoissani, kuolleiden ylösnousemisesta, huusin, minä teiltä tänäpänä tuomitaan.","Mutta tämän yhden sanan tähden, jonka minä heidän seassansa seisoissani, kuolleiden ylösnousemisesta, huusin, minä teiltä tänäpänä tuomitaan."],[24,22,"Kuin Feliks tämän kuuli, viivytti hän heitä; sillä hän tiesi hyvin tämän tien menon, ja sanoi: kuin Lysias sodanpäämies alas tulee, niin minä tahdon tutkia teidän asianne.","Kuin Feliks tämän kuuli, viivytti hän heitä; sillä hän tiesi hyvin tämän tien menon, ja sanoi: kuin Lysias sodanpäämies alas tulee, niin minä tahdon tutkia teidän asianne."],[24,23,"Ja käski sadanpäämiehen kätkeä Paavalin, ja antoi hänen saada levon, ja ettei yhtäkään hänen omistansa kiellettäisi häntä palvelemasta taikka käymästä hänen tykönänsä.","Ja käski sadanpäämiehen kätkeä Paavalin, ja antoi hänen saada levon, ja ettei yhtäkään hänen omistansa kiellettäisi häntä palvelemasta taikka käymästä hänen tykönänsä."],[24,24,"Mutta muutamain päiväin perästä tuli Feliks emäntänsä Drusillan kanssa, joka Juudalainen oli, ja kutsutti Paavalin eteensä, ja kuulteli häntä uskosta Kristuksen päälle.","Mutta muutamain päiväin perästä tuli Feliks emäntänsä Drusillan kanssa, joka Juudalainen oli, ja kutsutti Paavalin eteensä, ja kuulteli häntä uskosta Kristuksen päälle."],[24,25,"Mutta kuin hän puhui vanhurskaudesta ja puhtaasta elämästä ja tulevaisesta tuomiosta, peljästyi Feliks, ja vastasi: mene tällä haavalla matkaas; vaan kuin minä saan tilan, niin minä sinun tyköni kutsutan.","Mutta kuin hän puhui vanhurskaudesta ja puhtaasta elämästä ja tulevaisesta tuomiosta, peljästyi Feliks, ja vastasi: mene tällä haavalla matkaas; vaan kuin minä saan tilan, niin minä sinun tyköni kutsutan."],[24,26,"Toivoi myös Paavalilta hänellensä rahaa annettavan, että hän olis hänen päästänyt, jonka tähden hän myös usein hänen tykönsä kutsutti ja puheli hänen kanssansa.","Toivoi myös Paavalilta hänellensä rahaa annettavan, että hän olis hänen päästänyt, jonka tähden hän myös usein hänen tykönsä kutsutti ja puheli hänen kanssansa."],[24,27,"Kuin kaksi ajastaikaa kulunut oli, tuli Porkius Festus Feliksen siaan. Mutta Feliks tahtoi Juudalaisten mieltä noutaa ja jätti Paavalin sidottuna.","Kuin kaksi ajastaikaa kulunut oli, tuli Porkius Festus Feliksen siaan. Mutta Feliks tahtoi Juudalaisten mieltä noutaa ja jätti Paavalin sidottuna."],[25,1,"Kuin siis Festus oli tullut maakuntaan, meni hän Kesareasta kolmannen päivän perästä ylös Jerusalemiin.","Kuin siis Festus oli tullut maakuntaan, meni hän Kesareasta kolmannen päivän perästä ylös Jerusalemiin."],[25,2,"Niin ylimmäinen pappi ja ylimmäiset Juudalaisista tulivat hänen eteensä Paavalia vastaan, ja rukoilivat häntä,","Niin ylimmäinen pappi ja ylimmäiset Juudalaisista tulivat hänen eteensä Paavalia vastaan, ja rukoilivat häntä,"],[25,3,"Ja pyysivät häneltä suosiota häntä kohtaan, että hän kutsuttais hänen Jerusalemiin, ja väijyivät häntä tappaaksensa tiellä.","Ja pyysivät häneltä suosiota häntä kohtaan, että hän kutsuttais hänen Jerusalemiin, ja väijyivät häntä tappaaksensa tiellä."],[25,4,"Niin Festus vastasi, että Paavali piti hyvin kätkettämän Kesareassa, ja että hän tahtoi itse pian sinne vaeltaa.","Niin Festus vastasi, että Paavali piti hyvin kätkettämän Kesareassa, ja että hän tahtoi itse pian sinne vaeltaa."],[25,5,"Jotka siis teidän seassanne, sanoi hän, voimalliset ovat, ne tulkaan alas meidän kanssamme, ja jos jotakin vääryyttä on tässä miehessä, niin kantakaan he hänen päällensä.","Jotka siis teidän seassanne, sanoi hän, voimalliset ovat, ne tulkaan alas meidän kanssamme, ja jos jotakin vääryyttä on tässä miehessä, niin kantakaan he hänen päällensä."],[25,6,"Kuin hän siis oli heidän tykönänsä viipynyt enempi kuin kymmenen päivää, läksi hän alas Kesareaan. Ja toisena päivänä istui hän tuomioistuimelle ja käski Paavalin tuoda edes.","Kuin hän siis oli heidän tykönänsä viipynyt enempi kuin kymmenen päivää, läksi hän alas Kesareaan. Ja toisena päivänä istui hän tuomioistuimelle ja käski Paavalin tuoda edes."],[25,7,"Kuin hän oli tullut edes, seisoivat ne Juudalaiset ympärillä, jotka olivat Jerusalemista tulleet alas, ja toivat edes monta ja suurta vikaa Paavalia vastaan, joita ei he voineet vahvistaa;","Kuin hän oli tullut edes, seisoivat ne Juudalaiset ympärillä, jotka olivat Jerusalemista tulleet alas, ja toivat edes monta ja suurta vikaa Paavalia vastaan, joita ei he voineet vahvistaa;"],[25,8,"Sillä hän vastasi edestänsä: en minä ole mitään rikkonut Juudalaisten lakia, en templiä, enkä keisaria vastaan.","Sillä hän vastasi edestänsä: en minä ole mitään rikkonut Juudalaisten lakia, en templiä, enkä keisaria vastaan."],[25,9,"Niin Festus tahtoi Juudalaisten mieltä noutaa, vastasi Paavalia ja sanoi: tahdotkos mennä ylös Jerusalemiin ja siellä näistä oikeudella seisoa minun edessäni?","Niin Festus tahtoi Juudalaisten mieltä noutaa, vastasi Paavalia ja sanoi: tahdotkos mennä ylös Jerusalemiin ja siellä näistä oikeudella seisoa minun edessäni?"],[25,10,"Mutta Paavali sanoi: minä seison keisarin oikeudessa, ja siinä tulee minua tuomita: en minä ole Juudalaisille mitään vääryyttä tehnyt, kuin sinä itsekin paremmin tiedät.","Mutta Paavali sanoi: minä seison keisarin oikeudessa, ja siinä tulee minua tuomita: en minä ole Juudalaisille mitään vääryyttä tehnyt, kuin sinä itsekin paremmin tiedät."],[25,11,"Sillä jos minä olen jonkun vahingoittanut, eli minun henkeni rikkonut, niin en minä tahdo välttää kuolemaa: jos ei taas mitään niistä ole, mitä he minun päälleni kantavat, niin ei yksikään taida minua antaa heidän käsiinsä: minä turvaan keisariin.","Sillä jos minä olen jonkun vahingoittanut, eli minun henkeni rikkonut, niin en minä tahdo välttää kuolemaa: jos ei taas mitään niistä ole, mitä he minun päälleni kantavat, niin ei yksikään taida minua antaa heidän käsiinsä: minä turvaan keisariin."],[25,12,"Silloin Festus puhutteli raatia ja vastasi: keisariin sinä turvasit, keisarin tykö pitää myös sinun menemän.","Silloin Festus puhutteli raatia ja vastasi: keisariin sinä turvasit, keisarin tykö pitää myös sinun menemän."],[25,13,"Mutta kuin muutamat päivät olivat kuluneet, tuli kuningas Agrippa ja Bernise alas Kesareaan Festusta tervehtimään.","Mutta kuin muutamat päivät olivat kuluneet, tuli kuningas Agrippa ja Bernise alas Kesareaan Festusta tervehtimään."],[25,14,"Ja kuin he siellä monta päivää viipyivät, jutteli Festus Paavalin asian kuninkaalle ja sanoi: yksi mies on jäänyt Felikseltä sidottuna,","Ja kuin he siellä monta päivää viipyivät, jutteli Festus Paavalin asian kuninkaalle ja sanoi: yksi mies on jäänyt Felikseltä sidottuna,"],[25,15,"Josta, kuin minä Jerusalemissa olin, ylimmäiset papit ja Juudalaisten vanhimmat tulivat ja ilmoittivat minulle, pyytäin tuomiota hänen ylitsensä.","Josta, kuin minä Jerusalemissa olin, ylimmäiset papit ja Juudalaisten vanhimmat tulivat ja ilmoittivat minulle, pyytäin tuomiota hänen ylitsensä."],[25,16,"Joille minä vastasin: ei se ole Roomalaisten tapa, että joku ihminen ennen annetaan surmata, kuin se, jonka päälle kannetaan, saa päällekantajat rinnallensa ja saa tilan edestänsä vastata kanteesta.","Joille minä vastasin: ei se ole Roomalaisten tapa, että joku ihminen ennen annetaan surmata, kuin se, jonka päälle kannetaan, saa päällekantajat rinnallensa ja saa tilan edestänsä vastata kanteesta."],[25,17,"Sentähden kuin he tänne kokoon tulivat, istuin minä kohta toisena päivänä viivyttelemättä tuomioistuimelle, ja käskin miehen tuoda edes.","Sentähden kuin he tänne kokoon tulivat, istuin minä kohta toisena päivänä viivyttelemättä tuomioistuimelle, ja käskin miehen tuoda edes."],[25,18,"Kuin päällekantajat tulivat, niin ei he yhtään syytä tuoneet edes niistä, mitä minä luulin.","Kuin päällekantajat tulivat, niin ei he yhtään syytä tuoneet edes niistä, mitä minä luulin."],[25,19,"Mutta heillä oli muutamia kysymyksiä häntä vastaan heidän taikauksistansa ja yhdestä kuolleesta Jesuksesta, jonka Paavali todisti elävän.","Mutta heillä oli muutamia kysymyksiä häntä vastaan heidän taikauksistansa ja yhdestä kuolleesta Jesuksesta, jonka Paavali todisti elävän."],[25,20,"Vaan että minä siitä kysymyksestä epäilin, kysyin minä, josko hän olis tahtonut mennä Jerusalemiin ja siellä näistä tuomittaa.","Vaan että minä siitä kysymyksestä epäilin, kysyin minä, josko hän olis tahtonut mennä Jerusalemiin ja siellä näistä tuomittaa."],[25,21,"Mutta koska Paavali lykkäsi asiansa keisarin tutkimisen alle, annoin minä hänen kätkettää, siihen asti kuin minä hänen keisarin tykö lähettäisin.","Mutta koska Paavali lykkäsi asiansa keisarin tutkimisen alle, annoin minä hänen kätkettää, siihen asti kuin minä hänen keisarin tykö lähettäisin."],[25,22,"Niin Agrippa sanoi Festukselle: minäkin kuulisin mielelläni sitä miestä. Hän sanoi: huomenna saat sinä häntä kuulla.","Niin Agrippa sanoi Festukselle: minäkin kuulisin mielelläni sitä miestä. Hän sanoi: huomenna saat sinä häntä kuulla."],[25,23,"Ja toisena päivänä tuli Agrippa ja Bernise suurella koreudella, ja menivät raastupaan, päämiesten ja kaupungin ylimmäisten kanssa, ja Paavali tuotiin edes Festuksen käskyn jälkeen.","Ja toisena päivänä tuli Agrippa ja Bernise suurella koreudella, ja menivät raastupaan, päämiesten ja kaupungin ylimmäisten kanssa, ja Paavali tuotiin edes Festuksen käskyn jälkeen."],[25,24,"Ja Festus sanoi: kuningas Agrippa ja kaikki miehet, jotka tässä meidän kanssamme olette, te näette sen, josta kaikki Juudalaisten joukko on minua rukoillut Jerusalemissa ja myös täällä, huutain, ettei hänen pitäisi enempi elämän.","Ja Festus sanoi: kuningas Agrippa ja kaikki miehet, jotka tässä meidän kanssamme olette, te näette sen, josta kaikki Juudalaisten joukko on minua rukoillut Jerusalemissa ja myös täällä, huutain, ettei hänen pitäisi enempi elämän."],[25,25,"Mutta kuin minä ymmärsin, ettei hän ollut mitään kuoleman ansiota tehnyt, ja että hän myös itse turvasi keisariin, niin minä aioin hänen sinne lähettää.","Mutta kuin minä ymmärsin, ettei hän ollut mitään kuoleman ansiota tehnyt, ja että hän myös itse turvasi keisariin, niin minä aioin hänen sinne lähettää."],[25,26,"Josta ei minulla ole mitään vahvaa herralle kirjoittaa: sentähden tuotin minä hänen teidän eteenne, ja enimmiten sinun etees, kuningas Agrippa, että kuin hänen asiansa visummasti tutkittaisiin, minulla olis jotakin kirjoittamista;","Josta ei minulla ole mitään vahvaa herralle kirjoittaa: sentähden tuotin minä hänen teidän eteenne, ja enimmiten sinun etees, kuningas Agrippa, että kuin hänen asiansa visummasti tutkittaisiin, minulla olis jotakin kirjoittamista;"],[25,27,"Sillä se on minun nähdäkseni toimetoin, että hän sidottuna lähetetään, ja ei hänen syytänsä ilmoiteta.","Sillä se on minun nähdäkseni toimetoin, että hän sidottuna lähetetään, ja ei hänen syytänsä ilmoiteta."],[26,1,"Niin Agrippa sanoi Paavalille: sinun on lupa puhua edestäs. Silloin Paavali ojensi kätensä ja vastasi edestänsä:","Niin Agrippa sanoi Paavalille: sinun on lupa puhua edestäs. Silloin Paavali ojensi kätensä ja vastasi edestänsä:"],[26,2,"Minä pidän itseni onnellisena, rakas kuningas Agrippa, että minä tänäpänä saan sinun edessäs vastata kaikista niistä, mitä minun päälleni Juudalaisilta kannetaan,","Minä pidän itseni onnellisena, rakas kuningas Agrippa, että minä tänäpänä saan sinun edessäs vastata kaikista niistä, mitä minun päälleni Juudalaisilta kannetaan,"],[26,3,"Liiatenkin että sinä tiedät kaikki tavat ja Juudalaisten kysymykset: sentähden rukoilen minä sinua, että kärsivällisesti minua kuulisit.","Liiatenkin että sinä tiedät kaikki tavat ja Juudalaisten kysymykset: sentähden rukoilen minä sinua, että kärsivällisesti minua kuulisit."],[26,4,"Kaikki tosin Juudalaiset tietävät minun elämäni hamasta nuoruudesta, kuin se alusta on ollut minun kansani seassa Jerusalemissa:","Kaikki tosin Juudalaiset tietävät minun elämäni hamasta nuoruudesta, kuin se alusta on ollut minun kansani seassa Jerusalemissa:"],[26,5,"Jotka minun ennen ovat tunteneet, (jos he tahtoisivat todistaa,) että minä meidän jumalanpalveluksen kaikkein ahkerimman eriseuran jälkeen olin Pharisealainen.","Jotka minun ennen ovat tunteneet, (jos he tahtoisivat todistaa,) että minä meidän jumalanpalveluksen kaikkein ahkerimman eriseuran jälkeen olin Pharisealainen."],[26,6,"Ja minä seison nyt tässä oikeuden edessä toivon tähden sen lupauksen päälle, joka Jumalalta on meidän isillemme tapahtunut:","Ja minä seison nyt tässä oikeuden edessä toivon tähden sen lupauksen päälle, joka Jumalalta on meidän isillemme tapahtunut:"],[26,7,"Johonka meidän kaksitoistakymmentä sukukuntaa toivovat tulevansa, palvellen Jumalaa yötä ja päivää. Tämän toivon tähden kannetaan Juudalaisilta minun päälleni, rakas kuningas Agrippa.","Johonka meidän kaksitoistakymmentä sukukuntaa toivovat tulevansa, palvellen Jumalaa yötä ja päivää. Tämän toivon tähden kannetaan Juudalaisilta minun päälleni, rakas kuningas Agrippa."],[26,8,"Miksi se luotaan mahdottomaksi uskoa teidän tykönänne, että Jumala kuolleet herättää?","Miksi se luotaan mahdottomaksi uskoa teidän tykönänne, että Jumala kuolleet herättää?"],[26,9,"Minä tosin luulin itselläni, että minun piti paljo vastahakoisuutta tekemän Jesuksen Natsarealaisen nimeä vastaan,","Minä tosin luulin itselläni, että minun piti paljo vastahakoisuutta tekemän Jesuksen Natsarealaisen nimeä vastaan,"],[26,10,"Niinkuin minä myös tein Jerusalemissa, ja salpasin monta pyhää vankihuoneisiin, kuin minä ylimmäisiltä papeilta olin saanut vallan; ja kuin he tapettiin, mielistyin minä heidän tuomioonsa,","Niinkuin minä myös tein Jerusalemissa, ja salpasin monta pyhää vankihuoneisiin, kuin minä ylimmäisiltä papeilta olin saanut vallan; ja kuin he tapettiin, mielistyin minä heidän tuomioonsa,"],[26,11,"Ja rankaisin heitä usein jokaisessa synagogassa, ja vaadin heitä pilkkaamaan, ja olin heitä vastaan ylönpalttisesti vimmattu, ja vainosin heitä hamaan ulkokaupunkeihin.","Ja rankaisin heitä usein jokaisessa synagogassa, ja vaadin heitä pilkkaamaan, ja olin heitä vastaan ylönpalttisesti vimmattu, ja vainosin heitä hamaan ulkokaupunkeihin."],[26,12,"Jonka tähden minä myös matkustin Damaskuun ylimmäisten pappein voimalla ja käskyllä.","Jonka tähden minä myös matkustin Damaskuun ylimmäisten pappein voimalla ja käskyllä."],[26,13,"Puolipäivän aikaan, rakas kuningas, näin minä tiellä yhden kirkkauden taivaasta, kirkkaamman kuin auringon paisteen, joka valkeus ympäri valaisi minun ja ne, jotka minun kanssani vaelsivat.","Puolipäivän aikaan, rakas kuningas, näin minä tiellä yhden kirkkauden taivaasta, kirkkaamman kuin auringon paisteen, joka valkeus ympäri valaisi minun ja ne, jotka minun kanssani vaelsivat."],[26,14,"Kuin me siis kaikki maahan lankesimme, kuulin minä äänen puhuvan minulleni ja sanovan Hebrean kielellä: Saul, Saul, miksis minua vainoot? työläs on sinun tutkainta vastaan potkia.","Kuin me siis kaikki maahan lankesimme, kuulin minä äänen puhuvan minulleni ja sanovan Hebrean kielellä: Saul, Saul, miksis minua vainoot? työläs on sinun tutkainta vastaan potkia."],[26,15,"Niin minä sanoin: Herra, kukas olet? Hän sanoi: minä olen Jesus, jota sinä vainoot.","Niin minä sanoin: Herra, kukas olet? Hän sanoi: minä olen Jesus, jota sinä vainoot."],[26,16,"Mutta nouse ylös ja seiso jaloillas: sillä sitä varten minä sinulle ilmestyin, että minä asetan sinun palveliaksi ja niiden todistajaksi, joita sinä näit, niin myös niiden, joita minä vielä sinulle ilmoittava olen.","Mutta nouse ylös ja seiso jaloillas: sillä sitä varten minä sinulle ilmestyin, että minä asetan sinun palveliaksi ja niiden todistajaksi, joita sinä näit, niin myös niiden, joita minä vielä sinulle ilmoittava olen."],[26,17,"Ja tahdon sinun päästää tästä kansasta ja pakanoista, joiden tykö minä nyt sinun lähetän,","Ja tahdon sinun päästää tästä kansasta ja pakanoista, joiden tykö minä nyt sinun lähetän,"],[26,18,"Heidän silmiänsä avaamaan ja heitä pimeydestä valkeuteen kääntämään, että he eriäisivät saatanan vallasta Jumalan tykö, saamaan syntein anteeksiantamista ja perimistä ynnä niiden kanssa, jotka pyhitetään uskon kautta minun päälleni.","Heidän silmiänsä avaamaan ja heitä pimeydestä valkeuteen kääntämään, että he eriäisivät saatanan vallasta Jumalan tykö, saamaan syntein anteeksiantamista ja perimistä ynnä niiden kanssa, jotka pyhitetään uskon kautta minun päälleni."],[26,19,"Niin siis, rakas kuningas Agrippa! en minä ollut taivaalliselle näylle kovakorvainen,","Niin siis, rakas kuningas Agrippa! en minä ollut taivaalliselle näylle kovakorvainen,"],[26,20,"Vaan ilmoitin ensin niille, jotka Damaskussa ja Jerusalemissa ovat ja kaikessa Juudan maakunnassa, ja myös pakanoille, että he parannuksen tekisivät, ja kääntyisivät Jumalan puoleen, ja tekisivät parannuksen kelvollisia töitä.","Vaan ilmoitin ensin niille, jotka Damaskussa ja Jerusalemissa ovat ja kaikessa Juudan maakunnassa, ja myös pakanoille, että he parannuksen tekisivät, ja kääntyisivät Jumalan puoleen, ja tekisivät parannuksen kelvollisia töitä."],[26,21,"Tämän tähden ovat Juudalaiset minun templissä ottaneet kiinni ja tahtoivat minun surmata.","Tämän tähden ovat Juudalaiset minun templissä ottaneet kiinni ja tahtoivat minun surmata."],[26,22,"Mutta Jumalan avun olen minä saanut ja seisonut tähän päivään asti, todistaen sekä pienille että suurille, enkä mitään muuta sanoen kuin mitä prophetat ja Moses ovat sanoneet tulevaksi:","Mutta Jumalan avun olen minä saanut ja seisonut tähän päivään asti, todistaen sekä pienille että suurille, enkä mitään muuta sanoen kuin mitä prophetat ja Moses ovat sanoneet tulevaksi:"],[26,23,"Että Kristuksen piti kärsimän ja oleman ensimäisen kuolleiden ylösnousemisesta julistamassa valkeutta tälle kansalle ja pakanoille.","Että Kristuksen piti kärsimän ja oleman ensimäisen kuolleiden ylösnousemisesta julistamassa valkeutta tälle kansalle ja pakanoille."],[26,24,"Kuin hän näin edestänsä vastasi, sanoi Festus suurella äänellä: Paavali, sinä hulluttelet, suuri oppi hulluttaa sinua.","Kuin hän näin edestänsä vastasi, sanoi Festus suurella äänellä: Paavali, sinä hulluttelet, suuri oppi hulluttaa sinua."],[26,25,"Niin hän sanoi: en minä hulluttele, voimallinen Festus, vaan totuuden ja toimen sanoja puhun.","Niin hän sanoi: en minä hulluttele, voimallinen Festus, vaan totuuden ja toimen sanoja puhun."],[26,26,"Sillä kyllä kuningas nämät tietää, jonka tykönä minä myös rohkiasti puhun, ja en minä luule näistä mitään olevan häneltä salatun: sillä ei tämä ole loukkaassa tapahtunut.","Sillä kyllä kuningas nämät tietää, jonka tykönä minä myös rohkiasti puhun, ja en minä luule näistä mitään olevan häneltä salatun: sillä ei tämä ole loukkaassa tapahtunut."],[26,27,"Uskotkos, kuningas Agrippa, prophetat? minä tiedän, ettäs uskot.","Uskotkos, kuningas Agrippa, prophetat? minä tiedän, ettäs uskot."],[26,28,"Niin Agrippa sanoi Paavalille: ei paljo puutu, ettes minua saa kristityksi.","Niin Agrippa sanoi Paavalille: ei paljo puutu, ettes minua saa kristityksi."],[26,29,"Paavali sanoi: minä toivoisin Jumalalta, joko siitä puuttuis vähä eli paljo, että et ainoasti sinä, mutta myös kaikki, jotka minua tänäpänä kuulevat, tulisivat senkaltaiseksi kuin minäkin olen, paitsi näitä siteitä.","Paavali sanoi: minä toivoisin Jumalalta, joko siitä puuttuis vähä eli paljo, että et ainoasti sinä, mutta myös kaikki, jotka minua tänäpänä kuulevat, tulisivat senkaltaiseksi kuin minäkin olen, paitsi näitä siteitä."],[26,30,"Ja kuin hän nämät sanonut oli, nousi kuningas ylös, ja maanvanhin, ja Bernise, ja jotka heidän kanssansa istuneet olivat.","Ja kuin hän nämät sanonut oli, nousi kuningas ylös, ja maanvanhin, ja Bernise, ja jotka heidän kanssansa istuneet olivat."],[26,31,"Ja kuin he menivät pois, puhuivat he keskenänsä, sanoen: eipä tämä mies ole mitään tehnyt, mikä kuoleman eli siteet ansainnut on.","Ja kuin he menivät pois, puhuivat he keskenänsä, sanoen: eipä tämä mies ole mitään tehnyt, mikä kuoleman eli siteet ansainnut on."],[26,32,"Mutta Agrippa sanoi Festukselle: kyllä tämä mies olis taidettu päästää, ellei hän olisi keisariin turvannut.","Mutta Agrippa sanoi Festukselle: kyllä tämä mies olis taidettu päästää, ellei hän olisi keisariin turvannut."],[27,1,"Mutta sittenkuin päätetty oli, että meidän piti Italiaan purjehtiman, antoivat he Paavalin muiden vankien kanssa yhden sadanpäämiehen haltuun, joka kutsuttiin Julius, keisarin sotajoukosta.","Mutta sittenkuin päätetty oli, että meidän piti Italiaan purjehtiman, antoivat he Paavalin muiden vankien kanssa yhden sadanpäämiehen haltuun, joka kutsuttiin Julius, keisarin sotajoukosta."],[27,2,"Kuin me siis astuimme Adramytin haahteen, ja meidän piti purjehtiman Asian ohitse, laskimme me ulos maalta. Ja meidän kanssamme oli Aristarkus, Makedonian mies, Tessalonikasta.","Kuin me siis astuimme Adramytin haahteen, ja meidän piti purjehtiman Asian ohitse, laskimme me ulos maalta. Ja meidän kanssamme oli Aristarkus, Makedonian mies, Tessalonikasta."],[27,3,"Ja me tulimme toisena päivänä Sidoniin. Ja Julius meni hyvästi Paavalin kanssa, ja salli hänen mennä ystäväinsä tykö ja heiltä holhottaa.","Ja me tulimme toisena päivänä Sidoniin. Ja Julius meni hyvästi Paavalin kanssa, ja salli hänen mennä ystäväinsä tykö ja heiltä holhottaa."],[27,4,"Ja kuin me sieltä laskimme ulos, niin me purjehdimme Kyprin ohitse, että vastatuulet olivat.","Ja kuin me sieltä laskimme ulos, niin me purjehdimme Kyprin ohitse, että vastatuulet olivat."],[27,5,"Ja kuin me olimme purjehtineet yli meren, joka Kilikian ja Pamphilian kohdalla on, ja tulimme Myraan, joka on Lykiassa,","Ja kuin me olimme purjehtineet yli meren, joka Kilikian ja Pamphilian kohdalla on, ja tulimme Myraan, joka on Lykiassa,"],[27,6,"Niin löysi sadanpäämies siellä yhden Aleksandrialaisen haahden, joka Italiaan purjehti, ja pani meidät siihen.","Niin löysi sadanpäämies siellä yhden Aleksandrialaisen haahden, joka Italiaan purjehti, ja pani meidät siihen."],[27,7,"Kuin me monta päivää hitaasti purjehdimme ja tuskalla Knidon saavutimme, ettemme päässeet tuulelta, niin me purjehdimme Kretan alle, Salmoneen päin.","Kuin me monta päivää hitaasti purjehdimme ja tuskalla Knidon saavutimme, ettemme päässeet tuulelta, niin me purjehdimme Kretan alle, Salmoneen päin."],[27,8,"Ja kuin me tuskin sen ohitse pääsimme, niin me tulimme yhteen paikkaan, joka Kauniiksi satamaksi kutsutaan, jota läsnä oli Lasean kaupunki.","Ja kuin me tuskin sen ohitse pääsimme, niin me tulimme yhteen paikkaan, joka Kauniiksi satamaksi kutsutaan, jota läsnä oli Lasean kaupunki."],[27,9,"Koska paljo aikaa oli kulunut, ja purjehdus oli vaarallinen, ja paaston aika oli jo kulunut, neuvoi Paavali heitä,","Koska paljo aikaa oli kulunut, ja purjehdus oli vaarallinen, ja paaston aika oli jo kulunut, neuvoi Paavali heitä,"],[27,10,"Sanoen: armaat miehet! minä näen, että purjehdus tulee vaaralliseksi ja vahingolliseksi, ei ainoastaan kalulle ja haahdelle, mutta myös meidän hengellemme.","Sanoen: armaat miehet! minä näen, että purjehdus tulee vaaralliseksi ja vahingolliseksi, ei ainoastaan kalulle ja haahdelle, mutta myös meidän hengellemme."],[27,11,"Mutta sadanpäämies uskoi enemmin haahdenhaltiaa ja peränpitäjää kuin Paavalin sanoja.","Mutta sadanpäämies uskoi enemmin haahdenhaltiaa ja peränpitäjää kuin Paavalin sanoja."],[27,12,"Ja kuin ei satama ollut sovelias yli talvea olla, niin he enimmitten mielistyivät siihen neuvoon, että sieltä piti laskettaman pois, jos he jollakin muotoa olisivat voineet tulla Phoinikaan talvea pitämään, joka on Kretan satama, etelälänteä ja luodepohjaa päin.","Ja kuin ei satama ollut sovelias yli talvea olla, niin he enimmitten mielistyivät siihen neuvoon, että sieltä piti laskettaman pois, jos he jollakin muotoa olisivat voineet tulla Phoinikaan talvea pitämään, joka on Kretan satama, etelälänteä ja luodepohjaa päin."],[27,13,"Mutta kuin etelätuuli rupesi puhaltamaan, luulivat he aikomisensa käyvän edes, läksivät matkaan ja purjehtivat Kretan ohitse lähempänä maata.","Mutta kuin etelätuuli rupesi puhaltamaan, luulivat he aikomisensa käyvän edes, läksivät matkaan ja purjehtivat Kretan ohitse lähempänä maata."],[27,14,"Mutta ei kauvan aikaa jälkeen löi sen päälle ankara puuskatuuli, joka itäpohjaksi kutsutaan.","Mutta ei kauvan aikaa jälkeen löi sen päälle ankara puuskatuuli, joka itäpohjaksi kutsutaan."],[27,15,"Ja kuin haaksi tuli sen valtaan eikä voinut tuulta vastaan seisoa, laskimme me sen tuulen haltuun kulkemaan.","Ja kuin haaksi tuli sen valtaan eikä voinut tuulta vastaan seisoa, laskimme me sen tuulen haltuun kulkemaan."],[27,16,"Ja kuin me tulimme yhden vähän saaren alle, joka kutsutaan Klauda, saimme me tuskalla venheesen ruveta,","Ja kuin me tulimme yhden vähän saaren alle, joka kutsutaan Klauda, saimme me tuskalla venheesen ruveta,"],[27,17,"Jonka me otimme avuksemme ja sidoimme haahteen, peljäten, ettei sen pitänyt kariin sattuman; ja he laskivat alas purheen ja antoivat kulkea.","Jonka me otimme avuksemme ja sidoimme haahteen, peljäten, ettei sen pitänyt kariin sattuman; ja he laskivat alas purheen ja antoivat kulkea."],[27,18,"Mutta koska suuri ilma kävi päälle, heittivät he toisena päivänä kalun ulos.","Mutta koska suuri ilma kävi päälle, heittivät he toisena päivänä kalun ulos."],[27,19,"Ja kolmantena päivänä heitimme me omilla käsillämme ulos haahden kaluja.","Ja kolmantena päivänä heitimme me omilla käsillämme ulos haahden kaluja."],[27,20,"Mutta kuin emme monena päivänä aurinkoa emmekä tähtiä nähneet, eikä vähin ilma meidän päällemme käynyt, niin meidän elämämme toivo oli jo kaikki pois.","Mutta kuin emme monena päivänä aurinkoa emmekä tähtiä nähneet, eikä vähin ilma meidän päällemme käynyt, niin meidän elämämme toivo oli jo kaikki pois."],[27,21,"Ja koska me kauvan aikaa olimme syömättä, silloin seisoi Paavali heidän keskellänsä ja sanoi: miehet, teidän olis tullut minua kuulla ja ei Kretasta laskea ulos, että me olisimme välttäneet tainkaltaisen tuskan ja vahingon.","Ja koska me kauvan aikaa olimme syömättä, silloin seisoi Paavali heidän keskellänsä ja sanoi: miehet, teidän olis tullut minua kuulla ja ei Kretasta laskea ulos, että me olisimme välttäneet tainkaltaisen tuskan ja vahingon."],[27,22,"Ja nytkin minä neuvon teitä, olkaat hyvässä uskalluksesta, ei teistä yksikään huku, vaan ainoastaan haaksi.","Ja nytkin minä neuvon teitä, olkaat hyvässä uskalluksesta, ei teistä yksikään huku, vaan ainoastaan haaksi."],[27,23,"Sillä minun tykönäni seisoi tänä yönä Jumalan enkeli, jonka oma minä olen, jota minä myös palvelen,","Sillä minun tykönäni seisoi tänä yönä Jumalan enkeli, jonka oma minä olen, jota minä myös palvelen,"],[27,24,"Ja sanoi: älä pelkää, Paavali, sinä pitää keisarin eteen asetettaman, ja katso, Jumala on sinulle lahjoittanut ne kaikki, jotka sinun kanssas purjehtivat.","Ja sanoi: älä pelkää, Paavali, sinä pitää keisarin eteen asetettaman, ja katso, Jumala on sinulle lahjoittanut ne kaikki, jotka sinun kanssas purjehtivat."],[27,25,"Sentähden miehet, olkaat hyvässä uskalluksessa! Sillä minä uskon Jumalan päälle, että se niin tapahtuu, kuin minulle sanottu on.","Sentähden miehet, olkaat hyvässä uskalluksessa! Sillä minä uskon Jumalan päälle, että se niin tapahtuu, kuin minulle sanottu on."],[27,26,"Mutta yhteen luotoon pitää meidän kulkeman.","Mutta yhteen luotoon pitää meidän kulkeman."],[27,27,"Kuin neljästoistakymmenes yö joutui, ja me ajeltiin Adrian merellä, äkkäsivät haaksimiehet puoliyön aikaan jonkun maan heitä lähestyvän,","Kuin neljästoistakymmenes yö joutui, ja me ajeltiin Adrian merellä, äkkäsivät haaksimiehet puoliyön aikaan jonkun maan heitä lähestyvän,"],[27,28,"Ja heittivät ulos luotirihman ja löysivät kaksikymmentä kyynärää syväksi; kuin he tulivat vähää edemmä, heittivät he taas ulos luotirihman ja löysivät viisitoistakymmentä kyynärää.","Ja heittivät ulos luotirihman ja löysivät kaksikymmentä kyynärää syväksi; kuin he tulivat vähää edemmä, heittivät he taas ulos luotirihman ja löysivät viisitoistakymmentä kyynärää."],[27,29,"Niin he pelkäsivät joutuvansa johonkuhun kariin, ja heittivät ulos neljä ankkuria perältä haahta, ja toivoivat päivän koittavan.","Niin he pelkäsivät joutuvansa johonkuhun kariin, ja heittivät ulos neljä ankkuria perältä haahta, ja toivoivat päivän koittavan."],[27,30,"Mutta kuin haaksimiehet pyysivät haahdesta paeta, ja lykkäsivät venheen mereen, sanoen että he tahtoivat ankkuria viedä ulos haahden keulasta,","Mutta kuin haaksimiehet pyysivät haahdesta paeta, ja lykkäsivät venheen mereen, sanoen että he tahtoivat ankkuria viedä ulos haahden keulasta,"],[27,31,"Niin Paavali sanoi sadanpäämiehelle ja sotamiehille: ellei nämät haahdessa pysy, ette suinkaan henkeänne pelasta.","Niin Paavali sanoi sadanpäämiehelle ja sotamiehille: ellei nämät haahdessa pysy, ette suinkaan henkeänne pelasta."],[27,32,"Niin sotamiehet hakkasivat poikki venheen pestin, ja antoivat sen pudota.","Niin sotamiehet hakkasivat poikki venheen pestin, ja antoivat sen pudota."],[27,33,"Ja kuin päivä rupesi valkenemaan, neuvoi Paavali kaikkia heitä ruokaa ottamaan, sanoen: tänäpänä on neljästoistakymmenes päivä, kuin te odottaneet olette, ja syömättä olleet, ja ette mitään ole tykönne ottaneet:","Ja kuin päivä rupesi valkenemaan, neuvoi Paavali kaikkia heitä ruokaa ottamaan, sanoen: tänäpänä on neljästoistakymmenes päivä, kuin te odottaneet olette, ja syömättä olleet, ja ette mitään ole tykönne ottaneet:"],[27,34,"Sentähden neuvon minä teitä ruokaa ottamaan, joka on teille terveydeksi; sillä ei yhdenkään teidän päästänne ole hiuskarva putoova.","Sentähden neuvon minä teitä ruokaa ottamaan, joka on teille terveydeksi; sillä ei yhdenkään teidän päästänne ole hiuskarva putoova."],[27,35,"Ja kuin hän sen oli sanonut, otti hän leivän, ja kiitti Jumalaa kaikkein nähden, mursi, ja rupesi syömään.","Ja kuin hän sen oli sanonut, otti hän leivän, ja kiitti Jumalaa kaikkein nähden, mursi, ja rupesi syömään."],[27,36,"Ja kuin he kaikki itsensä vahvistivat, rupesivat he myös syömään.","Ja kuin he kaikki itsensä vahvistivat, rupesivat he myös syömään."],[27,37,"Mutta meitä oli haahdessa kaikki yhteen kaksisataa ja kuusikahdeksattakymmentä henkeä.","Mutta meitä oli haahdessa kaikki yhteen kaksisataa ja kuusikahdeksattakymmentä henkeä."],[27,38,"Ja kuin he olivat ravitut, kevensivät he haahden ja heittivät jyvät mereen.","Ja kuin he olivat ravitut, kevensivät he haahden ja heittivät jyvät mereen."],[27,39,"Mutta kuin päivä tuli, niin ei he tunteneet maata, mutta havaitsivat lahden, jossa ranta oli, jonka päälle he mielivät antaa haahden ajaa, jos he olisivat taitaneet.","Mutta kuin päivä tuli, niin ei he tunteneet maata, mutta havaitsivat lahden, jossa ranta oli, jonka päälle he mielivät antaa haahden ajaa, jos he olisivat taitaneet."],[27,40,"Ja kuin he ankkurit olivat ottaneet ylös, läksivät he mereen ja päästivät perälautain siteet, ja asettivat purjeen tuuleen, ja antoivat juosta rantaa kohden.","Ja kuin he ankkurit olivat ottaneet ylös, läksivät he mereen ja päästivät perälautain siteet, ja asettivat purjeen tuuleen, ja antoivat juosta rantaa kohden."],[27,41,"Vaan kuin me tulimme yhden niemen tykö, loukkaantui haaksi, ja sen keula tarttui kiinni ja jäi seisomaan, mutta kastari tuli valallensa aaltoin väestä.","Vaan kuin me tulimme yhden niemen tykö, loukkaantui haaksi, ja sen keula tarttui kiinni ja jäi seisomaan, mutta kastari tuli valallensa aaltoin väestä."],[27,42,"Mutta sotamiesten neuvo oli vankeja tappaa, ettei joku uiden olisi karannut pois.","Mutta sotamiesten neuvo oli vankeja tappaa, ettei joku uiden olisi karannut pois."],[27,43,"Mutta sadanpäämies tahtoi Paavalia vapahtaa, ja esti heidät siitä neuvosta, ja käski niitä, jotka uida taisivat, että he ensin itsensä antaisivat ulos ja maalle pääsisivät.","Mutta sadanpäämies tahtoi Paavalia vapahtaa, ja esti heidät siitä neuvosta, ja käski niitä, jotka uida taisivat, että he ensin itsensä antaisivat ulos ja maalle pääsisivät."],[27,44,"Mutta muita lautain päällä, muutamia taas haahden kappaleilla (kulkea). Ja niin tapahtui, että jokainen tuli hengissä maalle.","Mutta muita lautain päällä, muutamia taas haahden kappaleilla (kulkea). Ja niin tapahtui, että jokainen tuli hengissä maalle."],[28,1,"Ja kuin he terveinä päässeet olivat, tunsivat he, että se luoto Meliteksi kutsutaan.","Ja kuin he terveinä päässeet olivat, tunsivat he, että se luoto Meliteksi kutsutaan."],[28,2,"Mutta se kansa osoitti meille ei vähintä rakkauden halua; sillä he tekivät meille valkian, ja kaikki ottivat vastaan meidät, sen sateen ja vilun tähden, joka meidän päällemme tuli.","Mutta se kansa osoitti meille ei vähintä rakkauden halua; sillä he tekivät meille valkian, ja kaikki ottivat vastaan meidät, sen sateen ja vilun tähden, joka meidän päällemme tuli."],[28,3,"Mutta kuin Paavali kokosi kasan risuja ja pani valkialle, tuli yksi kärme palavuudesta ja karkasi hänen käteensä.","Mutta kuin Paavali kokosi kasan risuja ja pani valkialle, tuli yksi kärme palavuudesta ja karkasi hänen käteensä."],[28,4,"Kuin kansa näki kärmeen riippuvan hänen kädessänsä, sanoivat he keskenänsä: kaiketi tämä ihminen on miehentappaja, jota ei koston jumalatar saali elää, vaikka hän on meren hädästä päässyt.","Kuin kansa näki kärmeen riippuvan hänen kädessänsä, sanoivat he keskenänsä: kaiketi tämä ihminen on miehentappaja, jota ei koston jumalatar saali elää, vaikka hän on meren hädästä päässyt."],[28,5,"Mutta hän pudisti kärmeen tuleen eikä mitään kipua tuntenut.","Mutta hän pudisti kärmeen tuleen eikä mitään kipua tuntenut."],[28,6,"Mutta he odottivat hänen ajettuvan eli kohta maahan lankeevan ja kuolevan; vaan kuin he kauvan sitä odottivat ja näkivät, ettei hänelle mitään vahinkoa tapahtunut, saivat he toisen mielen ja sanoivat hänen jumalaksi.","Mutta he odottivat hänen ajettuvan eli kohta maahan lankeevan ja kuolevan; vaan kuin he kauvan sitä odottivat ja näkivät, ettei hänelle mitään vahinkoa tapahtunut, saivat he toisen mielen ja sanoivat hänen jumalaksi."],[28,7,"Mutta vähän matkan takana siitä olivat sen luodon päämiehellä, jonka nimi oli Publius, maakartanot, joka meitä otti vastaan ja piti meidän kunniallisesti vierainansa kolme päivää.","Mutta vähän matkan takana siitä olivat sen luodon päämiehellä, jonka nimi oli Publius, maakartanot, joka meitä otti vastaan ja piti meidän kunniallisesti vierainansa kolme päivää."],[28,8,"Niin tapahtui, että Publiuksen isä sairasti vilutautia ja vatsankipua, jonka tykö Paavali meni, rukoili ja pani kätensä hänen päällensä, ja paransi hänen.","Niin tapahtui, että Publiuksen isä sairasti vilutautia ja vatsankipua, jonka tykö Paavali meni, rukoili ja pani kätensä hänen päällensä, ja paransi hänen."],[28,9,"Kuin siis se oli tehty, tulivat myös muut sairaat siitä luodosta, ja parannettiin,","Kuin siis se oli tehty, tulivat myös muut sairaat siitä luodosta, ja parannettiin,"],[28,10,"Jotka myös meille tekivät paljon kunniaa, ja kuin me sieltä purjehdimme, panivat he meidän myötämme, mitä me tarvitsimme.","Jotka myös meille tekivät paljon kunniaa, ja kuin me sieltä purjehdimme, panivat he meidän myötämme, mitä me tarvitsimme."],[28,11,"Mutta kolmen kuukauden perästä purjehdimme me sieltä Aleksandrian haahdessa, joka sen luodon tykönä oli talvea pitänyt, jolla oli lipun merkki kaksoinen.","Mutta kolmen kuukauden perästä purjehdimme me sieltä Aleksandrian haahdessa, joka sen luodon tykönä oli talvea pitänyt, jolla oli lipun merkki kaksoinen."],[28,12,"Ja kuin me tulimme Syrakusaan, olimme me siellä kolme päivää.","Ja kuin me tulimme Syrakusaan, olimme me siellä kolme päivää."],[28,13,"Ja kuin me sieltä ympäri purjehdimme ja tulimme Regioon, ja päivää jälkeen puhalsi lounatuuli, niin että me toisena päivänä tulimme Puteoliin.","Ja kuin me sieltä ympäri purjehdimme ja tulimme Regioon, ja päivää jälkeen puhalsi lounatuuli, niin että me toisena päivänä tulimme Puteoliin."],[28,14,"Kuin me sieltä löysimme veljet, niin meitä rukoiltiin olemaan heidän tykönänsä seitsemän päivää; ja niin me tulimme Roomiin.","Kuin me sieltä löysimme veljet, niin meitä rukoiltiin olemaan heidän tykönänsä seitsemän päivää; ja niin me tulimme Roomiin."],[28,15,"Ja kuin siellä veljet kuulivat meistä, tulivat he meitä vastaan hamaan Appiforuun ja Tretaberniin. Kuin Paavali heidät näki, kiitti hän Jumalaa ja sai uskalluksen.","Ja kuin siellä veljet kuulivat meistä, tulivat he meitä vastaan hamaan Appiforuun ja Tretaberniin. Kuin Paavali heidät näki, kiitti hän Jumalaa ja sai uskalluksen."],[28,16,"Mutta kuin me Roomiin tulimme, antoi sadanpäämies vangit sodanpäämiehen haltuun. Mutta Paavali sallittiin olevan itsellänsä yhden sotamiehen kanssa, joka hänestä otti vaarin.","Mutta kuin me Roomiin tulimme, antoi sadanpäämies vangit sodanpäämiehen haltuun. Mutta Paavali sallittiin olevan itsellänsä yhden sotamiehen kanssa, joka hänestä otti vaarin."],[28,17,"Niin tapahtui kolmen päivän jälkeen, että Paavali kutsui kokoon ylimmäiset Juudalaisista. Ja kuin he tulivat kokoon, sanoi hän heille: miehet, veljet, vaikka en minä ole mitään tehnyt kansaa eli isäin säätyjä vastaan, kuitenkin olen minä sidottuna annettu Jerusalemista Roomalaisten käsiin,","Niin tapahtui kolmen päivän jälkeen, että Paavali kutsui kokoon ylimmäiset Juudalaisista. Ja kuin he tulivat kokoon, sanoi hän heille: miehet, veljet, vaikka en minä ole mitään tehnyt kansaa eli isäin säätyjä vastaan, kuitenkin olen minä sidottuna annettu Jerusalemista Roomalaisten käsiin,"],[28,18,"Jotka, koska he olivat minun tutkineet, tahtoivat minua päästää, ettei yhtään hengen rikosta minussa ole.","Jotka, koska he olivat minun tutkineet, tahtoivat minua päästää, ettei yhtään hengen rikosta minussa ole."],[28,19,"Mutta koska Juudalaiset sitä vastaan sanoivat, täytyi minun turvata keisariin, ei niin, että minulla olis jotakin kantamista minun kansani päälle.","Mutta koska Juudalaiset sitä vastaan sanoivat, täytyi minun turvata keisariin, ei niin, että minulla olis jotakin kantamista minun kansani päälle."],[28,20,"Tämän syyn tähden olen minä kutsunut teitä, että minä saisin teitä nähdä ja puhutella; sillä minä olen Israelin toivon tähden tällä kahleella sidottu.","Tämän syyn tähden olen minä kutsunut teitä, että minä saisin teitä nähdä ja puhutella; sillä minä olen Israelin toivon tähden tällä kahleella sidottu."],[28,21,"Niin he sanoivat hänelle: emme ole kirjaa saaneet sinusta Juudeasta, ei myös yksikään veljistä ole sieltä tullut ja meille ilmoittanut, eikä jotakuta pahuutta sinusta puhunut.","Niin he sanoivat hänelle: emme ole kirjaa saaneet sinusta Juudeasta, ei myös yksikään veljistä ole sieltä tullut ja meille ilmoittanut, eikä jotakuta pahuutta sinusta puhunut."],[28,22,"Mutta me tahdomme sinulta kuulla, mitä sinun mielessäs on; sillä tästä seurasta on meille tiettävä, että sitä vastaan joka paikassa sanotaan.","Mutta me tahdomme sinulta kuulla, mitä sinun mielessäs on; sillä tästä seurasta on meille tiettävä, että sitä vastaan joka paikassa sanotaan."],[28,23,"Ja kuin he olivat hänelle päivän määränneet, niin tuli monta hänen tykönsä majaan, joille hän selitti ja todisti Jumalan valtakunnasta, ja opetti heille Jesuksesta, Moseksen laista ja prophetaista huomenesta ehtoosen asti.","Ja kuin he olivat hänelle päivän määränneet, niin tuli monta hänen tykönsä majaan, joille hän selitti ja todisti Jumalan valtakunnasta, ja opetti heille Jesuksesta, Moseksen laista ja prophetaista huomenesta ehtoosen asti."],[28,24,"Ja muutamat uskoivat ne, mitkä sanottiin, mutta muutamat ei uskoneetkaan.","Ja muutamat uskoivat ne, mitkä sanottiin, mutta muutamat ei uskoneetkaan."],[28,25,"Mutta kuin he tulivat riitaisiksi keskenänsä, menivät he matkaansa, että Paavali oli yhden sanan sanonut: Pyhä Henki on oikein meidän isillemme Jesaias prophetan kautta puhunut,","Mutta kuin he tulivat riitaisiksi keskenänsä, menivät he matkaansa, että Paavali oli yhden sanan sanonut: Pyhä Henki on oikein meidän isillemme Jesaias prophetan kautta puhunut,"],[28,26,"Sanoen: mene tämän kansan tykö ja sano: korvillanne pitää teidän kuuleman ja ei ymmärtämän, ja silmillänne pitää teidän näkemän ja ei tunteman;","Sanoen: mene tämän kansan tykö ja sano: korvillanne pitää teidän kuuleman ja ei ymmärtämän, ja silmillänne pitää teidän näkemän ja ei tunteman;"],[28,27,"Sillä tämän kansan sydän on kovettunut, ja he kuulevat raskaasti korvillansa, ja panevat silmänsä umpeen, ettei he joskus silmillänsä näkisi, eikä korvillansa kuulisi, ei myös ymmärtäisi sydämellänsä, eikä kääntäisi heitänsä, että minä heitä parantaisin.","Sillä tämän kansan sydän on kovettunut, ja he kuulevat raskaasti korvillansa, ja panevat silmänsä umpeen, ettei he joskus silmillänsä näkisi, eikä korvillansa kuulisi, ei myös ymmärtäisi sydämellänsä, eikä kääntäisi heitänsä, että minä heitä parantaisin."],[28,28,"Niin olkoon se teille tiettävä, että tämä Jumalan autuus on lähetetty pakanoille, ja he myös sen kuulevat.","Niin olkoon se teille tiettävä, että tämä Jumalan autuus on lähetetty pakanoille, ja he myös sen kuulevat."],[28,29,"Ja kuin hän näitä puhunut oli, läksivät Juudalaiset pois ja riitelivät paljo keskenänsä.","Ja kuin hän näitä puhunut oli, läksivät Juudalaiset pois ja riitelivät paljo keskenänsä."],[28,30,"Mutta Paavali oli täyttä kaksi ajastaikaa omassa palkkahuoneessansa ja otti kaikki vastaan, jotka hänen tykönsä tulivat,","Mutta Paavali oli täyttä kaksi ajastaikaa omassa palkkahuoneessansa ja otti kaikki vastaan, jotka hänen tykönsä tulivat,"],[28,31,"Ja saarnasi Jumalan valtakunnasta, ja opetti Herrasta Jesuksesta Kristuksesta kaikella uskalluksella, ja ei häntä yksikään kieltänyt.","Ja saarnasi Jumalan valtakunnasta, ja opetti Herrasta Jesuksesta Kristuksesta kaikella uskalluksella, ja ei häntä yksikään kieltänyt."]]}};